// More spaced-review questions, so every concept has 8 to 12 multiple choice questions and a review recalls the idea
// instead of recognising the question (learning review, Oct 18: /mnt/project-files/learning-review/assessment.md).
// Same shape and rules as the rest of the bank (docs/question-style.md); `node tools/question_lint.js` checks them.
// They join each concept's pool through S.questionsFor in js/state.js, so dungeon, town and tide-post reviews all use them.
SD.questions.push(
  // delivery: Delivery Framework
  { id: 'qb-delivery1', c: 'delivery', type: 'mc', q: 'Designing a ride-sharing app, you list 15 features in the first few minutes. What do you do next?', opts: ['Agree with the interviewer on the top three to design', 'Sketch all fifteen at a shallow level so none is missed', 'Estimate the traffic for every feature before choosing', 'Pick a database that fits the feature with the most writes'], a: 0, no: [null, 'Breadth everywhere leaves no time for depth, and depth is where the signal is. Scope down first.', 'Estimation helps only when a number changes a decision. Choosing features is a product call, not a maths one.', 'Choosing storage is part of the design, which comes after requirements are pinned down.'], why: 'Requirements come first, and part of that step is scoping: agree the few core features with the interviewer so there is time to design them well and go deep.' },
  { id: 'qb-delivery2', c: 'delivery', type: 'mc', q: 'In the core entities step for a URL shortener, what should you write down?', opts: ['The tables, columns and indexes for each entity', 'The endpoints for creating and following links', 'The nouns: users, short links and clicks', 'The services: a write path and a redirect path'], a: 2, no: ['Full schemas are detail you refine later, during the design and deep dives. Here you only name what the system stores.', 'Endpoints are the next step, the API, which is built on top of the entities.', null, 'Services and data flow belong to the high-level design, after the API.'], why: 'Core entities are the main things the system stores and moves around. Naming them early gives the API and the design a shared vocabulary.' },
  { id: 'qb-delivery3', c: 'delivery', type: 'mc', q: 'When is the right moment to start deep dives?', opts: ['Once the API covers every edge case and error code', 'As soon as you spot the hardest part of the problem', 'Right after estimating every number in the system', 'Once a simple design covers every core feature'], a: 3, no: ['The API is a sketch of the main calls. Polishing error codes burns time on low-signal detail.', 'Diving into one part before the rest exists leaves an unfinished design that cannot be judged end to end.', 'Estimation is a tool for specific decisions, not a gate before design.', null], why: 'Get a simple high-level design that works for all the functional requirements first, then use deep dives to meet the non-functional ones: scale, latency, failures.' },
  { id: 'qb-delivery4', c: 'delivery', type: 'mc', q: 'In the API step for "post a tweet", where should the server get the author\'s identity from?', opts: ['A userId field in the JSON request body', 'The auth token sent in the request header', 'A user ID in the path, like /users/{id}/tweets', 'The user the server remembers from the last call'], a: 1, no: ['Any client can put any ID in the body, so a user could post as someone else.', null, 'A client can edit the path too. Path IDs suit reading another user\'s public data, not proving who you are.', 'HTTP requests are independent, and behind a load balancer the next call may hit a different server.'], why: 'The caller\'s identity comes from authentication (a session token or JWT in a header), never from a field the client can set freely.' },
  { id: 'qb-delivery5', c: 'delivery', type: 'mc', q: 'How should you state non-functional requirements?', opts: ['As broad goals: scalable, reliable and fast', 'As a stack: Redis for speed, Kafka for scale', 'As numbers, like redirects under 100 ms at p99', 'As one CAP choice that applies to the whole system'], a: 2, no: ['Every system wants these, so they drive no decision. Put numbers and scope on them.', 'Technologies are design choices that should follow from the requirements, not stand in for them.', null, 'Consistency needs differ by feature: a booking must be consistent while a feed can be stale.'], why: 'Concrete, measurable targets (latency, availability, scale, which data must be consistent) are what the deep dives later have to meet.' },
  { id: 'qb-delivery6', c: 'delivery', type: 'mc', q: 'Why define the API before drawing the high-level design?', opts: ['The endpoints show which flows the design must serve', 'The API fixes the database schema, so it must come first', 'Interviewers grade mostly on clean endpoint naming', 'Adding endpoints later forces a breaking v2 of the API'], a: 0, no: [null, 'The API is the external contract. The storage schema behind it can differ and is chosen during the design.', 'Naming matters little. The API earns its place by framing what the design has to do.', 'New endpoints are additive and do not break clients. Versioning is for changing existing contracts.'], why: 'Each endpoint is a request path the high-level design has to carry from client to storage and back, so the API turns requirements into flows you can draw.' },
  // estimation: Back-of-Envelope Math
  { id: 'qb-estimation1', c: 'estimation', type: 'mc', q: '10M daily users each upload one 2 MB photo and view 100. Which number dominates the storage plan?', opts: ['The metadata, about 1 KB per photo', 'The view logs, at 100 views per photo', 'The thumbnails, a tenth of each photo', 'The photo bytes, about 20 TB a day'], a: 3, no: ['Ten million rows of 1 KB is about 10 GB a day, a rounding error next to the photos.', 'A billion views at around 100 bytes each is about 100 GB a day: real, but far smaller.', 'At a tenth of the size, thumbnails add about 2 TB a day, still a tenth of the photos.', null], why: '10 million photos at 2 MB each is about 20 TB a day, so the media bytes decide the storage design (object storage, a CDN). The view count matters for the read path, not for storage.' },
  { id: 'qb-estimation2', c: 'estimation', type: 'mc', q: 'When is back-of-envelope math worth the time in a design interview?', opts: ['Up front, in detail, for every resource in the system', 'When the result changes a decision, like sharding', 'At the end, to justify the design you already drew', 'When the interviewer supplies exact traffic figures'], a: 1, no: ['Detailed numbers that change nothing use up time you need for the design.', null, 'Numbers should shape the design. Estimating afterwards only decorates it.', 'You can assume reasonable figures and say so. Waiting for exact data stalls you.'], why: 'Estimate when the answer moves a choice: whether data fits one machine, whether one node can take the writes, whether you need a cache.' },
  { id: 'qb-estimation3', c: 'estimation', type: 'mc', q: '50M writes a day, with peak at 3x the average. Can one well-tuned Postgres primary take the writes?', opts: ['Yes: about 1,700 writes a second at peak fits', 'No: 50M writes a day calls for sharding at once', 'No: peak comes to around 150,000 writes a second', 'Yes, since adding replicas spreads out the writes'], a: 0, no: [null, 'Per-day totals sound huge. Divide by 10^5 seconds first: it is only hundreds a second on average.', 'That divides by 1,000 instead of by about 100,000: a day is roughly 10^5 seconds.', 'Replicas copy every write, so they scale reads, not writes. Only sharding spreads writes.'], why: '50M / 86,400 is about 580 a second (call it 500 with 10^5), so under 2,000 at peak, well within one good SQL node. Converting per-day numbers to per-second ones often shows no sharding is needed.' },
  { id: 'qb-estimation4', c: 'estimation', type: 'mc', q: 'Your estimate says the whole dataset reaches 2 TB after five years. What does that tell you?', opts: ['It calls for a distributed store like Cassandra', 'It must live in memory for reads to stay fast', 'It fits on one machine, so size is no reason to shard', 'It is too small to be worth adding any replicas'], a: 2, no: ['2 TB fits on one disk. Wide-column stores earn their place with huge write volume, not modest size.', '2 TB of RAM is costly. Cache the hot set in memory and keep the rest on SSD.', null, 'Replicas are for availability and read scaling, not for size, so even small data wants them.'], why: 'A single modern node holds several TB on SSD, so 2 TB does not force sharding. You may still shard for write throughput, but not for storage.' },
  // vscale: Vertical vs Horizontal Scaling
  { id: 'qb-vscale1', c: 'vscale', type: 'mc', q: 'What is the main cost horizontal scaling adds that vertical scaling does not?', opts: ['A hard ceiling on what one node can ever handle', 'A downtime window each time you add capacity', 'One machine whose failure takes the whole system down', 'Coordination: balancing, shared state, partial failure'], a: 3, no: ['The ceiling is vertical scaling\'s problem. Horizontal scaling gets around it by adding machines.', 'Adding servers behind a balancer needs no downtime. Resizing one big box often does.', 'That is the single point of failure of a lone big machine. More machines remove it.', null], why: 'Many machines need a load balancer, stateless servers or shared state, and handling of machines that fail on their own. That complexity is the price of scaling out.' },
  { id: 'qb-vscale2', c: 'vscale', type: 'mc', q: 'You move your database to a bigger cloud instance size. What do you usually have to plan for?', opts: ['Resharding the data across the extra cores', 'A restart: a short outage or a failover', 'Rewriting queries so they run in parallel', 'Making the app servers stateless beforehand'], a: 1, no: ['Cores share one machine\'s memory and disk. Sharding splits data across machines, not cores.', null, 'The database plans parallel work itself. Bigger hardware needs no query changes.', 'Statelessness is what horizontal scaling of the app tier needs. A database resize does not depend on it.'], why: 'Vertical scaling is simple but changing machine size usually means a restart, so you plan a maintenance window or fail over to a resized replica.' },
  { id: 'qb-vscale3', c: 'vscale', type: 'mc', q: 'Your app server keeps each user\'s shopping cart in its own memory. You want to scale out to many servers. What must change first?', opts: ['Buy a box with far more RAM to hold all the carts', 'Add read replicas of the cart data', 'Move the carts into a shared store like Redis', 'Cache the carts at the CDN near users'], a: 2, no: ['That is scaling up. It postpones the problem and keeps one point of failure.', 'Replicas copy a database. The carts are in process memory, so there is nothing to replicate.', null, 'Carts are private and change often, which is a poor fit for a shared edge cache.'], why: 'Horizontal scaling needs stateless servers: any server must be able to handle any request, so per-user state has to live outside them.' },
  { id: 'qb-vscale4', c: 'vscale', type: 'mc', q: 'A Redis node is pinned at 100% of one CPU core while the other 15 cores sit idle. Will a 64-core machine help?', opts: ['Not much: commands run on one thread, so shard it', 'Yes: it runs four times as many commands at once', 'Yes: more RAM lets it cache more and reply sooner', 'Not much: add a replica to take half the writes'], a: 0, no: [null, 'Redis executes commands on a single thread, so extra cores mostly sit idle.', 'Memory is not the bottleneck here; one busy core is.', 'Replicas copy every write. They can take reads, but writes still go to one primary.'], why: 'A bigger box only helps if the software can use it. Redis is CPU-bound on one core, so the fix is horizontal: shard keys across several Redis nodes.' },
  { id: 'qb-vscale5', c: 'vscale', type: 'mc', q: 'Stack Overflow ran for years on a few large SQL servers. Why could that work?', opts: ['The data was sharded across those servers by tag', 'SQL Server spreads writes over its replicas itself', 'Traffic was too light to need any caching at all', 'The load fit, and big boxes avoid distributed pain'], a: 3, no: ['They did not shard. The point was that one well-equipped server held it all.', 'Replicas copy writes rather than share them. Writes still went to one primary.', 'They cached heavily, with Redis and in-process caches. Caching is what let a few servers keep up.', null], why: 'Vertical scaling is the right move while one bigger machine still fits the load. It avoids sharding, cross-node coordination and partial failures.' },
  { id: 'qb-vscale6', c: 'vscale', type: 'mc', q: 'A stateless web tier runs on one large server. Traffic will grow 10x this year. What is the better plan?', opts: ['Move to the largest instance size the provider sells', 'Put several smaller servers behind a load balancer', 'Shard the database now, before the web tier grows', 'Rewrite the tier as serverless functions per route'], a: 1, no: ['That has a ceiling a 10x jump may hit, and it stays one point of failure.', null, 'The web tier is the part growing. Sharding the database early adds complexity before it is needed.', 'Serverless can scale, but a rewrite is a big cost when stateless servers already scale out easily.'], why: 'The tier is already stateless, so scaling out is cheap: add servers behind a load balancer, gain headroom past one machine\'s ceiling and survive any one server dying.' },
  // stateless: Stateless Services
  { id: 'qb-stateless1', c: 'stateless', type: 'mc', q: 'Sessions live in Redis. You do a rolling deploy, restarting app servers one at a time. What happens to logged-in users?', opts: ['They stay logged in: any server reads their session', 'Those on a restarting server are logged out', 'They must stay pinned to old servers until it ends', 'Their sessions are copied to each new server at boot'], a: 0, no: [null, 'That happens when sessions live in server memory. Here they live in Redis, which keeps running.', 'Pinning is what sticky in-memory sessions need. With a shared store, any server will do.', 'Nothing needs copying: each server reads sessions from Redis on demand.'], why: 'With state outside the app servers, a restart loses nothing. The balancer drains the old server and the next request reads the session from Redis on another one.' },
  { id: 'qb-stateless2', c: 'stateless', type: 'mc', q: 'Each app server keeps a local in-memory cache of the product catalogue. Does that break statelessness?', opts: ['Yes: any data in memory makes a server stateful', 'Yes: users must stick to one server to use it', 'No: losing it costs only speed, not correctness', 'No, as long as every server holds the same copy'], a: 2, no: ['What matters is whether losing the data loses anything real. A cache can be rebuilt from the source.', 'Every server caches the catalogue, so any server serves it. Stickiness is only needed for per-user state.', null, 'Copies can differ briefly as entries expire at different times. Statelessness does not require them to match.'], why: 'A server is stateless if any request can go to any server and a restart loses nothing that matters. A rebuildable cache meets both; user sessions in memory do not.' },
  { id: 'qb-stateless3', c: 'stateless', type: 'mc', q: 'Chat servers hold open WebSockets, so they cannot be fully stateless. How do you limit the damage?', opts: ['Spread the sockets evenly with round robin', 'Keep each chat\'s history on its socket\'s server', 'Swap the WebSockets for sticky HTTP sessions instead', 'Keep only the socket there; data in shared stores'], a: 3, no: ['How sockets are spread does not change what is lost when a server dies. Least connections suits long-lived sockets anyway.', 'History would vanish or go missing when the user reconnects to another server.', 'Sticky sessions pin users to servers too, which is the same state problem in another form.', null], why: 'The open connection is the only thing tied to one server. Message history, presence and routing live in shared stores, so a dropped client reconnects anywhere and loses nothing.' },
  // lb: Load Balancing
  { id: 'qb-lb1', c: 'lb', type: 'mc', q: 'You route by hash(user ID) mod N so each user\'s local cache stays warm. You add an 11th server to 10. What happens?', opts: ['Only about a tenth of users move, all to the new server', 'Most users switch servers, and their caches go cold', 'No users move until the old servers restart', 'The new server gets no traffic until it warms up'], a: 1, no: ['That is consistent hashing, which moves only about 1/N of keys when a node joins.', null, 'The balancer applies the new N at once. Restarts play no part.', 'Plain mod N hashing has no warm-up step. It sends the new server its share at once.'], why: 'Changing N in mod N hashing remaps almost every key, so most users land on a server with a cold cache. Consistent hashing limits the move to about one key in N.' },
  { id: 'qb-lb2', c: 'lb', type: 'mc', q: 'Every request now passes through your one load balancer. What is the standard way to stop it being a single point of failure?', opts: ['Health checks that ping the balancer itself', 'Sticky sessions so users keep their server', 'An active-passive pair sharing a floating IP', 'A larger balancer instance with more headroom'], a: 2, no: ['A check can spot a dead balancer, but something must still take over its traffic.', 'Stickiness is about which backend a user hits. It does nothing if the balancer dies.', null, 'A bigger box handles more load but is still one machine that can fail.'], why: 'Run a second balancer on standby. When the active one fails, the standby takes over the shared virtual IP, so clients keep the same address.' },
  // cdn: CDN
  { id: 'qb-cdn1', c: 'cdn', type: 'mc', q: 'You ship a new app.js several times a week but want edges and browsers to cache it for a year. How?', opts: ['Put a content hash in the name, like app.3f9a.js', 'Set max-age to 60 seconds so changes show fast', 'Purge the CDN at every edge after each deploy goes out', 'Send Cache-Control: no-store with the bundle'], a: 0, no: [null, 'Short TTLs send most requests back to the edge or origin, giving up most of the benefit of caching.', 'A purge clears the edges, but browsers that cached the file keep the old one.', 'That turns off caching entirely. It suits private, sensitive responses.'], why: 'A new file name for each version means no cache ever holds a stale copy under the new name, so the old one can be cached for a year safely.' },
  { id: 'qb-cdn2', c: 'cdn', type: 'mc', q: 'Paid course videos must only play for enrolled users. Can they still be served through the CDN?', opts: ['No: content behind a paywall has to come from origin', 'Yes: if the video paths are long and hard to guess', 'Yes: if the CDN caches a separate copy per cookie', 'Yes: with signed URLs that expire in a few hours'], a: 3, no: ['The video bytes are the same for every buyer. Only access needs checking, and the edge can check a signature.', 'That is security by obscurity. A guessed or shared link works for anyone.', 'Varying the cache on cookies stores one copy per user, so the hit rate falls to near zero.', null], why: 'The app signs a URL for an enrolled user with an expiry, and the edge checks the signature. The same cached bytes serve everyone, and access stays controlled.' },
  { id: 'qb-cdn3', c: 'cdn', type: 'mc', q: 'A news homepage is the same for every reader but changes every minute. How should the CDN treat it?', opts: ['Skip the CDN, since pages that change cannot be cached', 'Cache it at the edge with a short TTL, like 30 s', 'Cache it per user so each reader sees fresh news', 'Serve it from read replicas placed near readers'], a: 1, no: ['Even a few seconds of caching collapses millions of requests into a few origin fetches.', null, 'A per-user key gives every reader a miss and loses the benefit of the shared page.', 'Replicas bring the database closer but the page still renders at origin. A CDN caches the finished page.'], why: 'Content that is the same for everyone can be cached briefly even if it changes often. A 30-second TTL keeps it nearly fresh while the origin serves a request every 30 seconds per edge.' },
  // herd: Cache Stampede
  { id: 'qb-herd1', c: 'herd', type: 'mc', q: 'Each of your 50 app servers coalesces requests in its own process. A hot key expires. At most how many database queries go out?', opts: ['About 50: one from each server', 'One in total, across all servers', 'One per request: about 10,000', 'None: the stale value is served'], a: 0, no: [null, 'Coalescing inside each process cannot see other servers. A single query overall needs a distributed lock.', 'That is no coalescing at all. Per-process single-flight collapses each server\'s misses into one.', 'That is serve-stale-while-revalidate, a different technique. Plain coalescing still fetches once per server.'], why: 'Single-flight merges concurrent misses within one process, so each server sends one query. Fifty queries is fine where ten thousand was not; a shared lock can bring it to one.' },
  { id: 'qb-herd2', c: 'herd', type: 'mc', q: 'You serve stale values while one request refreshes the expired key. What do you give up?', opts: ['Hit rate, as stale entries count as misses', 'Durability, as a failed refresh drops the key', 'Freshness: users see old data for a moment', 'Database consistency across your replicas'], a: 2, no: ['Stale hits are still hits. That is the point: no request waits on the database.', 'A failed refresh just keeps the old value until the next try. Nothing is lost.', null, 'This is a cache policy. It does not touch how database replicas copy data.'], why: 'Stale-while-revalidate keeps answering from cache while one refresh runs, so the database sees one query instead of a herd. The price is a short window of old data.' },
  { id: 'qb-herd3', c: 'herd', type: 'mc', q: 'Which keys suit refresh-ahead, where the cache renews a value before it expires?', opts: ['Every key in the cache, so that misses never happen', 'Keys that are written more often than read', 'Keys whose readers must not see stale data', 'A few hot keys that are costly to rebuild'], a: 3, no: ['Refreshing cold keys wastes database work on values nobody reads.', 'Keys written more than read gain little from caching at all. Write-around or no cache fits better.', 'Refresh-ahead still serves the cached copy between refreshes. Invalidate on write for those keys.', null], why: 'Refresh-ahead spends some database work to make sure a hot, expensive key never expires under load, which is exactly where a stampede would hurt.' },
  { id: 'qb-herd4', c: 'herd', type: 'mc', q: 'Your cache cluster restarts empty, and the database melts even though no single key is hot. What helps most?', opts: ['Add random jitter to the TTLs on every key', 'Warm the cache with the top keys before traffic', 'Split the hottest keys into salted copies on shards', 'Lengthen every TTL to a full day'], a: 1, no: ['Jitter staggers expiries of keys already cached. An empty cache has nothing to stagger.', null, 'Salting spreads one hot key over shards. Here the load is many keys missing at once.', 'TTLs only matter once values are in the cache. Right now nothing is.'], why: 'A cold cache is a stampede across every key. Preloading the most-read keys, or letting traffic back in gradually, keeps the database from taking the whole load at once.' },
  { id: 'qb-herd5', c: 'herd', type: 'mc', q: 'During a stampede the database slows, and the app retries every timed-out query at once. What happens?', opts: ['The retries succeed because the cache refills meanwhile', 'The load spreads out, as the retries land a bit later', 'The load grows, so the database falls further behind', 'The cache absorbs them, since retries check it first'], a: 2, no: ['The cache fills only when a query succeeds, and the retries are what keep queries failing.', 'Immediate retries land together. Exponential backoff with jitter is what spreads them out.', null, 'The key is still missing while the rebuild fails, so the retries reach the database too.'], why: 'Instant retries multiply the herd: each timeout adds another query. Back off with jitter, cap retries and coalesce, so the database can recover.' },
  { id: 'qb-herd6', c: 'herd', type: 'mc', q: 'With lock-based coalescing, one request rebuilds the key while others wait. The lock holder crashes mid-rebuild. What prevents a stall?', opts: ['A short expiry on the lock, so another takes over', 'Waiters query the database whenever the lock is busy', 'A longer TTL on the cached value itself', 'The holder writing the result to every server'], a: 0, no: [null, 'Then every waiter hits the database and the stampede is back.', 'The value has already expired; its TTL does not help the waiters now.', 'A crashed holder writes nothing. Getting the result to others is the cache\'s job.'], why: 'Give the rebuild lock a short timeout (a lease). If the holder dies, the lock lapses and the next request rebuilds the key, while the rest keep waiting or serve stale.' },
  // hotkey: Hot Keys
  { id: 'qb-hotkey1', c: 'hotkey', type: 'mc', q: 'You split a hot read key into 10 salted copies on different nodes. What new problem comes with every update?', opts: ['Reads must sum all 10 copies to get the value', 'The key\'s TTL must be cut to a tenth to cope', 'Each read needs a lock to choose a copy safely', 'All 10 copies must be updated or invalidated'], a: 3, no: ['Summing is for split counters, where each copy holds part of a total. Read copies each hold the whole value.', 'TTL length is unrelated to how many copies there are.', 'Reads pick a copy at random. No coordination is needed.', null], why: 'Copies spread the read load, but a write now touches N places, and readers may see old and new values until every copy is updated.' },
  { id: 'qb-hotkey2', c: 'hotkey', type: 'mc', q: 'On Black Friday one product page gets 30% of all your traffic. Where is that load best absorbed?', opts: ['Shard the products table by product ID', 'Cache the page at the CDN with a short TTL', 'Add more shards to the cache cluster', 'Rate-limit requests for that product page'], a: 1, no: ['One product is still one row on one shard, so sharding cannot split it.', null, 'One key lives on one shard. Extra shards stay idle.', 'Rate limiting suits abuse. Here it turns away real buyers on your busiest day.'], why: 'An edge cache spreads one hot item over many CDN locations, so the origin and its single shard see only a trickle of misses.' },
  { id: 'qb-hotkey3', c: 'hotkey', type: 'mc', q: 'Your events table\'s partition key is today\'s date. Writes slow down even though the cluster has 50 nodes. Why?', opts: ['All of today\'s writes land on one partition', 'Old dates leave too many partitions behind', 'Date strings hash poorly and pile onto shards', 'Followers lag behind the leaders on writes'], a: 0, no: [null, 'Old partitions sit idle and cost little. The problem is where the new writes go.', 'Hashing is fine. It is one value, so it maps to one partition however good the hash is.', 'Lag affects reads from followers, not the write speed on the leader.'], why: 'A partition key with one active value at a time is a hot key. Add a bucket suffix (date plus 0 to 19) so today\'s writes spread over many partitions.' },
  // replication: Replication
  { id: 'qb-replication1', c: 'replication', type: 'mc', q: 'Your async leader dies, and a replica is promoted. What can be lost?', opts: ['Nothing, as replicas confirm writes before the ack', 'Only reads that were in flight on the replicas', 'Writes the leader acked but had not yet shipped', 'All data since the last backup on that replica'], a: 2, no: ['That is synchronous replication. Async acks the client before any replica has the write.', 'Reads lose nothing; the client simply retries them.', null, 'Replicas keep applying the log continuously, so they trail by seconds, not back to the last backup.'], why: 'Async replication acks the client before followers have the write, so whatever was in the replication lag at the crash is gone. Semi-synchronous replication narrows that window.' },
  { id: 'qb-replication2', c: 'replication', type: 'mc', q: 'A user refreshes twice: first they see a new comment, then it vanishes. Reads hit random replicas. Cause and fix?', opts: ['Split brain: fence the second leader off', 'A stale cache: purge it after every new comment', 'Too few replicas: add more to cut the lag', 'Lagging replicas: pin each user to one replica'], a: 3, no: ['Split brain is two leaders taking writes. Here one write is simply visible on some replicas before others.', 'Nothing points to a cache. Different replicas at different lag explain it.', 'More replicas do not cut lag; each still applies the log at its own pace.', null], why: 'Replicas lag by different amounts, so a second read can go back in time. Monotonic reads, such as pinning each user to one replica, stop that.' },
  // cap: CAP & PACELC
  { id: 'qb-cap1', c: 'cap', type: 'mc', q: 'Which of these is a PA/EL system under PACELC: available in a partition, low latency otherwise?', opts: ['Spanner, with synchronous Paxos writes', 'Cassandra with reads and writes at ONE', 'Postgres with a synchronous standby', 'ZooKeeper, with its majority quorum'], a: 1, no: ['Spanner waits for a quorum on every write, picking consistency both in a partition and normally (PC/EC).', null, 'Each commit waits for the standby, so it trades latency for consistency (EC) and stalls if the standby is cut off.', 'ZooKeeper refuses writes without a majority, a classic CP choice that favours consistency.'], why: 'At consistency level ONE, Cassandra answers from any single replica, staying up in a partition and replying fast otherwise, at the cost of possibly stale reads.' },
  // sqlnosql: SQL vs NoSQL
  { id: 'qb-sqlnosql1', c: 'sqlnosql', type: 'mc', q: 'Orders live in Cassandra, keyed by order ID. A new page needs a customer\'s orders, newest first. What do you do?', opts: ['Filter on customer ID across all partitions', 'Join the orders table to a customers table', 'Add a table keyed by customer, sorted by time', 'Move the orders into a graph database'], a: 2, no: ['That scans every partition on every node (ALLOW FILTERING), which collapses under load.', 'Cassandra has no joins. That pattern belongs to a relational database.', null, 'Graph stores suit many-hop relationship queries, not a sorted list per customer.'], why: 'In wide-column stores you design tables around queries. A second table partitioned by customer ID and clustered by time answers this read in one partition, at the cost of writing each order twice.' },
  // idgen: Unique ID Generation
  { id: 'qb-idgen1', c: 'idgen', type: 'mc', q: 'Your shortener runs in two regions, each with its own counter. How do you keep their codes unique?', opts: ['Give each region its own range or prefix bit', 'Hash each counter value so the outputs differ', 'Use the millisecond timestamp as the code', 'Rely on base62 encoding to spread the values'], a: 0, no: [null, 'Both regions hash the same numbers to the same outputs, so collisions remain.', 'Two links made in the same millisecond collide, across regions or even within one.', 'Encoding changes how a number looks, not whether two counters produce it.'], why: 'Split the ID space: odd and even, separate ranges, or a region bit in front. Each region then counts on its own with no cross-region coordination.' },
  { id: 'qb-idgen2', c: 'idgen', type: 'mc', q: 'Users can pick custom aliases next to counter-generated codes. What must you handle?', opts: ['Nothing, since counter values never repeat', 'Aliases must be hashed before being stored', 'Clock skew between servers making aliases', 'An alias may match a future generated code'], a: 3, no: ['The counter never repeats itself, but an alias like "abc12" does not come from the counter.', 'Hashing the alias would make it unreadable, which defeats the point of choosing one.', 'Aliases come from users, not clocks, so skew plays no part.', null], why: 'A custom alias can take a code the counter later reaches. Check uniqueness on every insert, or keep aliases in a separate namespace, such as a different length or prefix.' },
  { id: 'qb-idgen3', c: 'idgen', type: 'mc', q: 'An NTP correction moves a Snowflake generator\'s clock back by 50 ms. What should it do?', opts: ['Carry on, since the sequence bits keep IDs unique', 'Wait or fail until the clock passes its last ID', 'Reset the sequence to zero and keep going', 'Switch to random UUIDv4 for those 50 ms'], a: 1, no: ['The sequence resets each millisecond, so replaying a millisecond can reproduce IDs already issued.', null, 'Restarting the sequence on a reused timestamp is exactly how duplicates appear.', 'That mixes formats, so the keys stop sorting by time and fragment the index.'], why: 'Snowflake IDs rely on time moving forward. If the clock goes back, the generator waits until it passes the last timestamp used, or errors, so no ID repeats.' },
  // redirect: 301 vs 302 Redirects
  { id: 'qb-redirect1', c: 'redirect', type: 'mc', q: 'A short link served with a 301 turns out to point at a phishing page. You change its target. Who still lands there?', opts: ['People whose browsers already cached the 301', 'Nobody, as the next click reads the new target', 'Only people whose DNS cache has not yet expired', 'Only people on CDN edges that missed the purge'], a: 0, no: [null, 'That is true for a 302. A cached 301 never comes back to ask.', 'DNS maps your domain to servers. It does not store where a short code points.', 'A purge fixes the edges, but browser caches are out of your reach.'], why: 'A 301 is permanent, so browsers cache it and skip your servers on later clicks. You cannot take it back, which is why shorteners that may need to change or block links use 302.' },
  { id: 'qb-redirect2', c: 'redirect', type: 'mc', q: 'You redirect with a 302 and send no cache headers. What does each click cost you?', opts: ['Nothing extra, as browsers keep 302s for a day', 'A full page download from your own servers', 'A round trip to your servers before the page loads', 'A new TLS certificate issued for each visitor'], a: 2, no: ['Without cache headers browsers do not keep a 302, so each click comes back to you.', 'A redirect is a tiny response with a Location header. The page itself comes from the target.', null, 'One certificate serves every visitor. TLS handshakes cost time, but nothing is issued per click.'], why: 'Every click of a 302 hits your servers, which is what lets you count it. The cost is the extra round trip for the user and the load on you.' },
  { id: 'qb-redirect3', c: 'redirect', type: 'mc', q: 'Can a 302 redirect be cached at all?', opts: ['No: the HTTP spec forbids caching any 302', 'Only by a CDN, and not by any browser', 'Only when the target URL uses HTTPS', 'Yes, if you send Cache-Control with it'], a: 3, no: ['The spec only says 302 is not cached by default. Explicit headers allow it.', 'Browsers honour Cache-Control on a 302 just as CDNs do.', 'The scheme of the target plays no part in whether a redirect is cached.', null], why: 'A 302 is not cached unless you say so, but Cache-Control: max-age lets browsers or a CDN keep it, trading some analytics for less load.' },
  { id: 'qb-redirect4', c: 'redirect', type: 'mc', q: 'You want most of the load savings of a 301 but still need to count every click. What works?', opts: ['A 301 plus a tracking pixel in its body', 'Redirect at the CDN edge and ship its logs', 'Return 304 Not Modified on every repeat click', 'A 307 so the browser keeps the method'], a: 1, no: ['Browsers follow a 301 without showing its body, so the pixel never loads.', null, 'A 304 answers a conditional request for a cached copy. It is not a redirect.', 'A 307 is temporary like a 302, so the load is the same. It exists to keep POST as POST.'], why: 'An edge that answers redirects from its own cache takes the load off your servers, and its access logs still record every click for analytics.' },
  { id: 'qb-redirect5', c: 'redirect', type: 'mc', q: 'POST /v1/orders moves to /v2/orders for good, and clients must keep sending a POST. Which status?', opts: ['301 Moved Permanently', '302 Found', '308 Permanent Redirect', '303 See Other'], a: 2, no: ['Clients may change a POST to a GET when following a 301, losing the body.', 'A 302 is temporary, and clients may also switch it to a GET.', null, 'A 303 tells the client to follow up with a GET by design, used after a form post.'], why: '308 is the permanent redirect that keeps the method and body, as 307 does for temporary moves.' },
  { id: 'qb-redirect6', c: 'redirect', type: 'mc', q: 'At 50,000 clicks a second, 80% are repeat clicks from the same browsers. You switch from 302 to 301. What happens?', opts: ['Load drops by up to 80%, but those go uncounted', 'Load barely moves; a 301 still hits you every click', 'Analytics improve, since 301s are logged at once', 'Load doubles, as browsers check the target first'], a: 0, no: [null, 'Browsers cache a 301 and stop asking, so repeat clicks skip you.', 'Clicks that skip your servers cannot be logged by them, so counts fall.', 'Browsers go straight to the cached target. There is no extra check.'], why: 'A cached 301 sends repeat clicks straight to the target, which cuts load but blinds your analytics to them. That is the core 301 versus 302 trade.' },
  // nines: Availability & Nines
  { id: 'qb-nines1', c: 'nines', type: 'mc', q: 'Your SLA is 99.99% a month. One incident takes 20 minutes to detect and fix. Where does that leave you?', opts: ['Fine: well inside the budget of about 53 minutes', 'Fine: well inside the budget of about 43 minutes', 'Over only if a second incident follows it', 'Over: the month allows only about 4 minutes'], a: 3, no: ['53 minutes is the budget for a whole year at 99.99%, not a month.', '43 minutes is a month at 99.9%, one nine less.', 'One 20-minute outage already exceeds the month\'s budget.', null], why: 'A month has about 43,000 minutes, and 0.01% of that is about 4.3 minutes. Four nines leaves almost no time for a human to notice, so it needs automated failover.' },
  { id: 'qb-nines2', c: 'nines', type: 'mc', q: 'A request passes through 5 services in a row, each 99.9% available. About how available is the whole path?', opts: ['About 99.9%', 'About 99.5%', 'About 99.0%', 'About 99.95%'], a: 1, no: ['Each part in series adds its own downtime. The chain is weaker than any one link.', null, 'That would need about ten 99.9% parts, or five 99.8% ones.', 'Parts in series can only lower availability. Higher needs redundancy.'], why: 'Series availability multiplies: 0.999^5 is about 0.995. Each extra dependency on the critical path adds its downtime, which is why deep call chains hurt.' },
  { id: 'qb-nines3', c: 'nines', type: 'mc', q: 'Two 99% replicas sit in one rack on a single power feed. Why might you not get the 99.99% the parallel maths promises?', opts: ['They fail together, so they are not independent', 'The parallel formula only holds for three replicas', 'Replication lag counts against availability', 'Each replica halves its capacity when paired'], a: 0, no: [null, 'The formula works for two or more replicas, as long as their failures are independent.', 'Lag makes reads stale, but a stale answer is still an answer.', 'Capacity per replica does not change, and spare capacity is not the issue here.'], why: 'Parallel availability (1 - 0.01 x 0.01) assumes the replicas fail separately. A shared rack, power feed or deploy fails them together, so spread replicas across zones.' },
  { id: 'qb-nines4', c: 'nines', type: 'mc', q: 'A system fails about once a month and takes 4 hours to recover. You cut recovery to 20 minutes. What happens to availability?', opts: ['From about 99.4% to about 99.5%', 'Nothing, as it still fails every month', 'From about 99.4% to about 99.95%', 'From about 99.4% to about 99.999%'], a: 2, no: ['That understates it: downtime falls twelvefold, from 240 to 20 minutes.', 'Availability counts time down, not how often it fails. Shorter outages mean less downtime.', null, 'Five nines allows about 26 seconds a month, far less than 20 minutes.'], why: 'Downtime goes from 240 of about 43,000 minutes a month (99.4%) to 20 (about 99.95%). That is why faster recovery (lower MTTR) is often the cheapest nine.' },
  // limiterdesign: Where the Limiter Lives
  { id: 'qb-limiterdesign1', c: 'limiterdesign', type: 'mc', q: 'Your limiter keys by client IP and sits behind a load balancer. Suddenly every user is throttled together. Likely cause?', opts: ['Redis keys collide, since IPs hash to the same slot', 'Clock skew between limiter nodes shortens the window', 'The Retry-After header is too short, so clients flood back', 'It reads the load balancer\'s IP, not X-Forwarded-For'], a: 3, no: ['Redis keys are compared exactly; a slot collision only co-locates keys, it never merges their counts.', 'Skew can let a few extra requests through near a window edge, but it cannot make all users share one counter.', 'Short Retry-After values cause quicker retries per client, not one shared limit across every user.', null], why: 'Behind a proxy, the TCP source address is the proxy itself, so every user shares one counter. Read the real client IP from X-Forwarded-For, trusting only the hops you control.' },
  { id: 'qb-limiterdesign2', c: 'limiterdesign', type: 'mc', q: 'A login endpoint is hit by credential stuffing from many machines. Users are not signed in yet. What should the limiter key on?', opts: ['The API key that ships inside every copy of the mobile app', 'The session cookie the client sends', 'The client IP and the target username, each limited', 'The User-Agent string of each request'], a: 2, no: ['An API key baked into a public app is the same for every install, so it limits all users at once and anyone can extract it.', 'An attacker simply drops or rotates cookies. Cookies identify sessions after login, not callers before it.', null, 'The User-Agent is chosen by the client, so a script sends whatever string it likes and dodges the limit.'], why: 'Before login there is no user ID, so limit by IP to slow one machine and by target username to protect one account from a botnet spread over many IPs.' },
  { id: 'qb-limiterdesign3', c: 'limiterdesign', type: 'mc', q: 'Ops wants to raise the free tier from 100 to 200 requests a minute without a deploy. Where should limit rules live?', opts: ['As constants in the gateway code, changed by pull request', 'In each user\'s JWT claims, read on every request', 'In the client SDK, which reads them on start-up', 'In a config store that limiter nodes load and cache'], a: 3, no: ['Constants work but every change needs a build and deploy, which is what ops wants to avoid.', 'Claims are fixed until the token expires, so a change waits for every token to be reissued.', 'Client-side rules are only a courtesy; the server must enforce limits, since clients can be modified.', null], why: 'Rules belong in config (files or a small store) that each limiter caches and refreshes, so changing a limit is a config push rather than a code deploy.' },
  { id: 'qb-limiterdesign4', c: 'limiterdesign', type: 'mc', q: 'An API client wants to slow down before it ever gets a 429. What should your successful responses carry?', opts: ['X-RateLimit-Remaining and a reset time', 'A Retry-After header on every response', 'Cache-Control: max-age set to the window', 'An ETag so repeats can be skipped'], a: 0, no: [null, 'Retry-After tells a rejected or unavailable client when to come back; on a success it has no meaning.', 'Cache-Control governs how long a response may be cached, not how many calls the client has left.', 'ETags enable conditional requests to save bandwidth, but each one still counts against the limit.'], why: 'X-RateLimit-Remaining (with limit and reset headers) lets a well-behaved client pace itself; Retry-After is for the 429 itself.' },
  { id: 'qb-limiterdesign5', c: 'limiterdesign', type: 'mc', q: 'You run limiters in three regions, each with its own Redis. A user spreads requests across regions. What happens to their limit?', opts: ['Redis replicates counts so each region sees the total', 'The gateway sums the three counts on each request', 'They can get up to three times their limit in total', 'Requests in the second region are rejected outright'], a: 2, no: ['Separate Redis instances share nothing unless you set up cross-region sync, which adds lag anyway.', 'Reading three remote stores per request adds cross-region latency, which is why regional limiters avoid it.', null, 'Nothing links the regions, so the second region has its own fresh count and accepts the requests.'], why: 'Independent regional counters each allow the full limit. Teams usually accept that slack, give each region a share of the limit, or sync counts asynchronously.' },
  // atomic: Race Conditions & Atomic Counters
  { id: 'qb-atomic1', c: 'atomic', type: 'mc', q: 'Your token-bucket Lua script reads tokens:42 and ts:42. On Redis Cluster it fails with CROSSSLOT. Fix?', opts: ['Use a hash tag, like {42}, so both keys share a slot', 'Wrap the two reads in MULTI and EXEC instead', 'Split it into two scripts, one per key', 'Add WATCH on both keys before running the script'], a: 0, no: [null, 'A MULTI transaction has the same rule: every key it touches must live in one slot.', 'Two scripts are no longer one atomic step, so the read-then-write race comes back.', 'WATCH is optimistic locking for transactions; it does not let one command span slots.'], why: 'Redis Cluster runs a script on one node, so all its keys must hash to one slot. A hash tag hashes only the part in braces, keeping a user\'s keys together.' },
  { id: 'qb-atomic2', c: 'atomic', type: 'mc', q: 'A hot counter uses WATCH, GET, then MULTI with SET. Under heavy load, throughput collapses. Why?', opts: ['WATCH holds a lock that blocks every other client', 'Each WATCH copies the key, which fills memory', 'Each MULTI transaction is replayed in full on every replica', 'Most transactions abort because the key changed, and retry'], a: 3, no: ['WATCH takes no lock. It only marks the key, so EXEC fails if someone else wrote it first.', 'WATCH stores no copy of the value; it is a cheap flag per watched key.', 'Replicas apply the result once, like any other write; replication is not what slows this down.', null], why: 'WATCH is optimistic: under contention nearly every EXEC fails and retries. A single atomic INCR or a Lua script does the update in one step with no retries.' },
  // backoff: Retries, Backoff & Idempotency
  { id: 'qb-backoff1', c: 'backoff', type: 'mc', q: 'The gateway, the service and the DB client each make up to 3 attempts. The database blips. How many DB calls can one user request cause?', opts: ['3', '9', '27', '81'], a: 2, no: ['That is one layer alone. Each outer attempt restarts the inner layers\' attempts too.', 'That counts two layers. The gateway\'s three attempts each restart the service and its DB client.', null, 'That would be four layers of three attempts each, a layer more than this path has.'], why: 'Retries multiply across layers: 3 x 3 x 3 = 27. Retry at one layer, usually the outermost or the one closest to the failure, and let the others fail fast.' },
  { id: 'qb-backoff2', c: 'backoff', type: 'mc', q: 'Backoff starts at 100 ms and doubles each try, with no cap. Roughly how long does the 15th retry wait?', opts: ['About 1.5 seconds', 'About 3 minutes', 'About 27 minutes', 'About 7 hours'], a: 2, no: ['That is 15 x 100 ms, which is linear backoff, not doubling.', 'That is roughly the 12th retry. Doubling grows faster than it feels.', null, 'That is about four doublings further, around the 19th retry.'], why: '100 ms x 2^14 is about 1,640 seconds, or 27 minutes. That is why backoff is capped (say at 30 s) and retries are limited in number.' },
  { id: 'qb-backoff3', c: 'backoff', type: 'mc', q: 'Which failure should a client not retry automatically?', opts: ['503 Service Unavailable with Retry-After', 'A connection reset before any reply', '429 Too Many Requests', '400 Bad Request: field "email" invalid'], a: 3, no: ['A 503 is a transient server problem. Retrying after the Retry-After delay is exactly right.', 'A reset is a transient network failure. Retry it, with an idempotency key if it was a write.', 'A 429 means slow down, not stop. Retry after the Retry-After time.', null], why: 'A 4xx validation error will fail the same way every time, so retrying only adds load. Retry transient errors: timeouts, resets, 503 and 429.' },
  { id: 'qb-backoff4', c: 'backoff', type: 'mc', q: 'A payment retry arrives with the same idempotency key while the first attempt is still running. What should the server do?', opts: ['Mark keys in progress at the start; answer the retry 409', 'Process it, since no result is stored for that key yet', 'Save the key only after the charge succeeds, with its result', 'Dedupe on a hash of the request body instead'], a: 0, no: [null, 'That runs two charges in parallel, the very double charge the key exists to prevent.', 'Saving late leaves a window where both attempts see no key and both charge.', 'Two genuine identical purchases would merge, and it still does not handle the in-flight race.'], why: 'Insert the key as in progress atomically before charging. A concurrent retry sees it and gets a 409 or waits; later retries get the stored result.' },
  { id: 'qb-backoff5', c: 'backoff', type: 'mc', q: 'During an outage, retries from your whole fleet triple the load on a struggling service. What caps that amplification?', opts: ['A retry budget, such as retries capped at 10% of calls', 'Hedged requests sent after the p95 latency passes', 'Longer client timeouts, so fewer calls fail and get retried', 'Adding more partitions to the request queue'], a: 0, no: [null, 'Hedging sends a duplicate to cut tail latency on a healthy service; during an outage it adds even more load.', 'Longer timeouts hold threads and connections longer, which often spreads the outage upstream.', 'Partitions add consumer parallelism; they do not reduce how many retries hit the service.'], why: 'A retry budget limits retries to a fraction of normal traffic, so a failing service sees at most a little extra load. Circuit breakers do the same per dependency.' },
  // blob: Object Storage & Presigned URLs
  { id: 'qb-blob1', c: 'blob', type: 'mc', q: 'Clients upload straight to S3 with a presigned PUT. How does the file\'s metadata row learn the upload finished?', opts: ['The app server proxies the bytes and sees the last one arrive', 'The row is marked complete when the URL is handed out', 'A cron job lists the whole bucket each minute and diffs it', 'A storage event or the client\'s confirm call marks it done'], a: 3, no: ['Proxying puts every byte back through your servers, undoing the point of presigned URLs.', 'Many uploads fail or are abandoned, so the row would point at files that do not exist.', 'Listing a bucket of billions of objects is slow and costly; event notifications report each new object directly.', null], why: 'The row starts as pending. An S3 event notification (or a confirm call that checks the object exists) flips it to uploaded, so bytes never touch the app.' },
  { id: 'qb-blob2', c: 'blob', type: 'mc', q: 'A presigned download link for a private file gets posted on a public forum. What limits the damage most?', opts: ['A short expiry, measured in minutes', 'Serving the link over HTTPS only', 'Server-side encryption on the bucket', 'Versioning turned on for the bucket'], a: 0, no: [null, 'HTTPS protects the link in transit, but anyone holding the link can still use it.', 'S3 decrypts for any valid request, and a presigned URL is a valid request.', 'Versioning keeps old copies after overwrites or deletes; it does nothing about who can read.'], why: 'A presigned URL is a bearer token: whoever has it can use it until it expires. Short expiries keep leaked links nearly worthless.' },
  { id: 'qb-blob3', c: 'blob', type: 'mc', q: 'Users on flaky mobile links keep failing to upload 4 GB videos at around 90%. Best fix?', opts: ['Multipart upload, retrying only the failed parts', 'Gzip the video before upload to shrink it', 'A longer timeout on the single PUT request', 'Route uploads through the app servers so they can retry'], a: 0, no: [null, 'Video is already compressed, so gzip saves almost nothing and still uploads as one piece.', 'Any drop still restarts the whole 4 GB, and a single PUT to S3 is capped at 5 GB, so larger files cannot use it at all.', 'App servers would carry every byte and still restart from zero on a drop.'], why: 'Multipart upload sends the file as independent parts, each with its own presigned URL, so a drop costs one part rather than the whole file.' },
  { id: 'qb-blob4', c: 'blob', type: 'mc', q: 'Deleting a file removes its metadata row, then calls S3 delete, which sometimes fails. How do you stop orphaned objects piling up?', opts: ['Wrap the row delete and S3 delete in a DB transaction', 'Turn on S3 versioning so deletes can be tracked', 'Run a sweep that deletes objects no row points to', 'Purge the file from the CDN as part of the delete'], a: 2, no: ['S3 is not part of the database, so the transaction cannot roll back or guarantee the S3 call.', 'Versioning keeps more copies, not fewer; deletes add markers and old versions still cost money.', null, 'A CDN purge removes cached copies at the edge; the object stays in the bucket.'], why: 'Two stores cannot share one transaction, so accept brief orphans and clean up: a periodic sweep or a retried async delete job reconciles the bucket with the database.' },
  { id: 'qb-blob5', c: 'blob', type: 'mc', q: 'Most stored files are rarely read after 90 days, and storage is now the biggest bill. Cheapest fix?', opts: ['Move old files into Postgres BLOB columns', 'A lifecycle rule to an infrequent-access tier', 'Cache old files at the CDN to cut reads', 'Keep them in Redis with a long TTL'], a: 1, no: ['Database storage costs far more per GB than object storage, and bloats backups and replicas.', null, 'A CDN saves on hot, popular files; cold files are rarely read, so it barely helps.', 'Memory costs many times more than disk; Redis is for small hot data, not cold files.'], why: 'Object stores have cheaper tiers for rarely read data (infrequent access, archive). A lifecycle rule moves objects by age automatically.' },
  // chunking: Chunking & Delta Sync
  { id: 'qb-chunking1', c: 'chunking', type: 'mc', q: 'Files use fixed 4 MB chunks. A user inserts one byte at the start of a 2 GB file. What does the client upload?', opts: ['Nearly every chunk, since all the boundaries shift', 'Only the first chunk, since the rest of the file is unchanged', 'Nothing new, since every chunk hash is known', 'The first chunk plus the updated chunk list'], a: 0, no: [null, 'That is what content-defined chunking achieves: boundaries chosen by a rolling hash move with the data.', 'Every byte after the insert moves, so each fixed chunk now has new content and a new hash.', 'That would be true for an edit in place, which keeps the boundaries where they were.'], why: 'Fixed-size boundaries sit at fixed offsets, so an insert shifts all later bytes into different chunks. Content-defined chunking avoids this by cutting where the content says.' },
  { id: 'qb-chunking2', c: 'chunking', type: 'mc', q: 'An upload of a 500-chunk file drops after chunk 320. When the client reconnects, what should it do?', opts: ['Restart the file, since the server may hold partial data', 'Ask the server for the byte offset and stream from there', 'Resend every chunk, letting the server dedupe them', 'Ask which chunk hashes the server has, then send the rest'], a: 3, no: ['Each chunk is stored whole under its hash, so finished chunks are safe to keep.', 'Byte-offset resume suits one long stream; with chunks, the server can simply report which ones it has.', 'Dedupe saves storage, but resending 320 chunks wastes the bandwidth the scheme should save.', null], why: 'Chunks are independent and named by hash, so the client sends the chunk list, the server replies with what is missing, and only those 180 go up.' },
  { id: 'qb-chunking3', c: 'chunking', type: 'mc', q: 'Why not use 64 KB chunks instead of 4 MB, to resend less on each edit?', opts: ['Small chunks dedupe worse across users', 'Hash collisions grow likely at that size', 'Object stores reject objects under 5 MB', 'Metadata and request counts balloon'], a: 3, no: ['Smaller chunks dedupe better, if anything, since shared runs of data are found at a finer grain.', 'A SHA-256 collision is astronomically unlikely at any chunk size.', 'Objects can be any size; the 5 MB minimum applies to S3 multipart parts, not to objects.', null], why: 'A 2 GB file becomes about 32,000 chunks at 64 KB, so the chunk list, the metadata rows and the number of requests grow 64 times. A few MB balances that against resend size.' },
  { id: 'qb-chunking4', c: 'chunking', type: 'mc', q: 'Chunks are deduplicated across users. When is it safe to delete a stored chunk?', opts: ['When no file version references it any more', 'When the user who first uploaded it deletes the file', 'When it has not been read for 90 days', 'Thirty days after it was first uploaded'], a: 0, no: [null, 'Other users\' files may share that chunk, so deleting it would corrupt their files.', 'An age rule suits moving cold data to a cheaper tier, not deleting data someone still owns.', 'A fixed TTL deletes chunks that live files still depend on.'], why: 'A shared chunk can belong to many files, so track a reference count (or mark and sweep) and delete it only when nothing points to it.' },
  { id: 'qb-chunking5', c: 'chunking', type: 'mc', q: 'Two devices edit the same file while offline, then both sync. What do file sync services usually do?', opts: ['Merge the two chunk lists into one file', 'Keep both, saving one as a conflicted copy', 'Keep the newer edit and drop the older one', 'Reject both edits until one of the devices reverts'], a: 1, no: ['Chunks from two different edits do not combine into a valid file; the result would be corrupt.', null, 'Last writer wins suits small fields where losing an edit is fine, but silently drops someone\'s work here.', 'Rejecting both loses work and blocks users; services prefer to keep data and let people choose.'], why: 'The server sees the second sync was based on an old version, so it keeps both: the first wins the name and the other becomes a conflicted copy for the user to resolve.' },
  // indexes: Database Indexes
  { id: 'qb-indexes1', c: 'indexes', type: 'mc', q: 'SELECT email FROM users WHERE last_name = ? uses an index on last_name, but still does thousands of random table reads. Fix?', opts: ['A hash index on last_name in place of the B-tree one', 'Run the query on a read replica', 'Partition the users table by last_name', 'A covering index on last_name that includes email'], a: 3, no: ['A hash index finds the same rows, then still visits the table for each email.', 'A replica moves the same random reads to another machine without making them fewer.', 'Partitioning narrows which tables to search; each match is still a separate table read.', null], why: 'If the index holds every column the query needs, the database answers from the index alone (an index-only scan) and skips the table lookups.' },
  { id: 'qb-indexes2', c: 'indexes', type: 'mc', q: 'On an LSM-tree store, reads for keys that do not exist are slow, since each checks many sorted files. What helps most?', opts: ['A Bloom filter on each sorted file', 'A B-tree secondary index on the same key', 'Larger memtables flushed less often', 'Write-ahead log replay on each read'], a: 0, no: [null, 'The LSM files are already sorted by that key; another index adds write cost without fixing the per-file checks.', 'Bigger memtables cut flushes, but reads still check every file on disk until compaction merges them.', 'The WAL is for crash recovery; reading it on lookups would make reads slower.'], why: 'A Bloom filter answers "definitely not here" cheaply, so a read skips most files. Compaction also helps by merging files so there are fewer to check.' },
  // fanout: Feed Fan-out
  { id: 'qb-fanout1', c: 'fanout', type: 'mc', q: 'With fan-out on write, someone deletes a post already pushed into 2 million feeds. Cheapest common handling?', opts: ['Mark it deleted; feed reads skip it when loading posts', 'Remove it from all 2M feeds before confirming', 'Rebuild every affected feed from scratch in a nightly job', 'Leave it, since feeds are only eventually consistent'], a: 0, no: [null, 'A synchronous 2M-write delete makes the user wait and repeats the celebrity problem.', 'Rebuilding millions of feeds is far more work than skipping one ID at read time.', 'Eventual consistency allows a delay, but showing a deleted post indefinitely is a real bug.'], why: 'Feeds store post IDs and fetch post bodies on read, so a deleted flag hides the post at once. A background job can trim the stale IDs later.' },
  { id: 'qb-fanout2', c: 'fanout', type: 'mc', q: 'Fan-out on write pushes to every follower, but 40% of followers have not opened the app in a month. Common optimisation?', opts: ['Push to them through a slower, lower-priority queue', 'Switch the whole system to fan-out on read', 'Skip them; build their feed by pull when they return', 'Keep their feeds in cheaper disk-based storage'], a: 2, no: ['A slower queue still does all the writes; it only delays wasted work.', 'Pull for everyone makes reads slow for the 60% who are active.', null, 'Cheaper storage lowers the cost per write but keeps every wasted write.'], why: 'Precomputing feeds nobody reads is waste. Push only to active users; when an inactive user returns, assemble their feed by pull once, then push resumes.' },
  // streams: Stream Processing & Aggregation
  { id: 'qb-streams1', c: 'streams', type: 'mc', q: 'One viral ad gets 40% of all clicks. The stream task that owns that ad lags far behind while others sit idle. Fix?', opts: ['Add more Kafka partitions and consumers to the click topic', 'Salt the key into sub-keys, then sum them per window', 'Window by processing time so the task skips waiting', 'Checkpoint less often to free up the busy task'], a: 1, no: ['One key still maps to one partition, so extra partitions leave the hot ad where it was.', null, 'Processing time changes which window a click lands in, not how much work one task has.', 'Rare checkpoints save a little overhead but lengthen replay after a crash; the hot key remains.'], why: 'Split the hot key (ad#1, ad#2, ...) so several tasks count it in parallel, then a second step sums the partial counts for each window.' },
  { id: 'qb-streams2', c: 'streams', type: 'mc', q: 'A chart needs clicks in the last 5 minutes, refreshed every minute. Which window?', opts: ['A 5-minute tumbling window', 'A session window, 5-minute gap', 'A sliding window: 5 min, 1 min step', 'A global window, count trigger'], a: 2, no: ['Tumbling windows do not overlap, so the number would update only every 5 minutes.', 'Session windows group bursts of activity per key until a quiet gap, which suits user sessions.', null, 'A global window never closes; it suits counting since the start, not a moving 5 minutes.'], why: 'A sliding (hopping) window of 5 minutes that advances every minute gives an overlapping 5-minute count each minute.' },
  { id: 'qb-streams3', c: 'streams', type: 'mc', q: 'A job windows clicks by arrival time. After a 10-minute consumer outage, the chart shows a dip then a huge spike. Why?', opts: ['The backlog landed in the minutes it was processed', 'Watermarks jumped ahead and dropped the late clicks', 'Kafka reordered its partitions after the restart', 'Producers batch more clicks under backpressure'], a: 0, no: [null, 'Dropped clicks would leave a lasting gap, not a spike; this job is not using event-time watermarks anyway.', 'Kafka keeps order within each partition across restarts; partitions are not reshuffled.', 'Batching changes how clicks are sent, not when they were made or which window counts them.'], why: 'With arrival time, ten minutes of clicks pile into the minute the job caught up. Windowing by event time puts each click in the minute it happened.' },
  { id: 'qb-streams4', c: 'streams', type: 'mc', q: 'A click arrives after its window\'s watermark and grace period have passed. Typical handling?', opts: ['Reopen the window and recompute its total', 'Count it in the window that is open now', 'Pause the job until older data catches up', 'Send it to a side output; batch fixes totals'], a: 3, no: ['Keeping every window reopenable means keeping all state forever, which the grace period exists to avoid.', 'That puts the click in the wrong minute, which is the arrival-time error over again.', 'One slow phone would stall every count; watermarks exist so the job can move on.', null], why: 'Past the grace period the live count is final. Very late events go to a side output or are dropped, and the nightly batch over raw events corrects the exact totals.' },
  // topk: Top-K & Sketches
  { id: 'qb-topk1', c: 'topk', type: 'mc', q: 'A count-min sketch says a niche video has 50k views; the true count is 2k. What happened?', opts: ['The sketch rounds counts to powers of two', 'Two writes raced and one update was lost', 'The sketch is too wide, so counts spread thin', 'In every row, it shares a cell with a hit video'], a: 3, no: ['Rounding to powers of two is a Morris counter, a different trick for counting one item in few bits.', 'A lost update would make the count lower, not higher.', 'A wider sketch has fewer collisions and smaller errors; too narrow is the problem.', null], why: 'Each row hashes the video to a cell that other videos also add to. The sketch takes the minimum across rows, but if every row collides with a popular video, it overcounts.' },
  { id: 'qb-topk2', c: 'topk', type: 'mc', q: 'Your count-min sketch overcounts too much. What change makes its estimates tighter?', opts: ['Take the max across rows instead of the min', 'Use fewer hash rows, so each cell is checked once', 'Store each item ID in its cell beside the count', 'Add columns, so fewer items share each cell'], a: 3, no: ['Every row can only overcount, so the max is the worst estimate, not the best.', 'Fewer rows means fewer chances to find a row without a collision, so errors grow.', 'Storing IDs makes it an exact hash map, which loses the small fixed memory that is the point.', null], why: 'Width controls error size: more columns, fewer collisions. Depth (rows) controls how likely the estimate is to be that good.' },
  { id: 'qb-topk3', c: 'topk', type: 'mc', q: 'A trending page gets 50k reads a second and rebuilds the top 10 from all counts on each request. Fix?', opts: ['Add read replicas to the counter store', 'Precompute the list each minute; serve it', 'Use a min-heap of size 10 on each request', 'Swap the exact counts for a count-min sketch'], a: 1, no: ['Replicas spread the reads, but each request still scans every count, which is the real waste.', null, 'A heap is the right way to compute top 10, but doing it 50k times a second still repeats work.', 'A sketch saves memory for counting; it does not stop recomputing the ranking per request.'], why: 'The top 10 barely changes within a minute, so compute it once a minute and cache the list. Each read becomes a single cache lookup.' },
  { id: 'qb-topk4', c: 'topk', type: 'mc', q: 'You reshard view counts by video ID instead of by the server that took the view. Why does that make merged top-K exact?', opts: ['Each shard is smaller, so its heap fits in memory', 'Each video\'s full count now lives on a single shard', 'Hot videos spread across shards, avoiding hot keys', 'Shards can now use a count-min sketch safely'], a: 1, no: ['Memory was not the issue; partial counts split across servers were.', null, 'The opposite: sharding by video puts each hot video on one shard, which can become a hot spot.', 'Sketches estimate counts approximately; they add error rather than making the merge exact.'], why: 'When a video\'s total sits on one shard, any video in the global top K must be in its own shard\'s top K, so merging shard top-K lists is exact.' },
  // search: Search & Inverted Indexes
  { id: 'qb-search1', c: 'search', type: 'mc', q: 'Searching for "running" misses documents that only say "runs" or "ran". What fixes it?', opts: ['A trigram index for fuzzy substring matching', 'A leading-wildcard LIKE \'%run%\' query', 'Stemming in the analyser, at index and query time', 'More shards, so the index can hold more word forms'], a: 2, no: ['Trigrams catch typos and substrings, but "ran" shares little with "running", so it is still missed.', 'That scans every row and still misses "ran", while matching unrelated words like "brunch".', null, 'Shards spread the index over machines; they do not change which words the index stores.'], why: 'Analysers lower-case, tokenise and stem words (or map them to a base form) at index and query time, so "running", "runs" and "ran" hit the same term.' },
  { id: 'qb-search2', c: 'search', type: 'mc', q: 'A search index is split by document across 20 shards. How is a single query served?', opts: ['Sent to the one shard that owns the first term', 'Sent to all shards; their top hits are merged', 'Hashed by document ID to the one shard that owns it', 'Sent to a random shard, with results cached'], a: 1, no: ['That fits term partitioning, where each shard owns some words; here each shard holds whole documents.', null, 'Hashing by ID finds a known document, as in a get by ID. A search does not know which documents match until every shard looks.', 'One random shard sees about 5% of documents, so most results would be missing.'], why: 'With document partitioning, every shard may hold matches, so a coordinator scatters the query to all shards and gathers and merges their top results.' },
  { id: 'qb-search3', c: 'search', type: 'mc', q: 'A seller renames a listing and searches for it at once, but sees the old title. Postgres feeds Elasticsearch by CDC. Why?', opts: ['Elasticsearch caches each query result for an hour', 'The B-tree index on the title column is out of date', 'CDC captures only inserts, so updates are missed', 'The indexer applies the change shortly after the commit'], a: 3, no: ['Elasticsearch caches some filters and shard results, but invalidates them when the index refreshes.', 'Postgres updates its B-tree in the same transaction as the row, so it is never stale.', 'CDC reads inserts, updates and deletes from the log, so the rename will arrive.', null], why: 'CDC is asynchronous: the change flows from the log to the indexer and a refresh, often a second or so later. That lag is usually fine; read your own write from the database if not.' },
  { id: 'qb-search4', c: 'search', type: 'mc', q: 'Typeahead serves precomputed top suggestions per prefix. How should new trending queries get into it?', opts: ['Update the prefix table on every search typed', 'A job rebuilds the prefix table from query logs', 'Clients send their own recent searches to all', 'Fall back to LIKE \'prefix%\' when the cache misses'], a: 1, no: ['Writing to every prefix of every query on each search turns a read-heavy table into a write hot spot.', null, 'Sharing raw searches leaks private queries and does not rank by popularity.', 'Scanning the query log per keystroke is what the precomputed table replaces.'], why: 'Aggregate query logs in a batch or stream job every few minutes or hours, rebuild the top suggestions per prefix, and swap the new table into the cache.' },
  // realtime: Real-time Connections & Presence
  { id: 'qb-realtime1', c: 'realtime', type: 'mc', q: 'A gateway deploy drops 200,000 WebSockets at once. Seconds later the new gateways are overloaded and fall over again. What fixes it?', opts: ['Clients reconnect with exponential backoff plus random jitter', 'Lengthen the presence timeout so users are not marked offline', 'Turn on sticky sessions so each client returns to its old server', 'Switch the clients from WebSockets to Server-Sent Events'], a: 0, no: [null, 'That stops a burst of false "offline" updates, but the overload is the reconnect stampede itself, which a timeout does not slow down.', 'Sticky sessions pin a client to one server, useful for server-side session state, but the old servers are gone and every client still arrives at once.', 'SSE is a lighter one-way push stream, but its clients reconnect too, so the same thundering herd hits the gateways.'], why: 'Every dropped client retries at the same instant: a thundering herd. Exponential backoff with jitter spreads the reconnects over many seconds, so the gateways can accept them at a pace they survive.' },
  // clocks: Clocks & Ordering
  { id: 'qb-clocks1', c: 'clocks', type: 'mc', q: 'Server A logs "order paid" at 10:00:00.120, then sends the message that makes server B ship. B logs "order shipped" at 10:00:00.090. What explains it?', opts: ['B received the message before A had finished sending it', 'The message was delivered twice, and B logged the first copy', 'B\'s clock is behind A\'s, so the wall times mislead', 'Lamport clocks on the two servers reordered the two events'], a: 2, no: ['A receive always happens after its send; that is the core of happens-before. The timestamps are what is wrong, not the order of events.', 'A duplicate delivery still comes after the send, so it cannot explain a receive stamped before the payment.', null, 'Lamport clocks never reorder events; they would give the shipping event a higher counter than the payment, matching the real cause.'], why: 'Wall clocks drift and NTP only keeps them roughly in step, so a 30 ms gap between machines is normal. Causal order (happens-before) says the payment came first; a Lamport or vector clock would record that correctly.' },
  { id: 'qb-clocks2', c: 'clocks', type: 'mc', q: 'A node\'s Lamport clock reads 7. It receives a message stamped 12. What does it set its clock to before handling the message?', opts: ['12: copy the sender\'s stamp', '13: max(7, 12) + 1', '8: its own clock plus one', '19: the sum of the two clocks'], a: 1, no: ['The receive must come strictly after the send, so it needs a value above 12, not equal to it.', null, 'Just ticking its own counter ignores the sender, so the receive (8) would look earlier than the send (12).', 'Adding the counters is not the rule. It still respects order, but the clocks would grow needlessly fast; Lamport takes the maximum and adds one.'], why: 'On receive, a Lamport clock jumps to the larger of its own value and the message stamp, then ticks once. That guarantees every receive gets a higher number than its send.' },
  { id: 'qb-clocks3', c: 'clocks', type: 'mc', q: 'Event X has Lamport timestamp 5 and event Y has Lamport timestamp 9. What can you safely conclude?', opts: ['Y cannot have happened before X', 'X happened before Y in causal order', 'X and Y were concurrent on different nodes', 'Y happened about 4 ticks of real time after X'], a: 0, no: [null, 'Lamport clocks only work one way: if X caused Y then L(X) < L(Y), but a smaller number does not prove a cause. They may be concurrent.', 'They might be, but they might also be causally linked. Telling the two cases apart needs a vector clock.', 'Lamport counters count events, not time. A gap of 4 says nothing about how much real time passed.'], why: 'If Y happened before X, Y would have the smaller Lamport timestamp. Since it has the larger one, Y did not cause X; but X might have caused Y or they might be concurrent, and only a vector clock can tell which.' },
  { id: 'qb-clocks4', c: 'clocks', type: 'mc', q: 'Two versions of one key have vector clocks A = [2, 1, 0] and B = [1, 3, 0]. What should a Dynamo-style store do?', opts: ['Keep B, since its counters add up to more', 'Keep A, since node 1 has the higher count there', 'Keep whichever version carries the later wall time', 'Keep both, since neither descends from the other'], a: 3, no: ['Vector clocks are compared entry by entry, not by their sum. A larger total does not mean B saw everything A saw.', 'A is ahead on node 1 but behind on node 2, so A did not see all of B either. Picking A drops B\'s write.', 'That is last-write-wins: simple, but with concurrent writes it silently drops one, and drifting clocks decide which.', null], why: 'A version descends from another only if every entry is greater than or equal. Here A leads on one node and B on another, so the writes were concurrent: keep both as siblings, or merge them, instead of losing one.' },
  { id: 'qb-clocks5', c: 'clocks', type: 'mc', q: 'A like counter is incremented on two replicas at once, and last-write-wins keeps losing likes. Which fix keeps every like without coordinating replicas?', opts: ['A CRDT counter: each replica counts its own, summed on read', 'Last-write-wins with timestamps from tightly synced clocks', 'Vector clocks, keeping the higher of the two counts', 'A distributed lock taken around each increment'], a: 0, no: [null, 'Better clocks pick the "last" write more fairly, but LWW still keeps one of two concurrent writes and throws the other away.', 'Vector clocks detect that the writes were concurrent, but taking the higher count still drops the other replica\'s likes.', 'A lock makes increments safe but forces every like through coordination, which the question rules out and which slows every write.'], why: 'A grow-only counter CRDT keeps one count per replica; each replica increments only its own slot and merging takes the max per slot. The total is the sum, so concurrent likes merge without any being lost.' },
  { id: 'qb-clocks6', c: 'clocks', type: 'mc', q: 'A service measures each request as end wall-clock time minus start wall-clock time. A few logs show negative durations. What went wrong?', opts: ['The request crossed midnight, so the date rolled over', 'NTP stepped the clock back; durations need a monotonic clock', 'A garbage collection pause stalled the request midway', 'Lamport timestamps were logged instead of real times'], a: 1, no: ['Wall-clock timestamps include the date, so crossing midnight still gives a positive difference.', null, 'A pause makes the measured time longer, never negative; it only stretches the gap between the two clock reads.', 'Lamport counters only go up within a node, so a later event can never get a smaller value; they cannot go negative either.'], why: 'NTP can step a drifting wall clock backwards, so end minus start can go below zero. A monotonic clock only moves forward and is the right tool for measuring elapsed time on one machine.' },
  // election: Leader Election & Consensus
  { id: 'qb-election1', c: 'election', type: 'mc', q: 'A 5-node Raft cluster loses 2 nodes. Can it still commit new writes?', opts: ['Yes: the 3 left still make up a majority of 5', 'No: a leader needs all 5 nodes to acknowledge each write', 'Only reads: writes wait until an operator shrinks the cluster', 'Yes, and each write now needs just 2 acks, a majority of 3'], a: 0, no: [null, 'Raft needs a majority, not everyone. Requiring all nodes would let any single failure stop writes.', 'No operator is needed while a majority is alive. Changing membership is for removing nodes for good, not riding out failures.', 'The majority is counted against the configured cluster of 5, so a write still needs 3 nodes. Counting only live nodes would allow two leaders.'], why: 'A Raft write commits once a majority of the configured cluster has it. With 5 nodes that is 3, so the cluster tolerates 2 failures and keeps going.' },
  { id: 'qb-election2', c: 'election', type: 'mc', q: 'Leaders send heartbeats every 50 ms. You set a 60 ms election timeout, and the leader often has 30 ms GC pauses. What goes wrong?', opts: ['A dead leader takes far too long to be noticed and replaced', 'Two leaders end up accepting writes in the same term', 'Followers start needless elections and leadership keeps flapping', 'Committed writes are lost each time the leader changes'], a: 2, no: ['The opposite problem: a short timeout reacts too fast. Slow failover comes from a timeout that is too long.', 'Raft gives each term at most one leader, since each node votes once per term and a leader needs a majority.', null, 'Committed writes are on a majority, and Raft only elects candidates with up-to-date logs, so they survive leader changes. The cost is unavailability.'], why: 'An election timeout only a little longer than the heartbeat interval fires on any pause or network blip. Followers keep electing new leaders, and writes stall during each election; the timeout should be many heartbeats long.' },
  { id: 'qb-election3', c: 'election', type: 'mc', q: 'An old leader freezes in a long GC pause. A new leader is elected. The old one wakes and sends a write to storage before hearing anything. What stops it?', opts: ['The new leader\'s next heartbeat reaches it and blocks the write', 'It checks its own lease against its own local clock before each write', 'Storage rejects any write tagged with an older term than it has seen', 'A shorter leader lease, so its leadership expires sooner'], a: 2, no: ['The heartbeat makes it step down, but only once it arrives; a write sent first still gets through.', 'The pause can happen right after the check, and its clock may be wrong. A lease checked locally cannot fence off a paused node.', null, 'Shorter leases shrink the window but cannot close it: a pause can be longer than any lease.'], why: 'This is a fencing token. Each write carries the leader\'s term, and storage refuses any term lower than the highest it has seen, so a stale leader cannot do damage even before it learns it lost.' },
  { id: 'qb-election4', c: 'election', type: 'mc', q: 'Your team needs exactly one node of a cron service to be leader at a time, with automatic failover. What is the soundest approach?', opts: ['The live node with the lowest IP leads, checked by pings', 'Take an expiring leader lease in etcd or ZooKeeper', 'Run the scheduler on one fixed node and restart it if it dies', 'Write our own Raft so the service does not depend on etcd'], a: 1, no: ['During a partition each side sees a different lowest live node, so two leaders run at once. Pings cannot tell a dead node from a cut link.', null, 'That is simple but has no automatic failover: no jobs run until someone restarts it.', 'Consensus is notoriously hard to get right. Reusing a tested system is safer than writing Raft yourself.'], why: 'etcd and ZooKeeper already run consensus. A node that holds an expiring lease (a lock with a TTL) is leader; if it dies the lease lapses and another node takes it, with the store deciding safely.' },
  { id: 'qb-election5', c: 'election', type: 'mc', q: 'A 5-node cluster has 3 nodes in datacenter 1 and 2 in datacenter 2. Datacenter 1 goes dark. What happens?', opts: ['Datacenter 2 elects a leader once its election timeouts pass', 'Datacenter 2 keeps serving writes from its follower copies', 'Datacenter 2 elects a leader, since it holds copies of the log', 'No leader: 2 of 5 is not a majority, so writes stop'], a: 3, no: ['Its nodes do time out and stand, but each candidate can gather only 2 votes, short of the 3 it needs.', 'Followers do not accept writes on their own; doing so without a majority would risk two diverging histories.', 'Having the log is not enough to lead. Without a majority it could not stop the other side from also acting.', null], why: 'A leader needs a majority of all 5 nodes, and 2 cannot reach it. Losing the site with most nodes stops writes; spreading nodes 2-2-1 across three sites lets any one site fail.' },
  // sagas: Sagas & Distributed Transactions
  { id: 'qb-sagas1', c: 'sagas', type: 'mc', q: 'An order saga\'s orchestrator crashes after charging the card but before reserving stock. What lets the order finish correctly?', opts: ['The payment service refunds the charge when its caller drops', 'The charge sat in a 2PC prepare until the orchestrator returned', 'The order service retries the whole order under a new order ID', 'It saved each step durably, so on restart it resumes the saga'], a: 3, no: ['A dropped caller does not mean the step failed. Services that undo work on a disconnect would undo saga steps the orchestrator still counts as done.', 'Sagas do not use two-phase commit; a prepare would hold locks for as long as the orchestrator is down.', 'A new ID defeats the idempotency key, so the card can be charged twice.', null], why: 'A workflow engine like Temporal records each step\'s result before moving on. A restarted orchestrator reads that state and carries on with reserving stock, or compensates; idempotent steps make any repeated call safe.' },
  // geo: Geospatial Indexes
  { id: 'qb-geo1', c: 'geo', type: 'mc', q: 'A million drivers each send a GPS fix every 4 seconds into a Postgres table with a geospatial index. Writes fall behind. What fits better?', opts: ['Keep live positions in memory, such as Redis GEO', 'Add read replicas so the index can absorb more updates', 'Rebuild a quadtree each night from the day\'s positions', 'Cache "nearby drivers" results at a CDN for a minute'], a: 0, no: [null, 'Replicas copy every write, so they spread reads, not writes. The primary still has to update the index 250,000 times a second.', 'A nightly quadtree suits static places like restaurants. Drivers move constantly, so it would be stale within seconds.', 'Drivers move every few seconds, so a minute-old answer shows cars that have gone. CDNs suit static, shared content.'], why: 'About 250,000 updates a second to a disk-backed index is costly, and only the latest position matters. An in-memory geo index overwrites each driver\'s point cheaply; durable, read-heavy places can stay in the database.' },
  { id: 'qb-geo2', c: 'geo', type: 'mc', q: 'Two cafes stand 10 m apart, yet their geohashes differ from the very first character. How can that be?', opts: ['Geohash scatters nearby points, since it is a hash function', 'The two were encoded at different geohash lengths', 'They sit either side of a top-level cell border', 'Geohash loses accuracy far from the prime meridian'], a: 2, no: ['Unlike a normal hash, a geohash keeps nearby points together; that is why prefix lookups work. Scattering is what hash-based sharding does.', 'A shorter geohash is just a prefix of the longer one for the same spot, so differing lengths still share the leading characters.', null, 'Geohash cells are the same everywhere in longitude. Only their shape in metres changes with latitude, and that does not split nearby points.'], why: 'A shared prefix means the same cell, but the reverse fails at borders: points just either side of a big cell edge share nothing. That is why searches also check the neighbouring cells.' },
  // chash: Consistent Hashing & Key-Value Stores
  { id: 'qb-chash1', c: 'chash', type: 'mc', q: 'Two replicas each hold 100 million keys and may differ on a few thousand. How does anti-entropy find the differences cheaply?', opts: ['Hinted handoff replays every write either replica missed', 'Read repair fixes each key the next time a client reads it', 'Stream every key and value across, and compare them one by one', 'Compare Merkle tree hashes, descending only where they differ'], a: 3, no: ['Hints cover only writes made while a node was known to be down, and hints themselves can be lost. Anti-entropy exists to catch what they miss.', 'Read repair fixes only keys that get read, so cold keys can stay wrong for months.', 'That works but ships 100 million keys to find a few thousand differences. It is what Merkle trees avoid.', null], why: 'Each replica hashes its key ranges into a tree. Comparing root hashes, then only the children that differ, pinpoints the stale ranges while exchanging a tiny fraction of the data.' },
  // sched: Job Scheduling
  { id: 'qb-sched1', c: 'sched', type: 'mc', q: 'Job leases last 10 minutes, but some report jobs take 15 minutes. What happens to those jobs?', opts: ['The worker is killed when its lease runs out', 'The lease lapses and a second worker starts the same job', 'The job finishes, then rolls back because its lease expired', 'Nothing, since the first worker still holds the job in memory'], a: 1, no: ['A lease is a record in the scheduler, not a process supervisor; nothing stops the first worker, so both run.', null, 'Expiry does not undo work the job already did. Its side effects stay, and now a second run repeats them.', 'Holding the job in memory does not stop the scheduler handing it out again once the lease has expired.'], why: 'When a lease expires the scheduler assumes the worker died and gives the job to another, so two copies run. Long jobs should renew their lease with a heartbeat, and steps must be idempotent anyway.' },
  { id: 'qb-sched2', c: 'sched', type: 'mc', q: 'A job calls a partner API that is down for an hour, and its retries fire every second. What should you change?', opts: ['Add workers, so more retries run in parallel', 'Fail it at once, so the queue keeps moving', 'Lengthen the job\'s lease to cover the whole outage', 'Back off exponentially with jitter, then dead-letter it'], a: 3, no: ['More workers only hammer the down API harder and waste capacity on calls that cannot succeed.', 'Failing fast suits errors that will never succeed, like a bad request. A temporary outage deserves retries, just slower ones.', 'The lease decides who owns the job, not how often it retries; a long lease only delays recovery if the worker dies.', null], why: 'Exponential backoff with jitter spaces out retries so they do not pile onto a struggling service. After a set number of tries the job moves to a dead-letter queue for a person to check.' },
  { id: 'qb-sched3', c: 'sched', type: 'mc', q: 'A "send monthly invoice" job can run twice after a worker crash. What makes a second run safe?', opts: ['Exactly-once delivery from the job queue itself', 'A unique key per customer-month, enforced on insert', 'A lease long enough that two runs can never overlap', 'A status flag on the job, read before it starts work'], a: 1, no: ['Queues deliver at least once in practice; a crash after sending but before acking still causes a repeat.', null, 'Leases stop overlap, but a crash after sending and before finishing still makes the job run again later.', 'Check-then-act races, and a crash between sending and setting the flag leaves it unset, so the invoice goes out again.'], why: 'Delivery is at least once, so the job itself must be idempotent. Recording each invoice under a unique key (customer plus month), enforced by a unique constraint or passed to the provider as an idempotency key, lets a repeat find it already done and skip.' },
  { id: 'qb-sched4', c: 'sched', type: 'mc', q: 'Each order should be cancelled if unpaid after 30 minutes. You store the cancel jobs in a Redis sorted set. What is each job\'s score?', opts: ['The order\'s priority, so urgent cancels run first', 'Its creation time, polled for scores later than now', 'Its due time; poll for scores up to now', 'Its retry count, so fresh jobs are taken first'], a: 2, no: ['Priority decides which of several due jobs runs first. It cannot tell the poller which jobs are due yet.', 'Every creation time is in the past, so nothing scores later than now; and it leaves out the 30-minute delay.', null, 'Retry count is useful for backoff but says nothing about when a job is due.'], why: 'Scoring by due time keeps jobs ordered by when they should run. A poller asks for every member scored up to the current time (ZRANGEBYSCORE), moves those to a queue, and workers take them from there.' },
  // dcache: Distributed Caches
  { id: 'qb-dcache1', c: 'dcache', type: 'mc', q: 'One product key gets 200,000 reads a second, all landing on one cache node, which is maxed out. What helps?', opts: ['Copy the hot key to several nodes or a local cache', 'Add nodes to the ring so the load spreads further', 'Lower its TTL so the value is refreshed more often', 'Move from Memcached to Redis for faster reads per key'], a: 0, no: [null, 'A single key still hashes to a single node, however many nodes the ring has.', 'A shorter TTL adds misses and database load; it does nothing for the reads hitting that one node.', 'Redis runs commands on one thread, so it is not faster per key; Memcached is multithreaded. Either way, one node still serves it all.'], why: 'Consistent hashing spreads keys, not one key\'s traffic. Replicate the hot key under several names (key#1, key#2) on different nodes, or keep a short-lived copy in each app server\'s memory.' },
  { id: 'qb-dcache2', c: 'dcache', type: 'mc', q: 'A popular key expires, and 5,000 requests miss at the same instant and all query the database. What helps most?', opts: ['Write-through caching, so every write also updates the cache', 'One request reloads the key while the rest wait for its result', 'A shorter TTL on the key, so it is reloaded more often', 'LFU eviction, so frequently used keys are kept in memory'], a: 1, no: ['Write-through keeps the cache fresh on writes, but a key that expires still misses on read.', null, 'A shorter TTL makes the key expire more often, so the stampede happens more often.', 'Eviction decides what to drop when memory is full. This key expired by TTL, which LFU does not prevent.'], why: 'Request coalescing (single flight) lets only one caller rebuild the value while the others wait for that answer, so the database sees one query, not 5,000. A lock with a short expiry on the key does the same across servers.' },
  { id: 'qb-dcache3', c: 'dcache', type: 'mc', q: 'After a feature launch the cache hit rate drops from 95% to 70%. No node failed, and the evictions metric is climbing. Why?', opts: ['The ring rehashed, moving most keys to different nodes', 'Network latency rose, so slow reads time out as misses', 'Clients started using write-through, which skips reads', 'The working set outgrew memory, evicting keys still in use'], a: 3, no: ['The ring changes only when nodes join or leave, and none did. A ring change would also not raise evictions.', 'Timeouts can look like misses, but they would not make the cache evict more keys.', 'Write-through is about how writes reach the cache; reads still go to the cache first.', null], why: 'Evictions mean the cache is full and dropping keys to make room, here keys that are still wanted. The new feature added data, so add memory or nodes, or cache less per item.' },
  { id: 'qb-dcache4', c: 'dcache', type: 'mc', q: 'You run Redis with a replica for each shard. A primary dies at peak. Why does the database not get a miss storm?', opts: ['Its append-only file reloads every key the moment it dies', 'Its keys spread over the other shards, still cached', 'Clients keep retrying the dead node until it returns', 'Its replica is promoted and already holds those keys'], a: 3, no: ['The AOF helps a restarted node recover, but replaying it takes time, and nothing is served while the node is down.', 'Keys that move to other shards arrive there empty, so they miss; that is exactly the storm.', 'Retrying a dead node only adds delay and load; meanwhile the requests fail or fall through.', null], why: 'A promoted replica already has (nearly) all the shard\'s keys, so reads keep hitting the cache. Without replicas, the dead node\'s keys all miss together and fall through to the database.' },
  { id: 'qb-dcache5', c: 'dcache', type: 'mc', q: 'With cache-aside, a write updates a user in the database. What should it do with the cached copy so readers do not see old data for long?', opts: ['Update the cached value first, then the database', 'Leave it, and let the key\'s TTL catch up', 'Delete the key, so the next read reloads it', 'Write only to the cache, and flush to the database later'], a: 2, no: ['If the database write then fails, the cache holds a value the database never had.', 'That serves stale data for up to a whole TTL. TTLs are a safety net, not the main way to stay fresh.', null, 'That is write-back caching: fast, but a cache node loss loses writes. It is a different pattern from cache-aside.'], why: 'In cache-aside the app owns the cache: after writing the database it deletes the key, and the next read misses and loads the fresh row. Deleting beats overwriting: when two writers race, an overwrite can leave the older value cached, while a delete costs only one extra miss.' },
  // collab: Collaborative Editing
  { id: 'qb-collab1', c: 'collab', type: 'mc', q: 'Why does a Google Docs-style operational transformation editor run edits through a central server?', opts: ['The server picks one order, which each transform is defined against', 'Clients need the server to hand out unique IDs for each character', 'The server locks each paragraph while someone is typing in it', 'OT edits are too large to send directly between peers'], a: 0, no: [null, 'Unique per-character IDs are how CRDTs work, and they are generated locally without a server.', 'Locking would stop two people typing in one place. OT lets them type at once and transforms the edits.', 'OT edits are small (insert "x" at 5). Size is not the reason; ordering is.'], why: 'OT transforms each edit against the concurrent ones it has not seen, which is simplest when one server fixes a single order of operations. CRDTs avoid the need for that server.' },
  { id: 'qb-collab2', c: 'collab', type: 'mc', q: 'What is the main cost of a CRDT-based text editor compared with OT?', opts: ['Extra metadata: per-character IDs, plus tombstones for deletes', 'Every edit must reach a server before it can show on screen', 'Replicas can end with different text after they all merge', 'Edits made offline are rejected when the device reconnects'], a: 0, no: [null, 'CRDT edits apply locally at once and sync later; that is their selling point for offline use.', 'Convergence is the guarantee CRDTs give: replicas that have seen the same edits hold the same text.', 'Offline edits merge cleanly on reconnect. Rejecting them would be a locking or version-check design.'], why: 'Each character carries a unique ordered ID, and deleted characters often stay as tombstones so late edits can still find their place. Documents grow larger than their text, and compaction takes extra work.' },
  { id: 'qb-collab3', c: 'collab', type: 'mc', q: 'Editors of one document connect through a round-robin load balancer, so they land on different servers. Edits conflict and diverge. What do you change?', opts: ['Use sticky sessions keyed on each user\'s IP address', 'Raise the balancer timeout so sockets stay open longer', 'Route every editor of a document to its one session server', 'Save whole documents with last-write-wins instead'], a: 2, no: ['Sticky sessions keep one user on one server, but two users of the same document still land on different ones.', 'Longer-lived sockets do not help: the problem is which server each editor reaches, not how long it stays.', null, 'Last-write-wins on whole documents throws away someone\'s work, which is what collaborative editing is meant to avoid.'], why: 'OT needs one place that sees every edit to a document in order. Route by document ID (for example with consistent hashing) so all its editors share one session server.' },
  { id: 'qb-collab4', c: 'collab', type: 'mc', q: 'Live cursor moves are about 20 times as frequent as edits, and storing them is slowing document saves. What is the fix?', opts: ['Transform cursor moves with OT so they stay in order', 'Send cursors as ephemeral messages that are not stored', 'Fold the cursor positions into a snapshot every second', 'Fetch other users\' cursors with an HTTP poll instead'], a: 1, no: ['Cursors do need adjusting as text shifts, but that can happen on the client; running them through the edit pipeline adds load.', null, 'A cursor is useless a second later, so writing it into the document, even batched, still stores data nobody needs.', 'Polling makes cursors laggy and adds requests; the open WebSocket can already carry them.'], why: 'Cursors and presence are ephemeral: only the latest position matters. Broadcast them over the session\'s WebSocket and keep them out of the stored edit log, dropping stale updates freely.' },
  { id: 'qb-collab5', c: 'collab', type: 'mc', q: 'An old, busy document takes 30 seconds to open because the server replays 2 million edits from the start. What fixes it?', opts: ['Save periodic snapshots; replay only later edits', 'Switch from OT to a CRDT so no replay is needed', 'Cache the edit log in Redis so replay reads from memory', 'Send all 2 million edits to the client to replay itself'], a: 0, no: [null, 'A CRDT replica still has to load its full state or history; switching algorithms does not remove the need for snapshots.', 'Faster storage helps a little, but applying 2 million edits is still the bottleneck.', 'That moves the same work to a slower device and costs far more bandwidth.'], why: 'Snapshot the document every so often and record which edit it reflects. Opening then loads the latest snapshot and applies only the few edits after it.' },
  // dns: DNS & GeoDNS
  { id: 'qb-dns1', c: 'dns', type: 'mc', q: 'GeoDNS health checks drop a dead region from its answers within a minute, yet some users keep hitting the dead region for half an hour. The record TTL is 30 minutes. Why?', opts: ['Resolvers keep serving the answer they cached until its TTL runs out', 'The registrar has to approve each change, which takes about half an hour', 'Root servers cache your records and only refresh them every 30 minutes', 'GeoDNS pins each user to one region for 30 minutes to keep sessions sticky'], a: 0, no: [null, 'The registrar only holds which name servers are authoritative. Changing a record on your own name servers needs no approval.', 'Root servers only point to the top-level domain servers. They never hold or cache your own records.', 'GeoDNS answers every query fresh. The stickiness comes from caching resolvers, not from the DNS server keeping sessions.'], why: 'Taking a region out of the answers only affects new lookups. Resolvers that cached the old answer keep handing it out for the TTL, which is why failover records use short TTLs.' },
  { id: 'qb-dns2', c: 'dns', type: 'mc', q: 'Users in Brazil who use a public resolver hosted in the US are being sent to your US region by GeoDNS. What is the most likely cause?', opts: ['GeoDNS ranks regions by load, so it picked the idle US region', 'The record TTL is too long, so the first answer stuck for everyone', 'GeoDNS sees where the resolver is, not where the user is', 'The ISP rewrites DNS answers to point at its own cache servers'], a: 2, no: ['GeoDNS steers by the asker\'s location and region health. Load-aware steering is a separate weighted-routing feature.', 'A long TTL explains slow changes, not why the answer pointed to the wrong region in the first place.', null, 'Some ISPs rewrite failed lookups, but that would not send users to your own US region.'], why: 'A GeoDNS server only sees the resolver that asks it. The EDNS Client Subnet extension passes part of the user\'s address along; anycast avoids the problem because routing follows the user\'s own packets.' },
  // multiregion: Multi-Region & Failover
  { id: 'qb-multiregion1', c: 'multiregion', type: 'mc', q: 'You replicate writes synchronously between Virginia and Frankfurt, about 90 ms apart. What is the main cost?', opts: ['A failover can lose the last few seconds of acknowledged writes', 'Every write waits at least one ocean round trip before it is acknowledged', 'Each region holds only half the data, since the copies split the rows', 'Every read must also ask both regions and wait for the slower one'], a: 1, no: ['That is the risk of asynchronous replication. Synchronous replication avoids it, which is why teams pay its latency.', null, 'That describes sharding by key, not replication. Both regions hold a full copy.', 'Reads can be served from the local copy. Asking both regions is a quorum read, a separate choice.'], why: 'Synchronous replication acknowledges a write only after the far region has it, so each write pays the cross-ocean round trip. That is the price of losing nothing on failover.' },
  { id: 'qb-multiregion2', c: 'multiregion', type: 'mc', q: 'The link between two regions drops. The standby cannot see the primary and promotes itself, though the primary is alive. Both now take writes. What prevents this?', opts: ['Shorter health checks, so the standby notices failures sooner', 'GeoDNS health checks, so users only reach the region that is up', 'Async replication with a tighter lag target, so less can diverge', 'A quorum or witness in a third site that decides who is primary'], a: 3, no: ['Faster detection makes false promotions during a network blip more likely, not less.', 'Both regions look healthy from the internet. DNS cannot tell which one should be primary.', 'Lower lag means less data lost on a real failover, but two primaries still diverge once both accept writes.', null], why: 'This is split brain. A third vote (a quorum, a witness or a consensus store) lets only the side that can reach a majority stay or become primary, and the other side fences itself.' },
  // observe: Monitoring & Alerting
  { id: 'qb-observe1', c: 'observe', type: 'mc', q: 'The average latency dashboard is flat at 80 ms, yet users keep reporting that the site feels slow. What should you look at first?', opts: ['The p99 latency, since an average hides a slow tail', 'The CPU of each host, since it is the root cause', 'The error rate, since slow requests are logged as errors', 'The request rate, since rising traffic slows every request'], a: 0, no: [null, 'CPU is a cause, not a symptom. Start from what users feel, then dig into causes.', 'A slow request that succeeds is not an error. Latency and errors are separate golden signals.', 'Traffic matters for saturation, but a flat average says most requests are fine; the slow ones hide in the tail.'], why: 'One request in a hundred taking 3 seconds barely moves the average. Latency percentiles such as p95 and p99 show the tail that users complain about.' },
  { id: 'qb-observe2', c: 'observe', type: 'mc', q: 'Checkout p99 jumped from 300 ms to 2 s. Checkout calls six services. What finds the slow one fastest?', opts: ['Grep the logs of all six services for errors around that time', 'Compare the CPU dashboards of the six services side by side', 'Turn on debug logging everywhere and replay some checkouts', 'Open traces of slow checkouts and see which span grew'], a: 3, no: ['Slow calls often log no error, and logs from six services do not line up by request without a trace ID.', 'A service can be slow while its CPU looks normal, for example when it waits on a lock or a database.', 'Debug logs add load and noise, and replaying may not hit the slow path. They help once you know where to look.', null], why: 'A trace follows one request through every service and times each hop as a span, so the span that grew points straight at the culprit.' },
  { id: 'qb-observe3', c: 'observe', type: 'mc', q: 'Your SLO is 99.9% success over 30 days. For the last hour the error rate has been a steady 1%. How fast is the budget burning?', opts: ['Burn rate 1: on track to use exactly a month of budget', 'Burn rate 10: the budget is gone in about 3 days', 'Burn rate 100: the budget is gone in about 7 hours', 'Burn rate 0.1: well inside the budget for the month'], a: 1, no: ['Burn rate 1 would be an error rate equal to the budget, 0.1%. This is ten times that.', null, 'That would need a 10% error rate. 1% against a 0.1% budget is a burn rate of 10.', 'That would be an error rate of 0.01%. The budget allows 0.1%, and 1% is far above it.'], why: 'The error budget is 0.1%, so a 1% error rate burns it 10 times too fast: 30 days of budget in about 3. Burn-rate alerts page on exactly this kind of number.' },
  { id: 'qb-observe4', c: 'observe', type: 'mc', q: 'A team adds user_id as a label on every request metric, so they can graph any user. What breaks next?', opts: ['Traces stop joining up, since user IDs collide with trace IDs', 'Logs lose the user_id field, since it moved into the metrics', 'The metrics store struggles with millions of new time series', 'Latency histograms stop working, since labels split the buckets'], a: 2, no: ['Trace IDs are separate random values. Adding a metric label has no effect on how traces join.', 'Metric labels and log fields are independent. Logs keep whatever fields you write.', null, 'Histograms work fine with labels. The problem is how many label combinations there are.'], why: 'Every distinct label value creates a new time series, so a high-cardinality label like user_id explodes storage and query cost. Per-user detail belongs in logs and traces.' },
  // deploy: Safe Deploys
  { id: 'qb-deploy1', c: 'deploy', type: 'mc', q: 'One release stops writing a column and drops it. The deploy rolls out over 20 minutes. What breaks during the rollout?', opts: ['New instances fail, since the column is still in the schema', 'Old instances still read the column and start throwing errors', 'Nothing, since a rolling deploy swaps every instance at once', 'The migration locks the table until all old instances stop'], a: 1, no: ['New code that no longer uses the column does not care whether it exists.', null, 'A rolling deploy replaces instances in batches, so old and new code run side by side for its whole length.', 'Dropping a column takes a brief lock, but it does not wait for app instances to stop.'], why: 'During a rolling deploy old code is still live. Expand-then-contract drops the column only in a later release, once no running version touches it.' },
  { id: 'qb-deploy2', c: 'deploy', type: 'mc', q: 'Compared with a rolling deploy, what is the main cost of blue-green?', opts: ['Rollback takes as long as the original deploy did', 'Users see a mix of old and new versions mid-rollout', 'You need double the capacity while both versions run', 'It cannot be combined with any database schema change'], a: 2, no: ['That is a weakness of rolling deploys. Blue-green rolls back by switching traffic back in one step.', 'That happens during rolling and canary deploys. Blue-green switches all traffic at once.', null, 'It works with expand-then-contract migrations, since both versions share one database that suits either.'], why: 'Blue-green keeps a full copy of the old version running beside the new one, so rollback is one switch, but you pay for two environments during the switch.' },
  { id: 'qb-deploy3', c: 'deploy', type: 'mc', q: 'The service gets 200 requests a minute. Your canary takes 1% for 10 minutes, shows zero errors, and ramps to 100%. What is wrong with this plan?', opts: ['About 20 requests is too few to tell a bad build from noise', 'The canary should take half the traffic to match the baseline', 'It should be compared with yesterday\'s numbers, not today\'s', 'Ten minutes is too long, since the canary\'s caches go stale'], a: 0, no: [null, 'A 50/50 split is no longer a small slice, so a bad build hurts half your users.', 'Compare with the baseline running right now, under the same traffic. Yesterday had different load and users.', 'Caches warming is a reason to wait longer, not shorter. Staleness is not a canary risk.'], why: 'A canary needs enough requests to show a real difference in errors and latency. With low traffic, give it a larger slice or a longer soak before widening.' },
  { id: 'qb-deploy4', c: 'deploy', type: 'mc', q: 'Your team has used feature flags for two years. What is the main ongoing cost they bring?', opts: ['Old flags pile up, leaving branches of code nobody tests', 'Each flag check adds a network round trip to every request', 'Flagged code has to wait on its own branch until it is on', 'Changing a flag needs a new deploy of the service each time'], a: 0, no: [null, 'Flag SDKs cache the rules and evaluate them in process, so a check costs microseconds.', 'Flags let unfinished code merge to the main branch, switched off. That is their point.', 'Flags are flipped at runtime from a config service. Needing a deploy is what they remove.'], why: 'Every flag doubles a code path. Flags left on or off for good become dead branches and surprise combinations, so teams remove them once a rollout is done.' },
  // video: Video Streaming
  { id: 'qb-video1', c: 'video', type: 'mc', q: 'You cut video segments from 6 seconds to 1 second. What is the trade-off?', opts: ['Faster startup and switching, but more requests and worse compression', 'Better compression per segment, but players must buffer more of them', 'Fewer CDN requests, but each edge needs more storage for the files', 'Lower storage cost, but no change to startup or quality switching'], a: 0, no: [null, 'Each segment must start with a full keyframe, so shorter segments compress worse, not better, and players buffer less.', 'More segments mean more requests and manifest entries for the CDN to handle, not fewer.', 'Players switch rendition per segment and buffer whole segments, so length shapes startup and switching. Storage grows slightly, if anything.'], why: 'Short segments let a player start and change quality sooner, which live streams want. The price is a request per second per viewer and a keyframe in every segment.' },
  { id: 'qb-video2', c: 'video', type: 'mc', q: 'Users upload 4 GB videos to your API servers, which then copy them into object storage. The API fleet keeps running out of memory. What fixes it?', opts: ['Route uploads through the CDN, which caches them at the edge', 'Gzip each video on the API server before it goes to storage', 'Store the videos as database blobs so transcoders can query them', 'Hand out presigned URLs so clients upload straight to storage'], a: 3, no: ['A CDN serves and caches content for viewers. It is not where uploads should be stored.', 'Video is already compressed, so gzip saves almost nothing and adds more CPU to the API servers.', 'Databases are a poor home for multi-gigabyte blobs. Keep large files in object storage and their metadata in the database.', null], why: 'A presigned URL lets the client send the file straight to object storage, so API servers only handle the small metadata request. Storage events can then trigger transcoding.' },
  { id: 'qb-video3', c: 'video', type: 'mc', q: '1% of videos get 90% of the views; millions of others are watched rarely. How should the CDN handle the rarely watched ones?', opts: ['Push every video to every edge, so all of them load equally fast', 'Let edges pull them on demand, from origin or a regional cache', 'Serve them straight from the transcoding workers that made them', 'Delete any video that gets no views for 30 days to save space'], a: 1, no: ['Copying millions of rarely watched videos to every edge costs huge storage for almost no hits.', null, 'Transcoders are batch workers, not a serving tier. Finished renditions live in object storage behind the CDN.', 'That loses users\' videos. The CDN evicts cold content by itself while origin keeps the master copy.'], why: 'Push the head before it is asked for, and let the long tail be pulled on first request, often through a mid-tier cache that shields the origin.' },
  { id: 'qb-video4', c: 'video', type: 'mc', q: 'A 2-hour video is split into 200 chunks for parallel transcoding. One worker dies halfway through its chunk. How should the pipeline recover with the least rework?', opts: ['Restart the whole video, so all the chunks stay consistent', 'Mark the video failed and ask the user to upload it again', 'The queue redelivers that unfinished chunk to another worker', 'Transcode every chunk twice from the start, on two workers'], a: 2, no: ['Throwing away 199 finished chunks wastes hours of work. Chunks are independent until stitching.', 'The upload is safe in object storage. A worker crash is not the user\'s problem.', null, 'Doing everything twice doubles the cost to guard against a rare failure. Retrying the lost job is enough.'], why: 'Each chunk is a job in the queue, acknowledged only when done. A dead worker never acks, so its chunk times out and goes to another worker.' },
  // crawler: Web Crawlers
  { id: 'qb-crawler1', c: 'crawler', type: 'mc', q: 'Your crawler\'s seen-URL set is a Bloom filter. What mistake does it make?', opts: ['It can miss a URL it has seen, so a few pages are fetched twice', 'It skips a few new URLs, wrongly thinking they were seen', 'Each lookup slows down as more URLs are added to the filter', 'It grows without limit and must be rebuilt every few hours'], a: 1, no: ['A Bloom filter has no false negatives: a URL that was added always tests as present.', null, 'Each lookup checks a fixed number of bits, so it stays constant time as the filter fills.', 'Its size is fixed when you create it. As it fills, the false positive rate rises instead.'], why: 'A Bloom filter can say yes for a URL it never saw, so a small share of new pages are skipped. That is an acceptable trade for fitting billions of URLs in little memory.' },
  { id: 'qb-crawler2', c: 'crawler', type: 'mc', q: 'You have 1,000 fetchers, but 80% of the frontier belongs to one huge site and crawl throughput has stalled. Why?', opts: ['The parsers are behind, since huge sites have bigger pages', 'The seen-set Bloom filter is full, so new URLs are rejected', 'That site\'s robots.txt is blocking most of the queued URLs', 'The per-site delay caps that site, however many fetchers you add'], a: 3, no: ['Page size varies by page, not by how big the site is. Slow parsers would back up a queue, not idle the fetchers.', 'A full Bloom filter wrongly skips URLs; it would shrink the frontier, not stall it.', 'Disallowed URLs are dropped before queuing, so they would not fill the frontier.', null], why: 'Politeness allows one site only so many requests a second. A good frontier mixes many sites so fetchers always have a polite host to hit.' },
  { id: 'qb-crawler3', c: 'crawler', type: 'mc', q: 'You keep one queue per domain with a 1-second delay. A shared host serves 5,000 small sites from one IP address. What happens?', opts: ['The host gets thousands of hits a second; limit per IP too', 'Each site gets 1 request a second, which is polite', 'robots.txt on each site already throttles the shared host', 'The host is safe, since DNS spreads the sites across servers'], a: 0, no: [null, 'Per site, yes, but the shared server takes all 5,000 queues at once.', 'robots.txt says what to crawl and sometimes a crawl delay per site; it does not add up load across sites.', 'Here DNS gives the same IP for all 5,000 sites, so every request lands on one machine.'], why: 'Politeness is about the server, not the name. Crawlers group queues by IP address or host as well as domain so one machine is not overwhelmed.' },
  { id: 'qb-crawler4', c: 'crawler', type: 'mc', q: 'Parsing is slower than fetching: fetchers sit idle while the parse queue grows. What does the queue-based design let you do?', opts: ['Add more fetchers, since faster fetching speeds up the parse stage', 'Lower the per-site delay so pages arrive faster for the parsers', 'Add parser workers on their own, with the queue absorbing the bursts', 'Merge parsing into the fetchers, so no queue sits between them'], a: 2, no: ['The fetchers already outrun the parsers. More of them only grows the backlog.', 'That breaks politeness and feeds even more pages to the stage that is already behind.', null, 'That ties the two together so they can no longer scale apart, which is what the queue was for.'], why: 'Fetchers, parsers and storage sit behind queues so each stage scales on its own. Scale the bottleneck stage, and let the queue buffer the difference.' },
  // notify: Notification Systems
  { id: 'qb-notify1', c: 'notify', type: 'mc', q: 'Marketing schedules a push for 9 a.m. UTC to users worldwide. What should the fan-out do?', opts: ['Send at 9 a.m. UTC; phones mute alerts at night anyway', 'Send by each user\'s local time, respecting quiet hours', 'Split users into four batches to spread the provider load', 'Hold each push until that user next opens the app'], a: 1, no: ['Not every phone uses do-not-disturb, and quiet hours are your promise to the user, not the phone\'s.', null, 'Batching helps with provider rate limits but still wakes people at 3 a.m. in other time zones.', 'That turns it into an in-app message. Fine for some content, but it is not a push.'], why: 'Fan-out workers check each user\'s preferences and quiet hours, so a global campaign becomes many local sends scheduled by time zone.' },
  { id: 'qb-notify2', c: 'notify', type: 'mc', q: 'APNs returns "unregistered" for 8% of the device tokens in a campaign. What should you do?', opts: ['Retry them with exponential backoff until they get through', 'Send those users an SMS instead, so the message still lands', 'Move them to the dead-letter queue for an engineer to check', 'Delete those tokens so later sends skip those devices'], a: 3, no: ['Backoff suits temporary errors. An unregistered token is permanent: the app was removed or the token changed.', 'Switching channels needs the user\'s consent and costs money per SMS. Respect channel preferences.', 'Dead letters are for unexpected failures to inspect. This is a normal, expected answer from the provider.', null], why: 'The provider is saying the token is gone. Removing it saves wasted sends and keeps your sender reputation with the provider healthy.' },
  { id: 'qb-notify3', c: 'notify', type: 'mc', q: 'Your email provider is down for 20 minutes. What should happen to the emails waiting to go out?', opts: ['Wait in the queue and retry with backoff once it recovers', 'Drop them, since a late notification is worse than none', 'Retry each one at once in a tight loop until it succeeds', 'Send each one as a push notification instead of an email'], a: 0, no: [null, 'Most notifications, like receipts, are still useful 20 minutes late. Expiry suits only time-bound ones.', 'A tight retry loop hammers the provider as it recovers. Backoff with jitter, or a circuit breaker, avoids that.', 'Channels are the user\'s choice, and not every email has a push equivalent.'], why: 'The queue is the buffer. Messages stay there and retry with exponential backoff; a circuit breaker can pause sends until the provider answers again.' },
  { id: 'qb-notify4', c: 'notify', type: 'mc', q: 'A user\'s photo goes viral and they get 200 "someone liked your photo" pushes in an hour. What is the fix?', opts: ['Use idempotency keys so the repeated pushes are dropped', 'Batch them into a digest such as "Sam and 199 others"', 'Rate-limit the people liking so they cannot like so fast', 'Send them over SMS, which users read more reliably'], a: 1, no: ['Each like is a distinct event with its own key. Idempotency stops retries of the same message, not many real ones.', null, 'The likes are fine; the problem is how many messages the owner receives.', 'That moves the flood to a costlier channel and annoys the user just as much.'], why: 'Batching and per-recipient rate limits turn a noisy stream into one useful message, which keeps users from turning notifications off.' },
  { id: 'qb-notify5', c: 'notify', type: 'mc', q: 'Login codes (OTPs) share one queue with a 30-million-user marketing push, and users wait minutes for their codes. What is the fix?', opts: ['Add more fan-out workers so the big queue drains faster', 'Give each OTP an idempotency key so it skips ahead', 'Make the queue LIFO, so the newest messages go first', 'Give urgent messages their own queue and workers'], a: 3, no: ['More workers help, but the provider rate limit still caps the drain, and the codes wait behind it.', 'An idempotency key stops double sends; it does not change queue order.', 'LIFO starves older messages and sends campaigns out of order. Priority should come from the message type.', null], why: 'Separate queues by priority, a bulkhead, so a bulk campaign can never delay time-critical messages like login codes.' },
  // llmserve: Serving an LLM
  { id: 'qb-llmserve1', c: 'llmserve', type: 'mc', q: 'Users paste 50-page documents into your chatbot. Tokens per second after the first token look fine, but the first token takes 8 seconds. Why?', opts: ['The whole long prompt is processed before token one', 'Continuous batching holds it until the batch finishes', 'The max_tokens limit is set too high for these chats', 'Quantized models are slow to produce the first token'], a: 0, no: [null, 'That is static batching. Continuous batching adds new requests between steps.', 'max_tokens only caps how long the answer may get. It does not delay the start.', 'Quantization usually makes every step faster, since there is less memory to read.'], why: 'Before the first token the model must read the whole prompt, the prefill. A 50-page prompt makes that slow; prompt caching or retrieving only the relevant parts helps.' },
  { id: 'qb-llmserve2', c: 'llmserve', type: 'mc', q: 'You keep raising the batch size on a GPU. What eventually limits how many conversations fit?', opts: ['The weights, since each chat loads its own copy', 'KV cache memory, which grows with each chat\'s length', 'CPU cores, since each chat needs one to tokenize', 'Network bandwidth for streaming tokens to users'], a: 1, no: ['All conversations share one copy of the weights on the GPU.', null, 'Tokenizing is cheap and fast. It does not tie up a core per conversation.', 'A few tokens a second per user is tiny traffic compared with what one server can send.'], why: 'Each conversation keeps a KV cache that grows with every token. GPU memory left after the weights caps the batch, which is why servers page the cache in blocks.' },
  { id: 'qb-llmserve3', c: 'llmserve', type: 'mc', q: 'Bigger batches raise total tokens per second on each GPU. What does each user pay for it?', opts: ['Each user\'s tokens arrive more slowly as steps get longer', 'Lower answer quality, since the chats share one pass', 'Chats can leak into each other through a shared cache', 'Each answer gets shorter, since the token budget is split up'], a: 0, no: [null, 'Each conversation is computed separately inside the batch, so answers do not get worse.', 'Each conversation has its own KV cache. Only identical prompt prefixes are ever shared.', 'Each request keeps its own max_tokens limit. Batching shares GPU steps, not answer length.'], why: 'A larger batch makes each step take longer, so throughput rises while per-user tokens per second falls. Servers tune the batch to meet a latency target.' },
  // rag: Retrieval (RAG)
  { id: 'qb-rag1', c: 'rag', type: 'mc', q: 'Users ask about error code "E-4012", and the RAG bot retrieves chunks about errors in general instead of that code. What fixes it?', opts: ['Bigger chunks, so the code appears in more of them', 'Exact search instead of HNSW, so no match is missed', 'Add keyword search such as BM25 beside the vectors', 'A higher temperature, so the model looks further'], a: 2, no: ['Bigger chunks dilute the code further, so the vector matches it even less.', 'Exact search finds the same nearest embeddings. The embedding itself blurs rare codes into general meaning.', null, 'Temperature changes how the model writes, not what retrieval finds.'], why: 'Embeddings capture meaning, so rare exact strings like codes and names get lost. Hybrid search adds keyword matching and merges both result lists.' },
  { id: 'qb-rag2', c: 'rag', type: 'mc', q: 'You add a cross-encoder reranker that rescores the top 50 retrieved chunks. What is its main cost?', opts: ['All documents need re-embedding with the reranker\'s model', 'More latency per query, since it runs a model on each pair', 'The vector index has to be rebuilt as a flat, exact index', 'The context window must grow to fit all 50 chunks at once'], a: 1, no: ['A reranker reads the question and chunk text together at query time. The stored embeddings stay as they are.', null, 'The reranker works on whatever the index returns. HNSW still does the first, fast pass.', 'Reranking lets you send fewer, better chunks to the model, not more.'], why: 'A cross-encoder scores each question and chunk pair with a model call, which is more accurate but costs time, so it only runs on a short list.' },
  // evals: Evals
  { id: 'qb-evals1', c: 'evals', type: 'mc', q: 'Your golden set scores 98%, yet users keep complaining about wrong answers. What is the most likely problem?', opts: ['The set lacks the hard and adversarial questions users ask', 'The set is too large, so the real failures average out', 'Exact-match grading is too lenient for open-ended answers', 'The LLM judge is too strict, so it pulls the score down'], a: 0, no: [null, 'A larger set gives a more reliable score. It does not hide failures that the set contains.', 'Exact match is strict, not lenient. It marks good answers with other wording as wrong.', 'A strict judge would give a low score, not a high one users disagree with.'], why: 'A golden set only measures what it contains. Fill it from real traffic, including hard, ambiguous and adversarial cases, and add every bug you find.' },
  { id: 'qb-evals2', c: 'evals', type: 'mc', q: 'You use an LLM judge to grade open answers. How do you know its grades can be trusted?', opts: ['Use the same model as the one being graded, so it knows the style', 'Ask it to explain each score; longer reasons mean more certainty', 'People grade a sample and you check how often the judge agrees', 'Run the judge at temperature 0 so its scores come out correct'], a: 2, no: ['Models tend to prefer their own style, so self-grading inflates the scores.', 'Asking for reasons can help a judge, but their length says nothing about accuracy.', null, 'Temperature 0 makes scores more repeatable, not more correct. A biased judge stays biased.'], why: 'Calibrate the judge against human labels on a sample, and recheck now and then. Where they disagree, fix the rubric or the judge prompt.' },
  { id: 'qb-evals3', c: 'evals', type: 'mc', q: 'Which of these answers should be graded by code, not by a rubric or an LLM judge?', opts: ['Whether a support reply has a friendly tone', 'The order total and delivery date it quotes', 'Whether a summary covers the key points', 'Whether the answer suits a beginner reader'], a: 1, no: ['Tone is open-ended and needs a rubric, graded by people or an LLM judge.', null, 'Coverage is a judgement call, so it suits a rubric with a judge.', 'Fit for a reader is subjective and needs a rubric, not a string check.'], why: 'Exact facts have one right value, so code can check them cheaply and reliably. Save judges for open qualities like tone and completeness.' },
  { id: 'qb-evals4', c: 'evals', type: 'mc', q: 'A team tweaks the prompt 40 times against the same 100 questions until it scores 100%. What is the risk?', opts: ['The LLM judge learns the answers and starts grading too kindly', 'The provider caches the answers, so later runs test nothing new', 'The prompt is overfit to those 100 and may not carry over', 'The golden answers drift, since each run quietly rewrites them'], a: 2, no: ['A judge does not learn between calls. Each grading call starts fresh.', 'Prompt caching reuses processed input, not finished answers, so each run still generates new output.', null, 'Golden answers are fixed data you wrote. Runs read them and never change them.'], why: 'Tuning against one set teaches the prompt that set, like training on the test data. A held-out set that you rarely look at shows whether the gain is real.' },
  { id: 'qb-evals5', c: 'evals', type: 'mc', q: 'A new prompt beats the old one by 4 points on the golden set. What should you do before rolling it out to everyone?', opts: ['Ship it to everyone, since the golden set already proved it', 'Re-run the golden set ten more times to make sure of the gain', 'Ask the LLM judge to predict which prompt users will prefer', 'A/B test it on live traffic, watching thumbs and escalations'], a: 3, no: ['Offline wins do not always carry over. The set may miss what real users ask.', 'Repeats reduce noise, but on the same questions. They cannot show how real traffic responds.', 'A judge grades answers against a rubric. It cannot stand in for real users\' behaviour.', null], why: 'Offline evals gate the change; online signals confirm it. An A/B test on a slice of traffic compares thumbs, escalations and retention for real.' },
  // guardrails: Guardrails
  { id: 'qb-guardrails1', c: 'guardrails', type: 'mc', q: 'A bot summarises web pages and its output is shown as markdown. A page tells it to add an image whose URL contains the user\'s data. What stops the leak?', opts: ['A system prompt saying never to put user data in links', 'An allow-list of domains that images and links may load from', 'Moderation on the page text, to catch harmful content', 'A rate limit on how many pages the bot reads a minute'], a: 1, no: ['Instructions in the prompt can be overridden by the injected text. They help but cannot be relied on.', null, 'Moderation catches toxic or unsafe text. A polite request to add an image passes it.', 'Rate limits curb abuse volume; one page is enough for this attack.'], why: 'The browser fetching the image is what sends the data out. Checking output and only loading links from trusted domains removes the channel, whatever the model was told.' },
  { id: 'qb-guardrails2', c: 'guardrails', type: 'mc', q: 'A support bot needs to look up the signed-in customer\'s orders. What database access should its tool get?', opts: ['A tool that returns only the signed-in customer\'s orders', 'Read-only SQL on the orders table, with queries written by the model', 'Full access, with a prompt telling it to query one customer', 'Read access to a nightly copy of the whole database'], a: 0, no: [null, 'Read-only still lets an injected prompt read every other customer\'s orders.', 'A prompt is not a permission. Injected text can override it.', 'A copy still holds every customer\'s data, so a leak is just as bad.'], why: 'Least privilege: the tool, not the model, binds the query to the signed-in user, so even a hijacked model can only see that customer\'s orders.' },
  { id: 'qb-guardrails3', c: 'guardrails', type: 'mc', q: 'Your input filter blocks "ignore previous instructions". Attackers still get injections through. Why?', opts: ['The same order can be phrased endless ways, even in other languages', 'Attackers use HTTPS, so the filter never sees the text they send', 'The tokenizer splits the phrase, so the filter cannot match it', 'Filters run after the model has acted, so they are always too late'], a: 0, no: [null, 'TLS protects data in transit. Your server decrypts it before any filter runs.', 'Filters run on the raw text before tokenizing, so splitting does not hide the phrase.', 'Input filters run before the model sees the text. Timing is not why they miss.'], why: 'Natural language has no fixed syntax to block, so filters only catch known phrasings. That is why designs limit damage with least privilege and confirmation.' },
  { id: 'qb-guardrails4', c: 'guardrails', type: 'mc', q: 'An assistant summarises the user\'s incoming emails. How should the app pass each email to the model?', opts: ['In the system prompt, so the model treats it with authority', 'Base64-encoded, so any orders inside cannot be read as text', 'Before the instructions, so the instructions come last and win', 'Wrapped and labelled as untrusted data, apart from instructions'], a: 3, no: ['The system prompt is for your own instructions. Putting untrusted text there gives it the most authority.', 'Models can decode base64, and an encoded email cannot be summarised well anyway.', 'Order may shift the odds slightly, but it is not a boundary an attacker respects.', null], why: 'Keeping untrusted text clearly marked as data lowers the chance the model obeys it. It is not a guarantee, so pair it with least privilege and human confirmation.' },
  // llmcost: LLM cost & caching
  { id: 'qb-llmcost1', c: 'llmcost', type: 'mc', q: 'Each request has a 1,000-token prompt and a 500-token answer. Output tokens cost 4 times as much as input tokens. Which dominates the bill?', opts: ['The input, since it has twice as many tokens', 'The output, at about two-thirds of the cost', 'Neither: they cost the same per request', 'The input, since output tokens are cached'], a: 1, no: ['Twice the tokens at a quarter of the price: 1,000 units of input against 2,000 of output.', null, 'Providers bill input and output tokens separately, at different prices.', 'Caching discounts repeated input prefixes. Output is generated fresh every time.'], why: 'Input is 1,000 x 1 = 1,000 units and output is 500 x 4 = 2,000, so output is two-thirds. Capping answer length often saves more than trimming the prompt.' },
  { id: 'qb-llmcost2', c: 'llmcost', type: 'mc', q: 'To raise the hit rate, you loosen your semantic cache\'s similarity threshold. What goes wrong?', opts: ['Each entry stores more vectors, so the cache runs out of memory', 'Looser matches take longer to search, so latency climbs', 'Different questions get each other\'s answers, for everyone', 'The provider\'s prompt-prefix cache stops matching requests'], a: 2, no: ['The threshold changes which entries match, not what each entry stores.', 'The nearest-neighbour search costs the same; only the cut-off for accepting a match moves.', null, 'Prefix caching works on the provider side for exact prompt prefixes, unaffected by your cache.'], why: '"Cancel my order" and "can I cancel your order?" may sit close but need different answers. A wrong hit is served to everyone who asks, so tune the threshold against real pairs.' },
  { id: 'qb-llmcost3', c: 'llmcost', type: 'mc', q: 'Someone proposes a semantic cache for "What is my account balance?" and similar questions. Why is that a bad idea?', opts: ['Short questions cost too little to be worth caching', 'Numbers embed poorly, so the cache would rarely hit', 'The answer depends on the user, so it must not be shared', 'Balance questions must go to the biggest model to be right'], a: 2, no: ['Cost is not the issue here. Even cheap requests are worth caching when the answer is shared.', 'The cache would hit often, which is exactly the danger.', null, 'Balances come from a tool or database lookup, so even a small model can answer them.'], why: 'A cache key must include everything the answer depends on. Answers built from one user\'s data are private, and serving them to others is a data leak.' },
  { id: 'qb-llmcost4', c: 'llmcost', type: 'mc', q: 'Every request starts with the same 6,000-token system prompt and tool list, then a short, varied user message. What cuts input cost the most?', opts: ['A semantic cache keyed on the user\'s message', 'A lower max_tokens cap so answers come out shorter', 'Provider prompt caching of the shared prefix', 'Moving the system prompt after the user\'s message'], a: 2, no: ['Varied user messages rarely repeat, so hit rates are low, and it caches whole answers.', 'max_tokens limits output. The 6,000 input tokens are still billed in full.', null, 'That breaks prefix caching, since the shared text no longer comes first.'], why: 'Providers can cache the processed form of a long, identical prompt prefix and bill repeats at a discount, so keep the stable part first and the varying part last.' },
  { id: 'qb-llmcost5', c: 'llmcost', type: 'mc', q: '50,000 users each send 10 messages a day, about 1,500 tokens each in and out together, at $2 per million tokens. Roughly what is the daily bill?', opts: ['$150 a day', '$750 a day', '$1,500 a day', '$15,000 a day'], a: 2, no: ['That is ten times too low: check the 500,000 messages a day.', 'That is half: 750 million tokens at $2 per million is $1,500, not $750.', null, 'That is ten times too high: 750 million tokens, not 7.5 billion.'], why: '50,000 x 10 = 500,000 messages; x 1,500 tokens = 750 million tokens; x $2 per million = $1,500 a day.' },
  // agents: Agents & tool use
  { id: 'qb-agents1', c: 'agents', type: 'mc', q: 'An agent deleted the wrong files last night. What do you need to work out why?', opts: ['The final answer it gave the user, saved with the session', 'A log of each step: prompt, tool call, arguments and result', 'The GPU metrics for the servers during the run', 'A rerun at temperature 0 to reproduce what it did'], a: 1, no: ['The final answer shows the outcome, not which tool result led it astray.', null, 'GPU metrics show load and latency, not the agent\'s decisions.', 'A rerun can take a different path, and the files are already gone. Replay needs the original log.'], why: 'Logging every step lets you replay the run and see which input or tool result made the agent choose the wrong action.' },
  { id: 'qb-agents2', c: 'agents', type: 'mc', q: 'An agent calls refund(order_id, amount) with an amount larger than the order total. Where should that be stopped?', opts: ['In the tool code, which checks arguments like any API', 'In the system prompt, which spells out the refund rules', 'By the LLM judge during the nightly evaluation run', 'By a JSON schema saying the amount must be a number'], a: 0, no: [null, 'The model can still get it wrong or be talked out of the rules. A prompt is not enforcement.', 'Evals catch the pattern later. The bad refund has already been paid.', 'A schema checks the type. A number that is too big still passes it.'], why: 'Tools are APIs and must validate their inputs, including business rules, whoever the caller is. The model is just an untrusted client.' },
  { id: 'qb-agents3', c: 'agents', type: 'mc', q: 'Each step of an agent is right 95% of the time, independently. About how often does a 20-step task go right all the way through?', opts: ['About 95% of the time', 'About 80% of the time', 'About half the time', 'About a third of the time'], a: 3, no: ['That is one step. Errors compound across 20 steps.', 'That would need each step to be about 99% right.', 'That is about 14 steps at 95%. Twenty steps go lower.', null], why: '0.95 to the 20th power is about 0.36. Long loops compound errors, which is why short loops, checks between steps or fixed workflows are often more reliable.' },
  { id: 'qb-agents4', c: 'agents', type: 'mc', q: 'An ops agent can read logs, restart pods and drop database tables. Where should a human approve its actions?', opts: ['Before every step, including each read of the logs', 'Once at the start, approving the agent\'s written plan', 'After the run, by reading the full log the next day', 'Before it drops a table, which cannot be undone'], a: 3, no: ['Approving every read trains people to click yes without looking.', 'The plan can change once the agent reads tool results, including injected text.', 'A review after the fact cannot bring back a dropped table.', null], why: 'Put the human check on irreversible or costly actions. Reads and safe, undoable actions can run freely within the step and budget limits.' },
  // proximity: Proximity Service
  { id: 'qb-proximity1', c: 'proximity', type: 'mc', q: 'Two cafés 20 m apart have geohashes that share no prefix at all. How?', opts: ['The geohash length is too short to tell them apart', 'They sit on either side of a big cell border', 'Two different points hashed into the same cell', 'Geohash is a random hash with no locality'], a: 1, no: ['Too short a geohash would make them share a prefix, not differ completely.', null, 'Sharing a cell means sharing a prefix, the opposite of what happened.', 'Geohash keeps locality in most places; nearby points usually share a long prefix.'], why: 'Near a major border, such as the equator or the prime meridian, points metres apart fall in different top-level cells. That is why searches also check neighbouring cells.' },
  { id: 'qb-proximity2', c: 'proximity', type: 'mc', q: 'The 9-cell lookup returns 300 candidate places for a 500 m search. What happens before you reply?', opts: ['Return all 300, since the cells were sized to the radius', 'Sort them by geohash string to rank by distance', 'Compute exact distances, drop any past 500 m, sort', 'Return only those in the user\'s own cell, to be safe'], a: 2, no: ['Nine cells cover more than the circle, so places in the corners are farther than 500 m.', 'Geohash order is not distance order; neighbours across a border can sort far apart.', null, 'That drops close places just over the border, which is why the neighbours were fetched.'], why: 'Cells only narrow the search. The service then measures the true distance to each candidate, keeps those inside the radius and sorts by distance or rating.' },
  { id: 'qb-proximity3', c: 'proximity', type: 'mc', q: 'The location index for 200M places is a few GB, and search traffic triples. How do you scale it?', opts: ['Replicate the whole index onto more servers', 'Shard it by business ID across many nodes', 'Cache each result at the CDN by exact lat, lng', 'Move it into the primary DB for consistency'], a: 0, no: [null, 'Random sharding by ID makes every search query every shard, adding fan-out for no gain.', 'Exact coordinates almost never repeat, so the cache would rarely hit.', 'That adds load to the primary and solves a freshness problem this read-heavy index does not have.'], why: 'A few GB fits in memory, so every server can hold a full copy. Adding read replicas scales searches without sharding.' },
  { id: 'qb-proximity4', c: 'proximity', type: 'mc', q: 'Quadtree leaves are capped at 100 places. A new restaurant opens in a leaf that already holds 100. What happens?', opts: ['The leaf splits into four smaller children', 'The place moves to the emptiest neighbour leaf', 'The tree is rebuilt from the database tonight', 'The leaf merges with its parent to make room'], a: 0, no: [null, 'Each leaf covers its own area, so a place in a neighbour would be found in the wrong spot.', 'Rebuilding nightly works for batch loads, but inserting one place is simpler as a local split.', 'Merging makes cells bigger, which is the opposite of handling a crowded one.'], why: 'A quadtree splits a crowded cell into four quadrants, so dense areas get small cells and sparse areas stay large. Many systems still rebuild the tree offline and apply small edits in between.' },
  // nearby: Nearby Friends
  { id: 'qb-nearby1', c: 'nearby', type: 'mc', q: 'Ben opens the app. How does he see which friends are nearby right away, before their next update?', opts: ['Wait for each friend\'s next ping, within 30 s', 'Query the location history store for each friend\'s last row', 'Read friends\' latest spots from the cache, then subscribe', 'Ask every friend\'s phone for its location via push'], a: 2, no: ['That leaves an empty screen for up to 30 seconds, a poor first impression.', 'History is a write-heavy archive; the cache already holds exactly the latest point.', null, 'Push notifications wake phones and drain batteries, and offline friends never answer.'], why: 'On connect, the handler batch-reads friends\' latest locations from the cache to fill the screen, then subscribes to their channels for live updates.' },
  { id: 'qb-nearby2', c: 'nearby', type: 'mc', q: 'You need to deploy a new version of the WebSocket servers. What is the main concern?', opts: ['Nothing: the load balancer moves open sockets', 'Clearing every location from the Redis cache', 'Locking the history store for a migration', 'Draining sockets so clients reconnect slowly'], a: 3, no: ['A load balancer cannot move a live TCP connection; killed sockets reconnect all at once.', 'Locations in the cache do not depend on the server version and expire on their own.', 'The history store is unrelated to how socket servers are rolled out.', null], why: 'Socket servers are stateful. Mark a server draining so it takes no new connections, then let its clients reconnect elsewhere gradually instead of in one storm.' },
  { id: 'qb-nearby3', c: 'nearby', type: 'mc', q: 'Ada\'s phone dies mid-walk. How does she drop off her friends\' maps?', opts: ['Her socket handler deletes her history rows', 'Friends\' phones poll her status every second', 'Her cache entry\'s TTL expires with no new pings', 'A nightly job clears stale users from the cache'], a: 2, no: ['History is an archive of past points; deleting it would not tell friends she is gone.', 'Polling every second would undo the reason for using pushed updates.', null, 'A nightly sweep would leave her showing as nearby for hours.'], why: 'Each update rewrites her location with a TTL. With no new pings, the entry expires and friends stop seeing her, with no clean-up message needed.' },
  { id: 'qb-nearby4', c: 'nearby', type: 'mc', q: '10M active users each send a location every 30 s, and all go to the history store. Which store suits it?', opts: ['One Postgres primary with an index on time', 'A write-optimised store like Cassandra', 'Redis with persistence turned off', 'A data warehouse loaded per write'], a: 1, no: ['About 330,000 inserts a second is far beyond one primary, and every index slows it further.', null, 'Without persistence, history is lost on restart; Redis holds the latest location, not the archive.', 'Warehouses load in batches for analytics; single-row writes at this rate are slow and costly.'], why: '10M / 30 s is about 330k writes a second. An LSM-based store like Cassandra, partitioned by user, takes heavy append writes and scales out.' },
  // maps: Maps & Routing
  { id: 'qb-maps1', c: 'maps', type: 'mc', q: 'Roads change, so some tiles must be re-rendered. How do phones get the new tiles quickly via the CDN?', opts: ['Set a zero TTL so tiles are never cached', 'Purge every tile in the CDN on each update', 'Put a version in tile URLs and bump it', 'Have phones re-request tiles each minute'], a: 2, no: ['With no caching, every request hits the origin, which is the load the CDN exists to absorb.', 'A full purge sends all traffic back to the origin at once, for a change that touched a few tiles.', null, 'Re-requesting adds load, and still returns the cached old tile until it expires.'], why: 'A new version in the URL (say /v42/12/2048/1361.png) is a new cache key, so phones fetch it fresh while old URLs simply age out.' },
  { id: 'qb-maps2', c: 'maps', type: 'mc', q: 'During navigation each phone could send its location every second. How do you cut that load?', opts: ['Send only when the driver leaves the route', 'Batch pings on the phone; send every 15 s', 'Use UDP, so each ping costs less to send', 'Route all pings to one region to pool them'], a: 1, no: ['The traffic model needs regular speed samples along every road, not just off-route events.', null, 'UDP trims headers but keeps the same number of messages, and lost pings go unnoticed.', 'One region adds latency for most drivers and becomes a single point of failure.'], why: 'The phone records a point each second and uploads a batch every few seconds, cutting request count many times while traffic speeds stay accurate.' },
  { id: 'qb-maps3', c: 'maps', type: 'mc', q: 'A jam forms on one highway segment. Of the millions of active trips, how do you find those to reroute?', opts: ['Recompute every active trip\'s route each minute', 'Look up trips indexed by the segments on their route', 'Wait for each phone to ask for a new ETA itself', 'Broadcast the jam to every phone to check locally'], a: 1, no: ['Rerouting millions of trips each minute is huge waste when a jam affects a few thousand.', null, 'Drivers already in the jam would learn too late; the server knows first.', 'Most phones are nowhere near the jam, and sending it to all of them is a huge fan-out.'], why: 'Keep a reverse index from road segment (or routing tile) to the active trips crossing it, so a speed change touches only those trips.' },
  { id: 'qb-maps4', c: 'maps', type: 'mc', q: 'Many map apps send vector tiles instead of PNG images. What do they gain?', opts: ['Live traffic baked into each cached tile', 'No need for a CDN, since vector tiles are so tiny', 'Less data, and the phone can restyle and rotate', 'Tiles no longer need zoom levels at all'], a: 2, no: ['Baking live data into tiles breaks caching; traffic is a separate overlay.', 'Vector tiles are still requested by millions, so a CDN still serves them.', null, 'Vector tiles are still cut by zoom, with less detail stored at low zoom.'], why: 'Vector tiles send geometry, which is usually smaller than images, and the phone draws it: smooth zoom, rotation, labels in the user\'s language and night mode.' },
  // dmq: Distributed Message Queue
  { id: 'qb-dmq1', c: 'dmq', type: 'mc', q: 'A consumer processes a message, then crashes before committing its offset. What happens when it restarts?', opts: ['The message is lost, since it was already read once', 'Another consumer group takes over that message', 'The broker skips it, since it was handed out already', 'It reads it again, so it is processed twice'], a: 3, no: ['Reading does not delete anything; the message stays in the log for the retention period.', 'Consumer groups are independent and each read every message. A group restarting does not hand its work to another group.', 'The broker does not track which messages it handed out; the consumer\'s committed offset is the only record of progress.', null], why: 'The committed offset still points before the message, so the restarted consumer reads it again. That is at-least-once delivery, and why consumers must be idempotent.' },
  { id: 'qb-dmq2', c: 'dmq', type: 'mc', q: 'You key an orders topic by country, and 60% of orders come from one country. What do you see?', opts: ['That country\'s orders arrive out of order at consumers', 'One partition, and its one consumer, carries 60% of the load', 'Adding consumers spreads that country\'s orders across them', 'Producers get errors because one key is used too often'], a: 1, no: ['Same key means same partition, which is exactly what keeps those orders in order.', null, 'Within a group each partition goes to one consumer, so extra consumers cannot share the hot partition.', 'Brokers accept any number of messages per key. The cost is load imbalance, not errors.'], why: 'Every message with one key goes to one partition, read by one consumer in the group. Key by something with many evenly used values, like order ID or customer ID, if per-country order is not needed.' },
  { id: 'qb-dmq3', c: 'dmq', type: 'mc', q: 'You grow a topic from 8 to 12 partitions to add throughput. What happens to per-key ordering?', opts: ['Nothing: the broker moves old messages to keep each key together', 'Ordering becomes global across all 12 partitions', 'Many keys now map to a new partition, so order can break', 'Consumers must stop, since groups cannot rebalance'], a: 2, no: ['Existing messages stay where they were written. Only new messages follow the new key-to-partition mapping.', 'Order still holds only within a partition. More partitions never create order across them.', null, 'Consumer groups rebalance automatically when partitions are added.'], why: 'The partition is hash(key) mod partition count, so changing the count moves many keys. A key\'s new messages land on a new partition while old ones may be unread on the old, so consumers can see them out of order. Pick enough partitions up front.' },
  { id: 'qb-dmq4', c: 'dmq', type: 'mc', q: 'A partition has 3 replicas and producers use acks=all, but the in-sync set has shrunk to just the leader. The leader\'s disk then dies. What happens?', opts: ['No data is lost, since acks=all waits for 3 replicas', 'Writes acked by the leader alone are lost', 'Followers had copied the writes, just behind the leader', 'Consumers replay those writes from their committed offsets'], a: 1, no: ['acks=all waits for the in-sync replicas, not all replicas; with only the leader in sync, it waits for just the leader.', null, 'Followers drop out of the in-sync set because they fell behind, so they lack the latest writes.', 'Offsets only mark a consumer\'s position in the log; they cannot recreate data the broker lost.'], why: 'With the in-sync set down to one, acks=all means a single copy. Setting min.insync.replicas = 2 makes the leader refuse writes it cannot copy to at least one follower.' },
  // metrics: Metrics Monitoring & Alerting
  { id: 'qb-metrics1', c: 'metrics', type: 'mc', q: 'On-call gets 40 pages a night for CPU above 80%, and users notice nothing. What is the better alerting setup?', opts: ['Page on SLO burn rate; keep CPU on a dashboard', 'Raise the threshold to 95%, so fewer of them fire', 'Add a second on-call engineer to share the pages', 'Page on every 5xx response the service returns'], a: 0, no: [null, 'A higher threshold cuts noise but still pages on a cause users may never feel, and can miss real outages.', 'Sharing noise halves it per person but does not fix it; people still learn to ignore pages.', 'Single errors happen constantly in healthy systems, so this pages even more often than CPU does.'], why: 'Alert on symptoms users feel. An error budget burn rate alert fires when the SLO is at risk; CPU is a cause worth charting, not worth waking someone for.' },
  { id: 'qb-metrics2', c: 'metrics', type: 'mc', q: 'A nightly batch job runs for 40 seconds, and the collector scrapes every 60 seconds. How do you reliably get its metrics?', opts: ['Scrape every second while the job is running', 'Register the job in service discovery like the long-lived services', 'Push them to a gateway before exiting, which gets scraped', 'Write the numbers to the logs and search them later'], a: 2, no: ['A one-second scrape of everything costs a lot, and the job can still finish between scrapes and lose its final numbers.', 'Discovery helps the collector find a target, but the job may finish before it is scraped even once.', null, 'Logs are fine for events, but they make counting, charting and alerting on numbers slow and costly.'], why: 'Pull suits long-running services; short-lived jobs can vanish before a scrape. They push their final metrics to a gateway (like Prometheus Pushgateway), which keeps them for the collector.' },
  { id: 'qb-metrics3', c: 'metrics', type: 'mc', q: 'A dashboard shows average latency at 80 ms, yet users complain the app is slow. What should it show instead?', opts: ['p99 latency from a histogram', 'The average of each host\'s p99', 'Maximum latency in each hour', 'Median latency across all requests'], a: 0, no: [null, 'Percentiles cannot be averaged: the mean of per-host p99s is not the fleet p99. Merge histograms instead.', 'The maximum is one outlier and jumps around; it does not show how many users are affected.', 'The median shows the typical request, which is already fine. The complaints come from the slow tail.'], why: 'An average hides a slow tail. Histogram buckets let you compute p95 and p99 across hosts, which show what the slowest users actually feel.' },
  { id: 'qb-metrics4', c: 'metrics', type: 'mc', q: 'Services push their metrics to a collector. One crashes silently overnight. What does the monitoring see?', opts: ['A failed scrape, which fires an "up == 0" alert', 'An error count the service pushes as it crashes', 'Its gauges dropping to zero on the dashboards', 'Nothing, unless you alert on missing data'], a: 3, no: ['Failed scrapes come from pull collection. With push nothing is scraped, so there is nothing to fail.', 'A process that dies suddenly rarely gets to push a final metric.', 'The points simply stop arriving; charts show a gap, not a drop to zero.', null], why: 'With push, a dead service just goes quiet, which looks the same as no traffic. Alert when expected series go missing; this is a main reason pull suits long-running services.' },
  { id: 'qb-metrics5', c: 'metrics', type: 'mc', q: 'A request metric has labels endpoint (50 values), status (5) and host (200). About how many time series can it create?', opts: ['255, the sum of the label values', '200, one series for each host', '10,000, endpoints times hosts', '50,000, the product of all three'], a: 3, no: ['Labels combine, they do not add: each combination of values is its own series.', 'Each host reports a separate series for every endpoint and status pair, not one.', 'That forgets status. Every label multiplies the count.', null], why: 'Every unique combination of label values is a separate series: 50 x 5 x 200 = 50,000. That is why one more label, like user_id, can explode cardinality.' },
  // adclick: Ad Click Aggregation
  { id: 'qb-adclick1', c: 'adclick', type: 'mc', q: 'The watermark waits 2 minutes. A click from 10:01 arrives at 10:09, after its window closed. With billing at stake, what should happen?', opts: ['Count it in the 10:09 window, where it arrived', 'Keep every window open an hour so that no click arrives late', 'Send it to a late-events path that corrects the totals', 'Drop it, since the watermark closed that window'], a: 2, no: ['That bills the click to the wrong minute, which is what counting by event time avoids.', 'Holding windows that long delays every count by an hour for the sake of a few stragglers.', null, 'Dropping late events is fine for rough charts, but with money involved those clicks must be counted somewhere.'], why: 'The watermark trades lateness for speed, so a few events will still miss their window. Route them to a side output that corrects the stored counts, and the nightly reconciliation catches anything left.' },
  { id: 'qb-adclick2', c: 'adclick', type: 'mc', q: 'The aggregator crashes and, on restart, re-reads the last few thousand clicks from the queue. Why are they not counted twice?', opts: ['The queue deletes clicks once read, so none come back', 'The producer\'s idempotence setting blocks repeats', 'Each click ID is recorded, so replays are dropped', 'The watermark skips any event it has already passed'], a: 2, no: ['A log-based queue keeps messages for its retention period; replaying them is the whole point here.', 'Producer idempotence stops duplicates from producer retries. It does nothing when a consumer re-reads the log.', null, 'Re-read clicks may still be inside open windows, and the watermark does not track which events were counted.'], why: 'Delivery is at least once, so replays happen. Deduplicating on each click\'s unique ID (or checkpointing counts and offsets together) turns that into effectively exactly-once counting.' },
  { id: 'qb-adclick3', c: 'adclick', type: 'mc', q: 'Billing needs clicks per ad per minute, with each click counted in exactly one bucket. Which window type?', opts: ['Sliding: a one-minute window recomputed each second', 'Session: a window that closes after a gap in clicks', 'Global: one window per ad that is never closed', 'Tumbling: fixed one-minute windows that never overlap'], a: 3, no: ['Sliding windows overlap, so each click counts in many windows; they suit moving averages like clicks in the last minute.', 'Session windows vary in length per user and suit visits or sessions, not fixed billing minutes.', 'A window that never closes never produces a final per-minute count to bill.', null], why: 'Tumbling windows split time into back-to-back fixed buckets, so each click falls into exactly one minute. That makes counts add up cleanly for billing.' },
  { id: 'qb-adclick4', c: 'adclick', type: 'mc', q: 'Clicks are partitioned by ad ID across 50 aggregator nodes, so each ad is counted on one node. How do you get the top 100 ads each minute?', opts: ['Each node sends its top 2, since 50 times 2 makes 100', 'Each node sends its own top 100; merge and keep the best', 'Each node sends a random 1% of its clicks to rank', 'Each node sends its top 10, and the merger ranks those 500'], a: 1, no: ['One node might hold 30 of the top 100 ads. Taking only 2 from each misses them.', null, 'Sampling gives rough ranks and can swap close ads. Since every node has exact counts, use them.', 'A node holding more than 10 of the global top 100 would have some left out.'], why: 'Each ad lives on one node, so any global top 100 ad is in its own node\'s top 100. Merging 50 lists of 100 and keeping the best 100 is exact and cheap.' },
  // email: Distributed Email Service
  { id: 'qb-email1', c: 'email', type: 'mc', q: 'A team shards email metadata by message ID to spread writes evenly. Which everyday request gets much slower?', opts: ['Saving an incoming email, since each insert now has to lock rows on every shard', 'Opening a mailbox, since one user\'s messages now sit on every shard', 'Reading a body from object storage, since its pointer is harder to find', 'Sending mail, since the outbound queue now has to be split by message ID'], a: 1, no: ['Each new message is still one insert on one shard. Writes were never the problem; it is the per-user reads that scatter.', null, 'The pointer is in the message row you already fetched, so the blob read is unchanged. The slow part is finding the rows at all.', 'The outbound queue is separate from metadata sharding. It is usually split by destination domain, not by message ID.'], why: 'Nearly every query is "this user\'s mailbox", so sharding by user ID keeps a mailbox on one shard. Sharding by message ID turns every inbox view into a scatter-gather across all shards.' },
  { id: 'qb-email2', c: 'email', type: 'mc', q: 'Why must a receiving mail server write an incoming email to durable storage before it replies 250 OK over SMTP?', opts: ['So a second replica can ack it first, since SMTP needs two copies before OK', 'So the recipient\'s phone gets its push before the sender hears back', 'So the per-user search index is updated before the mail is acknowledged', 'After the OK the sender drops its copy, so a crash would lose the mail'], a: 3, no: ['SMTP has no replication rule. Replicating before acking is good practice, but the reason is the same: accepting mail means taking responsibility for it.', 'Push to devices is a later, best-effort step. Delaying the SMTP reply for it would only slow intake.', 'Indexing can happen asynchronously after the mail is safely stored. Search being a few seconds behind is fine.', null], why: 'A 250 OK hands responsibility for the message to the receiver, and the sending server then deletes its own copy. If the message was only in memory, a crash after the OK loses it for good.' },
  { id: 'qb-email3', c: 'email', type: 'mc', q: 'A company emails the same 5 MB PDF to 1 million users, and attachment storage grows by 5 TB. What cuts this the most?', opts: ['Store each attachment once by hash; mailboxes keep a pointer', 'Gzip each copy of the PDF before it is written to the user\'s shard', 'Serve the PDF through a CDN so each mailbox reads one cached copy', 'Move attachments into the metadata DB so they share its replication'], a: 0, no: [null, 'PDFs are already compressed, so gzip saves little, and a million copies are still stored.', 'A CDN caches reads near users. It does nothing about the million copies sitting in storage.', 'Large blobs bloat a database and its replicas. The database should hold small, often-changing metadata, not attachments.'], why: 'Attachments are immutable blobs, so naming them by a content hash lets identical files share one stored copy. Each mailbox row just points at it, turning 5 TB into 5 MB plus pointers.' },
  { id: 'qb-email4', c: 'email', type: 'mc', q: 'One big mail provider starts throttling you, and 2 million messages for it fill the shared outbound queue. Mail to other domains stalls too. Best fix?', opts: ['Retry the throttled messages more often so the backlog clears sooner', 'Move each throttled message to a dead letter queue after one failure', 'Give each destination domain its own queue, rate and retry timer', 'Add more sender workers to the shared queue to drain it faster'], a: 2, no: ['Retrying a throttling server faster gets you throttled harder, or blocklisted. Backoff exists to slow down, not speed up.', 'That gives up on mail that would go through in an hour. A dead letter queue is for messages that keep failing after many tries.', null, 'New workers pull the same stuck messages and block on the same slow domain. More hands do not fix head-of-line blocking.'], why: 'Splitting the outbound queue by destination is a bulkhead: one slow or throttling domain only backs up its own queue. Each domain gets its own send rate and backoff, so mail elsewhere keeps flowing.' },
  // objstore: S3-like Object Storage
  { id: 'qb-objstore1', c: 'objstore', type: 'mc', q: 'A bucket holds billions of 2 KB objects, each stored with 8 data + 4 parity chunks. What goes wrong?', opts: ['Parity cannot be computed for any object smaller than one disk block', 'Each tiny object becomes 12 chunks, so per-chunk overhead dominates', 'Small objects cannot be spread over racks, so one rack loss kills them', 'Every read has to decode parity, so small reads fail under heavy load'], a: 1, no: ['Parity works on any size; small data is just padded. The real issue is the cost of tracking and fetching so many tiny pieces.', null, 'Chunk placement does not depend on object size. Twelve chunks of any size can go on twelve racks.', 'Erasure codes are usually systematic: a healthy read fetches the data chunks directly and decodes only after a loss.'], why: 'Erasure coding pays off on big objects. For tiny ones, 12 metadata entries, 12 disk seeks and 12 network calls per object swamp the 2 KB of data, so systems pack small objects together or replicate them.' },
  { id: 'qb-objstore2', c: 'objstore', type: 'mc', q: 'Versioning is on for a bucket. A user deletes a 50 GB object, but the storage bill does not drop. Why?', opts: ['The two other replicas keep the bytes until replication catches up', 'The parity chunks stay behind until the next scrub clears them out', 'Deleted data stays billable until its disk sectors are overwritten', 'The delete only adds a delete marker; older versions are still kept'], a: 3, no: ['Replication lag lasts seconds, not a billing cycle. Copies follow the metadata, which still says the old version exists.', 'Scrubbing checks and repairs chunks; it does not decide what is deleted. Chunks are freed when no version points at them.', 'Billing follows what the metadata says is stored, not physical sectors. Freed space is reclaimed by compaction behind the scenes.', null], why: 'With versioning, a delete writes a delete marker as the newest version and keeps the old ones, so the 50 GB is still stored. A lifecycle rule that expires old versions is what actually frees it.' },
  { id: 'qb-objstore3', c: 'objstore', type: 'mc', q: 'Log uploads use keys like logs/2026-10-19/host-17.gz. Writes for the current day start getting throttled. What is the likely cause?', opts: ['The metadata index is split by key range, so new keys share one partition', 'Each data node holds one prefix, so its disks fill up with that day\'s logs', 'Objects under one prefix share a lock, so writers queue behind each other', 'The bucket keeps a version counter that every new upload must increment'], a: 0, no: [null, 'Bytes are spread across data nodes by chunk placement, not by key prefix. Only the metadata is ordered by key.', 'Objects are immutable and written independently; there is no shared prefix lock. The bottleneck is the partition that owns the key range.', 'Versions are per object, not a bucket-wide counter. A bucket-wide counter would throttle all uploads, not just today\'s.'], why: 'Metadata is kept sorted by key so listing by prefix is fast, which means keys that start the same land on one partition. A date in the key sends all of today\'s writes there; a hashed prefix spreads them out.' },
  { id: 'qb-objstore4', c: 'objstore', type: 'mc', q: 'Clients start thousands of multipart uploads a day, and many crash before calling complete. What does that cost you?', opts: ['Each half-done upload holds a lock on its key, blocking other writers', 'Their parts stay stored, and billed, until aborted or expired by a rule', 'Readers see the partial object under its key until it is cleaned up', 'The store keeps retrying each upload until every missing part arrives'], a: 1, no: ['Multipart uploads take no lock on the key. Another writer can upload the same key, and the last complete call wins.', null, 'An object only becomes visible when complete is called. Until then the parts are invisible to readers.', 'The server cannot retry an upload; only the client has the bytes. Retrying a failed part is the client\'s job.'], why: 'Uploaded parts are kept so the client can resume, which means abandoned uploads leave invisible garbage. A lifecycle rule or garbage collector aborts uploads older than a few days and frees their parts.' },
  // leaderboard: Real-time Gaming Leaderboard
  { id: 'qb-leaderboard1', c: 'leaderboard', type: 'mc', q: 'Two players both reach 5,000 points. Whoever got there first should rank higher. How do you do that with a sorted set?', opts: ['Nothing extra: a sorted set breaks ties by the order members were added', 'Fold the time into the score, so earlier finishes score higher', 'Keep a second sorted set by finish time and merge the two on every read', 'Use ZRANGEBYLEX, which orders members with equal scores by write time'], a: 1, no: ['Redis breaks ties by comparing member names as strings, not by insertion order, so ties come out alphabetically.', null, 'Merging two sets on each read throws away the O(log n) rank lookup that made the sorted set worth using.', 'ZRANGEBYLEX ranges over member names when all scores are equal. It orders by name, not by time.'], why: 'Put the tie-breaker inside the score itself, for example points times a large factor plus (max time minus finish time). Every read and rank stays a single O(log n) sorted set call.' },
  { id: 'qb-leaderboard2', c: 'leaderboard', type: 'mc', q: 'Why keep players\' scores in a database when the Redis sorted set already holds every score?', opts: ['Redis cannot find one player\'s rank, so the database answers rank lookups', 'Redis sorted sets cap out at about a million members in a single key', 'Redis can lose data on a crash; the database is the record to rebuild from', 'SQL serves the top 10 faster, since its pages are cached in memory too'], a: 2, no: ['ZREVRANK returns one player\'s rank in O(log n). Rank lookups are exactly what the sorted set is good at.', 'A sorted set can hold billions of members. The limit you hit first is the memory of the node.', null, 'Redis returns the top 10 from memory in microseconds with no sort. That speed is the reason it is there.'], why: 'Redis is used as a fast, rebuildable view. Scores are written durably to a database too, so if a node loses its data the sorted set can be repopulated from the source of truth.' },
  { id: 'qb-leaderboard3', c: 'leaderboard', type: 'mc', q: 'A player wants to see their rank plus the five players just above and below them. Which sorted set calls do it?', opts: ['ZREVRANK for the rank, then ZREVRANGE rank - 5 to rank + 5', 'ZRANGEBYSCORE from their score minus 5 to their score plus 5', 'ZSCAN over the whole set, stopping once their name comes up', 'ZREVRANGE 0 to -1 to load the board, then search it in the app'], a: 0, no: [null, 'That returns everyone within 5 points, which could be nobody or thousands. Neighbours are by position, not by score gap.', 'ZSCAN walks the set in hash order, not rank order, and touches everything. It is for iterating big sets without blocking.', 'Loading millions of entries for every request costs O(n) in time and bandwidth, which is what the sorted set avoids.'], why: 'ZREVRANK gives the player\'s position in O(log n), and ZREVRANGE by index returns the eleven players around it in O(log n + 11). Both are cheap at any board size.' },
  { id: 'qb-leaderboard4', c: 'leaderboard', type: 'mc', q: 'Each month the game starts a fresh leaderboard at midnight, and last month\'s must stay viewable. How do you switch over?', opts: ['ZREM every member at midnight so the board starts again from zero', 'Halve every score at midnight so old results fade but stay in order', 'Copy the set to an archive key at midnight, then reset the live one', 'Write to a new key such as board:2026-11; the old one stays read-only'], a: 3, no: ['Removing millions of members is a slow O(n) job on a hot key, and it destroys the month you need to show.', 'Score decay is a real design for rolling boards, but it changes old results instead of freezing last month.', 'Copying millions of entries blocks Redis at the busiest moment, and the reset is another O(n) delete. A new key per month needs neither.', null], why: 'Putting the month in the key means the switch is just a change of key name. Nothing is copied or deleted at midnight, and the old board can expire later.' },
  // hotel: Hotel Reservation System
  { id: 'qb-hotel1', c: 'hotel', type: 'mc', q: 'A 3-night booking has reserved nights 1 and 3, then finds night 2 sold out. If the system is built right, what happens?', opts: ['Nights 1 and 3 stay booked, and night 2 goes onto a waiting list', 'The transaction rolls back, so none of the three nights is held', 'A cleanup job finds the half booking later and frees the two nights', 'The guest is shown a partial booking to confirm or cancel by hand'], a: 1, no: ['A guest cannot use two disjoint nights. Holding them blocks other guests from rooms that will likely go unused.', null, 'Until the job runs, those nights look sold and real guests are turned away. Compensation jobs are for steps across services.', 'Every night lives in one database, so one transaction can decide all of them. Pushing the mess to the guest is a workaround.'], why: 'All nights of the stay are checked and incremented in one transaction. If any night fails the guard, the whole transaction rolls back and no inventory is left held.' },
  { id: 'qb-hotel2', c: 'hotel', type: 'mc', q: 'The app reads reserved and total, checks reserved < total, then runs UPDATE reserved = reserved + 1. The last room sometimes sells twice. Fix?', opts: ['Cache the inventory row in Redis so both servers read the same count', 'Run the read on the primary instead of a lagging read replica', 'Put the check in the write: UPDATE ... WHERE reserved < total', 'Set the isolation level to READ COMMITTED for booking requests'], a: 2, no: ['A shared cache does not stop two servers reading 99 at the same moment. The read and write still are not atomic.', 'Even on the primary, two requests can both read before either writes. The gap between check and write is the bug.', null, 'READ COMMITTED is the default in many databases and still allows this race. You need the check inside the write, or a lock.'], why: 'A check followed by a separate write is a race: two requests both pass the check. Putting the condition in the UPDATE, or a CHECK constraint, makes the database refuse the second increment.' },
  { id: 'qb-hotel3', c: 'hotel', type: 'mc', q: 'To cut database load, a team caches room availability for 5 minutes and accepts bookings based on the cached counts. What goes wrong?', opts: ['Bookings trust stale counts, so a sold-out night can be sold again', 'When the cache expires, every request stampedes the database at once', 'Cached counts take up too much memory with one key per hotel night', 'Guests see prices up to 5 minutes old on the hotel and rate pages'], a: 0, no: [null, 'A stampede on expiry is real, and request coalescing fixes it. But the bigger harm here is selling rooms that are gone.', 'Even millions of small counters fit easily in memory. Size is not what makes this design wrong.', 'Slightly stale prices on browse pages are an accepted trade-off. That part of caching is fine.'], why: 'Hotel and rate pages are read-heavy and can be cached, but the booking itself must check live inventory in the database. Caching the count you book against lets two guests take the last room.' },
  { id: 'qb-hotel4', c: 'hotel', type: 'mc', q: 'Guests can take up to 10 minutes on the payment page. How do you stop the room selling to someone else meanwhile, without blocking anyone for long?', opts: ['Hold a SELECT ... FOR UPDATE lock on the row until payment is done', 'Overbook by 10% so a few rooms sold during payment are covered', 'Use the idempotency key so a second guest cannot book that room', 'Insert a pending reservation with an expiry; a job frees lapsed ones'], a: 3, no: ['A row lock held for minutes blocks every booking for that room type and night. Locks should last milliseconds.', 'Overbooking covers expected no-shows. Using it to paper over a known race oversells on busy nights.', 'An idempotency key dedupes the same guest\'s retries. It says nothing about a different guest.', null], why: 'A pending reservation counts against inventory right away but is just a row, not a lock. If payment does not finish before its expiry, a background job cancels it and gives the room back.' },
  // payment: Payment System
  { id: 'qb-payment1', c: 'payment', type: 'mc', q: 'Your call to the payment provider times out. You do not know whether the card was charged. What should happen next?', opts: ['Mark it failed and ask the customer to pay again from the checkout', 'Retry with a fresh idempotency key, since the first call never answered', 'Retry with the same idempotency key, or ask the provider for its status', 'Refund the amount at once, in case the first charge did go through'], a: 2, no: ['If the charge did go through, paying again charges the customer twice. A timeout means unknown, not failed.', 'A fresh key tells the provider it is a new payment, so a charge that already succeeded happens twice.', null, 'Refunding a charge that may not exist creates new errors. Find out what happened first.'], why: 'A timeout leaves the outcome unknown. Reusing the same idempotency key makes the retry safe: the provider either does the charge once or returns the result it already has.' },
  { id: 'qb-payment2', c: 'payment', type: 'mc', q: 'Finance finds a ledger entry posted with the wrong amount last week. How is it fixed in a double-entry ledger?', opts: ['UPDATE the entry\'s amount, with a trigger that logs the old value', 'Delete the bad debit and credit pair, then post the correct one', 'Adjust the account\'s balance row so the totals match again', 'Post a reversing entry, then a new entry with the right amount'], a: 3, no: ['Editing history breaks the audit trail and any report already built on it. A side log does not make the ledger itself trustworthy.', 'Deleting entries hides that the mistake happened. Auditors expect every posted entry to stay.', 'Balances are derived from entries. Changing the balance alone makes the books disagree with themselves.', null], why: 'A ledger is append-only: mistakes are corrected with new entries. The reversal cancels the bad entry and the new one posts the right amount, so history shows both what happened and the fix.' },
  { id: 'qb-payment3', c: 'payment', type: 'mc', q: 'Nightly reconciliation shows the provider settled a payment that your ledger still marks as pending. What is the most likely cause?', opts: ['The success webhook was lost and no status check followed it up', 'A debit was posted without its credit, so the ledger does not balance', 'The provider charged the card twice, since its key check failed', 'The settlement file is from yesterday, so it lists stale payments'], a: 0, no: [null, 'A missing credit would show up as books that do not sum to zero, not as one payment stuck in pending.', 'A double charge would show two settled payments for one order. Here there is one settled, one pending.', 'A settled payment is final whatever day the file covers. Old files would miss new payments, not settle pending ones.'], why: 'Pending means you never heard back. Webhooks can be lost, so a missed success is caught by a status poll or, failing that, by reconciliation against the settlement file.' },
  // wallet: Digital Wallet
  { id: 'qb-wallet1', c: 'wallet', type: 'mc', q: 'Try-Confirm-Cancel and a saga both handle transfers across shards. What is the main difference?', opts: ['TCC runs inside the databases, while a saga is written in app code', 'TCC reserves first, so no money really moves until both sides confirm', 'A saga holds locks on both balances until the last of its steps ends', 'TCC can only span two services, while a saga can span any number'], a: 1, no: ['Both are written in application code. Prepare and commit inside the databases is two-phase commit.', null, 'A saga commits each step locally and releases its locks at once. Holding locks to the end is two-phase commit.', 'TCC can reserve on many participants. The difference is reserve-then-confirm versus do-then-undo.'], why: 'TCC first reserves on every side, then confirms or cancels the reservations. A saga does each real step at once and, on failure, runs compensating steps, so others can briefly see money that is later undone.' },
  { id: 'qb-wallet2', c: 'wallet', type: 'mc', q: 'An event-sourced wallet finds a bug that has computed fees wrongly for six months. How do you get correct balances?', opts: ['Edit the past fee events to the correct amounts, then replay', 'Run an UPDATE on the balance table to apply the corrected fees', 'Fix the code, then replay the events to rebuild the balances', 'Restore the database from a backup taken before the bug began'], a: 2, no: ['Events are facts that already happened and are never edited. Editing them destroys the audit trail event sourcing exists for.', 'Balances are derived. Patching them by hand leaves them out of step with the events and the next replay undoes it.', null, 'A restore throws away six months of real transfers. Event sourcing lets you keep them and recompute.'], why: 'Balances are a projection of the event log. Fix the code that derives them and replay the unchanged events, plus correcting events for any money that must actually move.' },
  { id: 'qb-wallet3', c: 'wallet', type: 'mc', q: 'Replaying the same events for an account gives a different balance today than it did last week. What is the likely cause?', opts: ['Each replay starts from a different snapshot, so the totals drift', 'The events table lacks an index on account, so the replay is slow', 'The log is append-only, so corrections pile up as new events', 'A handler reads data from outside the events, like today\'s rate'], a: 3, no: ['A correct snapshot is just a saved replay, so starting from any of them gives the same result.', 'A missing index makes replay slow, not different. Speed and correctness are separate problems.', 'Correction events are part of the log and replay the same way every time. That is the design working.', null], why: 'Replay must be deterministic: the result may depend only on the events. Anything read from outside, like a live exchange rate or the clock, has to be captured in the event when it is written.' },
  // exchange: Stock Exchange
  { id: 'qb-exchange1', c: 'exchange', type: 'mc', q: 'Most messages hitting a matching engine are cancels. What keeps a cancel fast in a big order book?', opts: ['A map from order ID straight to the order\'s spot in its price level', 'Scanning the price level for the order, since levels are usually short', 'A separate thread that applies cancels to the book in parallel', 'Keeping the book in an on-disk B-tree keyed by order ID'], a: 0, no: [null, 'Busy price levels hold thousands of orders, so scanning makes each cancel O(n) on the hot path.', 'A second thread editing the book needs locks and breaks the deterministic single-threaded design.', 'Disk access is far too slow for the matching loop. The book lives in memory and the sequenced log gives durability.'], why: 'Each price level is a queue of orders, and a hash map from order ID to its node in that queue makes a cancel O(1). The engine stays single-threaded and fast.' },
  { id: 'qb-exchange2', c: 'exchange', type: 'mc', q: 'The standby replays exactly the same sequence as the primary, but its order book ends up slightly different. What is the likely cause?', opts: ['The standby runs on slower hardware, so it fell behind on matching', 'The sequencer gave the standby its own separate numbering of orders', 'The engine uses something outside the input, like the clock or random', 'Matching depends on order, so two replicas always drift a little'], a: 2, no: ['Slower hardware means lag, not a different result. Given time it reaches the same state.', 'The scenario says the sequence is the same. One shared sequence is exactly what lets the standby match the primary.', null, 'Order dependence is why the same input order gives the same book. Drift means something besides the sequence fed in.'], why: 'Hot-warm failover only works if the engine is deterministic: same input sequence, same state. Reading the wall clock, random numbers or hash-map iteration order breaks that.' },
  { id: 'qb-exchange3', c: 'exchange', type: 'mc', q: 'Market data goes out over UDP multicast with a sequence number per packet. A subscriber misses packet 1042. How does it recover?', opts: ['TCP under the feed spots the gap and resends 1042 to it', 'The multicast group resends lost packets to each member', 'It spots the gap and asks a recovery service for 1042', 'It waits for the next update, which carries the whole book'], a: 2, no: ['Multicast runs over UDP, which has no retransmission. That is why the feed numbers its own packets.', 'IP multicast is fire and forget; routers do not track or resend to members. Recovery has to be built on top.', null, 'Incremental feeds send only changes, so a missed one leaves the book wrong until a snapshot. Real feeds do send snapshots, just not each packet.'], why: 'Multicast reaches every subscriber at the same moment, but UDP can drop packets. Sequence numbers reveal a gap, and the client fetches it from a retransmission service or rebuilds from a snapshot.' },
  // chunksync: Chunked File Sync
  { id: 'qb-chunksync1', c: 'chunksync', type: 'mc', q: 'A sync service dedupes chunks across all users, skipping any upload the store already holds. What privacy problem does that create?', opts: ['Chunk hashes can be reversed to read the contents of other files', 'An uploader can tell another user holds a file, as its upload is skipped', 'Shared chunks let one user\'s edits show up in other users\' files', 'Other users can download any chunk once they know its hash value'], a: 1, no: ['Cryptographic hashes cannot be reversed. The leak comes from the skip itself, not from the hash.', null, 'Chunks are immutable: an edit makes new chunks with new hashes, so nobody else\'s file changes.', 'Downloads are checked against the metadata DB, so a user can only fetch chunks their own files list.'], why: 'If the client can see that an upload was skipped, it learns the chunk was already stored by someone. Per-user dedupe or always doing a full upload for unseen chunks closes that side channel.' },
  { id: 'qb-chunksync2', c: 'chunksync', type: 'mc', q: 'A laptop learns that a 2 GB file was edited on a phone. With content-hashed chunks, what does the laptop download?', opts: ['The whole file again, since chunk positions may have shifted', 'Every chunk whose position in the chunk list has changed', 'A binary patch the phone builds and sends to it directly', 'The new chunk list, then just the chunks it does not have'], a: 3, no: ['Shifted chunks keep their hash, and the laptop already holds them. It only needs the list to know the new order.', 'A chunk that moved still has the same hash, so the laptop has it. What matters is the hash, not the position.', 'Peer-to-peer patches need both devices online at once. The chunk store lets each device sync on its own.', null], why: 'The laptop fetches the file\'s new list of chunk hashes, compares it with what it already has, and downloads only the missing ones. It then rebuilds the file from local and new chunks in the listed order.' },
  { id: 'qb-chunksync3', c: 'chunksync', type: 'mc', q: 'Why name chunks by a SHA-256 hash rather than a CRC32 checksum, even though CRC32 is faster?', opts: ['CRC32 cannot detect the single-bit flips that disks most often cause', 'SHA-256 values are shorter, so chunk lists take up less space to store', 'CRC32 is not stable, so the same chunk can hash differently each time', 'CRC32 collides often at scale, handing users the wrong bytes'], a: 3, no: ['CRC32 catches every single-bit flip; that is what it was designed for. Its weakness is collisions, not detection.', 'A SHA-256 is 32 bytes against 4 for CRC32, so it is longer. The extra bytes are what make collisions unlikely.', 'CRC32 is deterministic: the same bytes always give the same value. Every hash used for dedupe must be.', null], why: 'With only 2^32 values, CRC32 collisions become likely after about 77,000 chunks. When the hash is a chunk\'s name, a collision means a file silently gets someone else\'s bytes, so a cryptographic hash is used.' },
  { id: 'qb-chunksync4', c: 'chunksync', type: 'mc', q: 'A user deletes a file whose chunks are deduped with other files. When can the store delete those chunks?', opts: ['Right away, since the file that owned them no longer exists', 'When no remaining file or version still lists that chunk hash', 'After 30 days, since every chunk has a fixed time to live', 'When the user empties their trash and confirms the deletion'], a: 1, no: ['A deduped chunk has no single owner. Other files may list the same hash and would break.', null, 'A fixed expiry would delete chunks that live files still need. Time to live suits caches, not shared data.', 'Emptying the trash removes this user\'s reference only. Others may still point at the same chunks.'], why: 'Shared chunks are freed by reference counting or a mark-and-sweep pass over the metadata. A chunk is garbage only once no file version anywhere lists its hash.' },
  // blobmeta: Metadata DB + Blob Store
  { id: 'qb-blobmeta1', c: 'blobmeta', type: 'mc', q: 'A user renames a folder holding 10,000 files. With metadata in a DB and bytes in a blob store, what has to change?', opts: ['Each blob is copied to a key under the new path, and the old one deleted', 'The blob store\'s prefix index, which is rebuilt for the new folder name', 'Only metadata rows; the blobs are keyed by hash, not by their path', 'Every client re-uploads the files so the store learns the new names'], a: 2, no: ['That is what happens when blobs are keyed by path. Keying by hash or ID avoids 10,000 copies on every rename.', 'The blob store does not know about folders when blobs are keyed by hash. Folders exist only in the metadata.', null, 'The bytes did not change, so nothing needs uploading. Clients just sync the metadata change.'], why: 'Names, folders and paths live only in the metadata DB, and blobs are named by content hash or an opaque ID. A rename is a metadata update; no bytes move.' },
  { id: 'qb-blobmeta2', c: 'blobmeta', type: 'mc', q: 'Why do clients sync by asking "what changed since my cursor?" instead of listing every file and comparing?', opts: ['S3 listings are eventually consistent, so a full list can miss files', 'Its cost grows with the changes, not with the library size', 'A cursor keeps the file bytes cached on the client between each sync', 'Full listings need a lock on the user\'s files while they are built'], a: 1, no: ['S3 listings have been strongly consistent since 2020, and the list comes from the metadata DB anyway.', null, 'The cursor is just a position in the change log. Caching bytes on the device is a separate concern.', 'A read of the metadata DB needs no lock on the files. The problem with full listings is their size.'], why: 'A user with 200,000 files who changed three should transfer three rows, not 200,000. The cursor marks the last change the client saw, so each sync costs only what is new.' },
  { id: 'qb-blobmeta3', c: 'blobmeta', type: 'mc', q: 'After uploading by presigned URL, the client tells your API "done, here are my chunk hashes". What should the API do before committing?', opts: ['Download every chunk and rehash it to be sure the bytes match', 'Commit at once, since a presigned URL proves the client is trusted', 'Check the store holds each chunk, with the expected size and hash', 'Ask the client to upload the file again through the API to confirm'], a: 2, no: ['Pulling every byte through the API undoes the point of presigned URLs. The store can report checksums itself.', 'A presigned URL only lets the client write one key. A buggy or malicious client can still list chunks it never sent.', null, 'Routing bytes through the API is the bottleneck presigned URLs were meant to remove.'], why: 'The API checks the blob store\'s own record of each chunk, for example a HEAD request returning size and checksum, before committing. Only then does the metadata point at those chunks.' },
  { id: 'qb-blobmeta4', c: 'blobmeta', type: 'mc', q: 'The product keeps 30 days of versions for every file. How is that stored without multiplying storage by the number of edits?', opts: ['Each version is a metadata row and chunk list; unchanged chunks are shared', 'Each version is a full copy of the file, compressed in the blob store', 'Old versions move to a cold storage tier, where each copy costs less', 'S3 object versioning keeps each version of the file\'s single blob'], a: 0, no: [null, 'Compressing full copies still stores every unchanged byte again for each edit.', 'Cold tiers make each byte cheaper, but every version is still a full copy. Tiering suits rarely read data, not deduping edits.', 'Versioning a whole-file blob stores a full new copy on every edit, even when one line changed.'], why: 'A version is just a row pointing at an ordered list of chunk hashes. Most chunks are the same between versions, so each edit adds only its few new chunks plus one row.' },
  { id: 'qb-blobmeta5', c: 'blobmeta', type: 'mc', q: 'The metadata DB outgrows one node. Most queries are "list this folder" or "changes since my cursor" for one user. Shard by what?', opts: ['By chunk hash, so lookups for any chunk spread evenly over shards', 'By upload date, so recent and busy files sit together on new shards', 'By file name, so files with the same name stay together on a shard', 'By user, so one user\'s tree and changes sit on one shard'], a: 3, no: ['Hashing chunks spreads load well but scatters one folder over every shard. It suits the chunk index, not the file tree.', 'Date sharding sends all new writes to one hot shard, and a folder listing spans every date.', 'Names are unrelated to how users query, so one folder still spans many shards.', null], why: 'Sharding by the owning user or account keeps their files, folders and change log together, so the common queries hit one shard. Shared folders need extra care, often a lookup to the owner\'s shard.' },
  // chatdelivery: Chat Delivery and Receipts
  { id: 'qb-chatdelivery1', c: 'chatdelivery', type: 'mc', q: 'Alice is connected to chat server 3 and Bob to server 7. How does Alice\'s stored message get pushed to Bob?', opts: ['Server 3 broadcasts it to every chat server, and server 7 keeps it', 'Server 3 looks Bob up in the registry and forwards it to server 7', 'Bob\'s app polls server 3 every few seconds for messages sent to him', 'The load balancer routes Alice\'s message to whichever server has Bob'], a: 1, no: ['Broadcasting every message to every server multiplies traffic by the number of servers. It does not scale past a few nodes.', null, 'Polling adds delay and load, and Bob is already holding a WebSocket to push on.', 'A load balancer routes new connections, not messages inside an open one. It does not know who sits behind each socket.'], why: 'The registry maps each online user to the server holding their connection. Server 3 looks Bob up and hands the message to server 7, which pushes it down his WebSocket.' },
  { id: 'qb-chatdelivery2', c: 'chatdelivery', type: 'mc', q: 'A 500-member group gets 10,000 messages a day. Storing a read receipt per member per message is too much. What do chat apps store instead?', opts: ['Receipts only for the members who are online when a message arrives', 'One receipt per message, set as soon as the first member opens it', 'Per member, the sequence number of the last message they have read', 'A counter per message of how many members have opened it so far'], a: 2, no: ['Offline members read later, and their receipts would be lost. Online status is not the same as reading.', 'One receipt cannot tell the sender who read it, and group apps show that per member.', null, 'A count says how many but not who, and without knowing who already counted, a re-open double counts.'], why: 'Reading is in order, so "read up to sequence 8,214" covers every earlier message too. That is one number per member per chat, updated as they scroll, instead of one row per message per member.' },
  { id: 'qb-chatdelivery3', c: 'chatdelivery', type: 'mc', q: 'When should the sender\'s app show two ticks (delivered)?', opts: ['When the recipient\'s device acks receiving the message', 'When the message is written to the recipient\'s open socket', 'When the registry shows the recipient online as it is stored', 'When the message has been stored and replicated on the server'], a: 0, no: [null, 'Writing to a socket only puts bytes in a buffer. A half-dead connection accepts them and they never arrive.', 'Online in the registry can be stale by minutes, and it says nothing about this message.', 'Stored and replicated is one tick, sent. It says the server has it, not the recipient.'], why: 'Delivered means the device has it, and only the device can say so. Its ack comes back to the server, which then tells the sender to show two ticks.' },
  { id: 'qb-chatdelivery4', c: 'chatdelivery', type: 'mc', q: 'Bob reconnects after three days with his phone off. How does he get the messages he missed in his chats?', opts: ['The server replays them from the WebSocket send buffer it kept for him', 'Each sender\'s app notices his reconnect and resends its messages', 'His app downloads the full history of every chat and drops duplicates', 'His app sends the last sequence number per chat; the server sends the rest'], a: 3, no: ['Socket buffers live in a server\'s memory and die with the connection. Missed messages come from durable storage.', 'Senders may be offline themselves. Messages were stored first exactly so senders need not resend.', 'Full history can be gigabytes. Sequence numbers let the client ask for only what is new.', null], why: 'Each chat has a sequence number, so the client knows the last message it has in each one. On reconnect it asks the inbox for everything after those numbers, and the server returns the gap.' },
  { id: 'qb-chatdelivery5', c: 'chatdelivery', type: 'mc', q: 'A phone loses signal in a lift. The server still thinks the socket is open for 15 minutes, so the registry keeps routing messages there. Fix?', opts: ['Use TCP keepalive with its default settings, which closes dead sockets', 'App heartbeats; a socket that misses a few is closed and unregistered', 'Have the phone send a goodbye frame before it loses signal', 'Give each registry entry a 24-hour time to live so stale ones expire'], a: 1, no: ['Default TCP keepalive waits about two hours before probing. That is far too slow for chat presence.', null, 'A phone cannot know it is about to lose signal. Clean close frames only cover deliberate logouts.', 'A day-long TTL leaves the stale route in place for a day. Short TTLs refreshed by heartbeats do work.'], why: 'A dead network leaves a half-open TCP connection that the server cannot see. Heartbeats every few tens of seconds, with a timeout, let the server drop it, update the registry, and leave new messages in the inbox.' },
  // netfaults: Unreliable Networks and Timeouts
  { id: 'qb-netfaults1', c: 'netfaults', type: 'mc', q: 'A leader checks that its 10 s lease is still valid, then hits a 15 s garbage collection pause, then writes to storage. What can go wrong?', opts: ['The write is refused, since its TCP connection timed out during the pause', 'It writes with an expired lease while another node may now be leader', 'Nothing: the lease clock stops during the pause, just like the process does', 'The pause looks like a crash, so it restarts and its pending writes are lost'], a: 1, no: ['TCP connections often survive a 15 s pause, and storage cannot know the lease expired unless writes carry a fencing token.', null, 'Wall clocks keep running while a process is paused; only the paused process loses track of time.', 'A paused process does not restart. It resumes mid-function, unaware that time has passed, which is exactly the danger.'], why: 'A process pause can happen between checking a lease and acting on it, so the node acts on stale beliefs. Storage should reject writes whose fencing token is older than the newest it has seen.' },
  { id: 'qb-netfaults2', c: 'netfaults', type: 'mc', q: 'A checkout calls the payment service, times out after 2 s and retries. Some customers are now charged twice. What fixes it?', opts: ['Retry with exponential backoff and jitter so the retries are spread out', 'Raise the timeout to 30 s so the first call always finishes before a retry', 'Send an idempotency key so a retried charge returns the first result', 'Put a circuit breaker on the call so retries stop once errors pile up'], a: 2, no: ['Backoff and jitter stop retry storms from synchronising. Each retry can still repeat a charge that already went through.', 'No timeout guarantees the first call finished; a lost reply looks the same at 2 s or 30 s, and users wait longer.', null, 'A circuit breaker protects a struggling dependency from load. It does nothing to stop one retried charge from running twice.'], why: 'A timeout cannot tell you whether the first attempt worked, so retries must be idempotent. The server stores the result per idempotency key and replays it for any repeat.' },
  { id: 'qb-netfaults3', c: 'netfaults', type: 'mc', q: 'Round trips inside one datacenter are usually 0.5 ms but sometimes jump to 200 ms. Where does most of that variable delay come from?', opts: ['Queueing in switches, the OS and busy apps waiting to read the packet', 'The speed of light in the cables, which changes with the route taken', 'A DNS lookup the sender makes before every packet it puts on the wire', 'TCP\'s three-way handshake, which runs again for each packet that is sent'], a: 0, no: [null, 'Propagation delay inside one building is microseconds and nearly fixed. It cannot explain a 400x jump.', 'DNS answers are cached and resolved once per name, not per packet; packets go to IP addresses.', 'The handshake runs once per connection, not per packet. Connection pools exist to avoid paying it often.'], why: 'Networks have unbounded delays mostly because of queues: a congested switch port, the OS waiting for a free CPU, or a receiver busy in a pause. That is why timeouts must be chosen from measured delay, not a fixed guess.' },
  { id: 'qb-netfaults4', c: 'netfaults', type: 'mc', q: 'Node A can still send to node B, but every packet from B back to A is dropped. B keeps processing A\'s requests. What does A observe?', opts: ['A TCP reset on each call, which tells A the return link is broken', 'An ICMP unreachable message, which tells A that the route has failed', 'Nothing odd; B sees the fault first, so B marks A as dead and stops', 'Only timeouts, which look the same as B having crashed or being slow'], a: 3, no: ['A reset is a packet from B, and B\'s packets never arrive, so A gets no reset at all.', 'ICMP errors are often filtered or never sent, and here they would travel the same broken return path.', 'B gets A\'s requests fine, so B has no reason to suspect A. Partitions can be one-way.', null], why: 'With a one-way fault A sees silence, which is indistinguishable from a crash, a slow node or a lost reply. Meanwhile B is doing the work, so retries from A must be idempotent.' },
  // datamodels: Document vs Relational
  { id: 'qb-datamodels1', c: 'datamodels', type: 'mc', q: 'A job site stores each candidate as a document with an embedded list of skills. Recruiters now want canonical skill names and searches across candidates and companies. What is the real trouble?', opts: ['Fields inside embedded arrays cannot be indexed, so search must scan', 'The data has become many-to-many, which documents handle poorly', 'Schema on read stops new fields being added to older candidates', 'The documents grew too large, so they must be split across shards'], a: 1, no: ['Document stores such as MongoDB index fields inside arrays (multikey indexes), so search can use an index.', null, 'Schema on read is what lets old and new documents differ. Adding a field to new ones needs no migration.', 'A list of skills is small, and sharding spreads documents across servers; it does not fix a modelling problem.'], why: 'Shared skills and companies are entities many candidates point at, so the data is many-to-many. Documents then need app-side joins or copied names, while the relational model handles it with tables and joins.' },
  { id: 'qb-datamodels2', c: 'datamodels', type: 'mc', q: 'Each profile is one 2 MB document. A new feature updates its last_seen field on every page view. What is the cost?', opts: ['Many stores rewrite the whole document, so each tiny update is heavy', 'Every older profile needs a last_seen field added before the first write', 'Each update joins to the user table to find the document to change', 'Readers can see a half-updated document while the write is in flight'], a: 0, no: [null, 'Schema on read lets old profiles simply lack the field until they are next written.', 'A document is found by its key; no join is needed to update one.', 'Document stores make writes to a single document atomic, so readers see the old or the new version.'], why: 'Document locality helps when you read the whole thing, but many stores rewrite the full document on update. Keep documents small, and move hot, fast-changing fields like last_seen out of big ones.' },
  { id: 'qb-datamodels3', c: 'datamodels', type: 'mc', q: 'An HR system tracks employees, departments and projects, and an employee can be on many projects. Reports ask which people on project P report directly to manager M. Which fits best?', opts: ['A document per department, embedding its employees and their projects', 'A columnar warehouse, since reports scan employees across many columns', 'A key-value store keyed by employee ID, with each record as a JSON value', 'Relational tables with foreign keys, joined for each report as needed'], a: 3, no: ['An employee on projects in several departments would be copied into each, and every change must be made in many places.', 'Columnar stores suit big analytical scans over history. This is everyday transactional data with selective lookups.', 'A key-value store fetches by key only; asking who is on project P means scanning every record.', null], why: 'Employees, projects and managers are shared entities with many-to-many links, which is where the relational model shines: each fact lives in one place and joins answer new questions.' },
  { id: 'qb-datamodels4', c: 'datamodels', type: 'mc', q: 'A hero has an inventory of at most 20 items, always shown with the hero, and belongs to a guild shared by thousands of heroes. How should a document store model this?', opts: ['Embed both in the hero document, so a hero page is a single read', 'Embed the inventory, and refer to the guild by its ID', 'Refer to both by ID, since embedding anything breaks normal form', 'Embed the guild, and refer to the inventory, as guilds rarely change'], a: 1, no: ['A guild rename would then mean rewriting thousands of hero documents. Copying shared data trades writes for reads.', null, 'This works but throws away locality: the inventory is small, owned and read together, which is exactly what to embed.', 'This is backwards. The guild is the many-to-one data to reference; the owned inventory belongs inside the hero.'], why: 'Embed what is owned, bounded and read together; reference what many records share. That gives one read for the hero page and one place to change the guild.' },
  // graphmodel: Graph Data Model
  { id: 'qb-graphmodel1', c: 'graphmodel', type: 'mc', q: 'A property graph of heroes and quests needs a new kind of link: one hero mentored another. What does adding it take?', opts: ['An ALTER TABLE that adds a mentor_id column to the heroes table', 'A new join table for mentors, plus a migration to create it first', 'Nothing up front: just add edges labelled MENTORED as they happen', 'Rebuilding the graph\'s indexes so traversals can follow the new label'], a: 2, no: ['That is the relational way, and a single column only allows one mentor per hero.', 'A join table is how relational models store many-to-many links, and it needs a schema change first.', null, 'Property graphs do not need index rebuilds for new edge labels; edges are stored with their vertices.'], why: 'In a property graph any vertex can link to any other with an edge of any label, so new kinds of relationship need no schema change. That flexibility is a big reason to choose a graph.' },
  { id: 'qb-graphmodel2', c: 'graphmodel', type: 'mc', q: 'Places sit inside places: city in county in state in country, with no fixed depth. In SQL, how do you find every place inside one country?', opts: ['A recursive CTE (WITH RECURSIVE) that follows parents to any depth', 'A fixed chain of self-joins, one for each level of the hierarchy', 'A GROUP BY on the country column, with a HAVING clause to filter', 'A full-text index over place names, searched for the country\'s name'], a: 0, no: [null, 'The number of joins must be known when writing the query, but here the depth varies from place to place.', 'Only the top level stores its country directly, so grouping misses everything nested deeper.', 'Full-text search matches words in text. It knows nothing about which place is inside which.'], why: 'Variable-length paths are where SQL gets clumsy: you need a recursive common table expression. A graph query language says the same thing in one short pattern, such as Cypher\'s -[:WITHIN*]->.' },
  { id: 'qb-graphmodel3', c: 'graphmodel', type: 'mc', q: 'Two heroes have been friends since 2019. In a property graph, where does "since 2019" belong?', opts: ['A property on one of the two hero vertices, named friend_since', 'A new Year vertex for 2019, linked by an edge from each friend', 'A separate table keyed by both hero IDs, holding the start year', 'A property on the FRIENDS_WITH edge between the two heroes'], a: 3, no: ['A hero has many friends, each with a different start year, so one vertex property cannot hold it.', 'Edges to a Year vertex do not say which friendship began then. Extra vertices are how stores without edge properties, like RDF, model it.', 'That is a relational join table. It splits the fact away from the graph it describes.', null], why: 'Property graphs give edges their own labels and properties, so facts about a relationship live on the relationship. Queries can then filter on them while traversing.' },
  { id: 'qb-graphmodel4', c: 'graphmodel', type: 'mc', q: 'Relational and graph stores hold the same social graph. A query walks friends of friends of friends. Why is the graph database usually faster here?', opts: ['It keeps the whole graph in memory, while SQL tables live on disk', 'It precomputes paths between every pair of vertices when edges change', 'Each vertex points straight at its edges, so a hop skips an index search', 'It stores edges in a B-tree, which finds each hop in constant time'], a: 2, no: ['Both kinds of database cache hot data in memory and spill to disk; memory is not the difference.', 'Precomputing all pairs grows with the square of the vertices; no general graph database does it.', null, 'B-tree lookups cost time that grows with the log of the table size. That is the relational join cost.'], why: 'Native graph stores keep each vertex\'s edges next to it (index-free adjacency), so a hop costs about the same however big the graph is. In SQL every hop is another self-join that searches an index.' },
  { id: 'qb-graphmodel5', c: 'graphmodel', type: 'mc', q: 'A team stores friendships in an SQL edges table (from_id, to_id). The product asks for "heroes who share a guild with a friend of a friend". What makes this painful in SQL?', opts: ['Relational databases cannot store many-to-many links like friendships', 'Each hop is another self-join, so the query grows with every hop', 'Foreign keys must be dropped first, or the joins lock the edges table', 'The edges table needs one extra column for every hop a query takes'], a: 1, no: ['They can, with a join table such as this edges table. The pain is in querying many hops, not storing them.', null, 'Foreign keys check writes; they do not stop joins or make reads take locks.', 'The edges table stays two columns. Hops are expressed in the query, not in the schema.'], why: 'Each hop through an edges table is one more join, so deep traversals produce long, slow queries. Graph query languages express the same walk as one pattern.' },
  // livecomments: Live Comments Fan-out
  { id: 'qb-livecomments1', c: 'livecomments', type: 'mc', q: 'Each viewer polls GET /comments?after=<last id> every 2 seconds. A stream reaches 500,000 viewers. What breaks first?', opts: ['Comments show out of order, since polls return them in a random order', 'Viewers miss comments that were posted between two of their polls', 'About 250,000 requests a second hit the backend, mostly finding nothing', 'Browsers cap open connections, so many viewers can no longer poll at all'], a: 2, no: ['Reading after the last ID returns comments in ID order, so order holds.', 'The after parameter picks up everything since the last poll, so nothing is missed; it just arrives late.', null, 'Each poll is a short request that finishes, so the browser connection limit is not reached.'], why: 'Polling costs a request per viewer per interval whether or not anything is new. Holding one Server-Sent Events stream per viewer and pushing only new comments removes the empty requests.' },
  { id: 'qb-livecomments2', c: 'livecomments', type: 'mc', q: 'A realtime server holds 3,000 viewers spread over 40 videos. When should it subscribe to a video\'s pub/sub channel?', opts: ['When its first viewer of that video connects, unsubscribing after the last leaves', 'At startup, for every live video, so that no comment can ever be missed', 'Once per viewer, so each connection has its own subscription to the channel', 'When the database, polled each second, shows a video has new comments'], a: 0, no: [null, 'Subscribing to every channel means every server receives every comment, the waste that routing by video ID removes.', 'One subscription per viewer duplicates every message on that server; one per video, fanned out locally, is enough.', 'That is polling the database from every server, adding load and delay that pub/sub exists to avoid.'], why: 'A server needs a channel only while at least one of its viewers watches that video. It keeps one subscription per video and fans each message out to its local connections.' },
  { id: 'qb-livecomments3', c: 'livecomments', type: 'mc', q: 'Comments are saved, then published with Redis pub/sub. One realtime server\'s subscription drops for 5 seconds and reconnects. What do its viewers see?', opts: ['Every comment, since Redis buffers them until the subscriber is back', 'Errors on their own posts, since publishing fails while it is gone', 'Those 5 seconds of comments twice, since Redis replays on reconnect', 'A gap: Redis pub/sub keeps no history, so those comments are missed'], a: 3, no: ['Plain Redis pub/sub is fire and forget. Redis Streams or Kafka keep history that a consumer can replay.', 'Publishing succeeds for the other subscribers; Redis does not fail a publish because one subscriber is missing.', 'Plain pub/sub has nothing to replay. Duplicates come from at-least-once systems that redeliver.', null], why: 'Pub/sub with no history drops messages for absent subscribers. Because comments are saved first, the server or its viewers can backfill the gap from the store by last seen ID.' },
  { id: 'qb-livecomments4', c: 'livecomments', type: 'mc', q: 'The comment service publishes each comment to pub/sub first, then writes it to the database. About 1 in 1,000 writes fails. What results?', opts: ['Nothing visible: pub/sub retries the write until the database takes it', 'Viewers see comments that are gone on reload, since they were not saved', 'Nothing visible: pub/sub keeps the comment, so it is the record anyway', 'Those comments never show, since realtime servers check the database first'], a: 1, no: ['Pub/sub delivers to subscribers; it does not retry writes into your database for you.', null, 'Plain pub/sub keeps nothing once delivered, so it cannot be the system of record.', 'Realtime servers push what pub/sub hands them; they do not check the database for each message.'], why: 'Publishing before the durable write shows comments that may never exist. Save first, then publish, so what viewers see is always backed by the store and missed messages can be refetched.' },
  // shred: Deleting from an Append-Only Log
  { id: 'qb-shred1', c: 'shred', type: 'mc', q: 'A compacted Kafka topic is keyed by user ID. You write a tombstone (null value) for user 42. When are their old values gone from the topic?', opts: ['At once, since the tombstone overwrites the older records in place', 'After compaction runs on the segments that hold the older values', 'When the retention period expires, as it would on any normal topic', 'Once every consumer has read the tombstone and committed its offset'], a: 1, no: ['The log is append-only; a tombstone is a new record, and old ones stay until cleaned.', null, 'A compact-only topic does not delete by age. Compaction keeps the latest value per key, which lets a tombstone stand for deleted.', 'Consumer offsets track reading progress; they do not decide what the broker deletes.'], why: 'A tombstone marks a key as deleted, and compaction later drops older values for that key. Until it runs, and in any backup or copy taken before, the old data is still there.' },
  { id: 'qb-shred2', c: 'shred', type: 'mc', q: 'You crypto-shred user 7 by deleting their key. A search index and a cache built from the log hold decrypted copies of their name. What now?', opts: ['Nothing: deleting the key makes every copy of their data unreadable', 'Rotate the encryption keys of the index and cache to finish the job', 'Those stores keep plain text copies, so each one must delete them as well', 'Rebuild the log from the index, so the two sources agree again'], a: 2, no: ['Deleting a key only protects copies still encrypted with it. Plain text downstream is unaffected.', 'Rotating keys re-encrypts data under new keys; it does not remove the name from those stores.', null, 'The log is the source of truth and derived stores are built from it, not the other way round.'], why: 'Crypto-shredding covers every encrypted copy at once, but derived views that store decrypted data need their own delete. Keep personal data encrypted in derived stores too, or tombstone it there.' },
  { id: 'qb-shred3', c: 'shred', type: 'mc', q: 'A team encrypts each day\'s log segment with its own key and plans to delete keys when users ask to be forgotten. Why does that fail?', opts: ['Encryption at rest already covers this, so the day keys add nothing', 'Old segments are read-only, so their keys can no longer be deleted', 'The ciphertext stays in backups, so deleting a key erases nothing', 'Deleting a day\'s key erases everyone\'s events from that day'], a: 3, no: ['Disk encryption protects against stolen drives; one key covers everyone, so it cannot erase one person.', 'Keys live in a separate key store, so they can be deleted whatever happens to the segments.', 'Copies encrypted with a deleted key become unreadable anywhere, backups included. That part works.', null], why: 'Crypto-shredding needs the key to match the unit you must erase, which is usually one person. A per-day key would destroy every user\'s data for that day to forget one.' },
  { id: 'qb-shred4', c: 'shred', type: 'mc', q: 'Without crypto-shredding, a user must be erased within 30 days, but backups are immutable and kept for 90. What is the usual approach?', opts: ['Delete every backup that holds the user, and take a fresh one now', 'Restore each backup, delete the user, and back up the result again', 'Keep a list of erased IDs and re-delete them whenever a backup is restored', 'Overwrite the user\'s rows in each backup with SHA-256 hashes of them'], a: 2, no: ['Dropping backups to erase one person leaves no history to recover from after an incident.', 'Immutable backups cannot be replaced, and redoing every backup for each request does not scale.', null, 'Hashes of names and emails can be reversed by guessing, so it is not erasure, and immutable backups cannot be edited.'], why: 'Live systems delete at once; backups age out on schedule, and a restore re-applies the erasure list before the data is used. Crypto-shredding avoids this by making old copies unreadable.' },
  // oncall: On-Call, SLOs and Error Budgets
  { id: 'qb-oncall1', c: 'oncall', type: 'mc', q: 'A service has a 99.9% SLO over 30 days. For the last hour its error rate has been 1.44%, about 14 times the budgeted rate. What should alerting do?', opts: ['File a ticket: one hour at this rate spends only a tiny part of the budget', 'Wait: SLOs are judged over 30 days, so check the numbers at month end', 'Page now: at this burn rate the month\'s budget is gone in about two days', 'Page only once the error rate passes 50%, which marks a true outage'], a: 2, no: ['An hour at 14x spends about 2% of the month\'s budget, and it keeps burning. Slow burns are what tickets suit.', 'By month end the budget is long gone. Burn-rate alerts exist to catch it while there is still time.', null, 'Users notice far below 50%. Fixed high thresholds miss steady partial failures that drain the budget.'], why: 'Alert on burn rate: how fast the error budget is being spent. At 14.4x, 30 days of budget lasts about two days, so a page is warranted; slower burns can go to a ticket.' },
  { id: 'qb-oncall2', c: 'oncall', type: 'mc', q: 'A team split between London and Sydney runs one weekly rotation, so whoever is on call gets paged at 3 a.m. their time. What is the fix?', opts: ['Pay a night bonus, so engineers accept the 3 a.m. pages', 'Follow the sun: each office covers its own working hours', 'Move to one-day shifts, so nobody has more than one bad night', 'Silence pages overnight and handle them all the next morning'], a: 1, no: ['A bonus does not stop tired engineers making mistakes at 3 a.m.; it only pays for the damage.', null, 'Shorter shifts spread the pain thinner but still wake someone up every night.', 'Real outages at night would then go unhandled for hours and burn the error budget.'], why: 'With teams in time zones far apart, follow-the-sun hands the pager over at the end of each office\'s day, so pages land during someone\'s working hours.' },
  { id: 'qb-oncall3', c: 'oncall', type: 'mc', q: 'Halfway through the window, a service has spent its whole error budget. Product wants to ship a big new feature next week. What does the error budget policy say?', opts: ['Ship it, but lower the SLO to 99% so the budget is positive again', 'Ship it on schedule, since the budget will reset at the next window', 'Raise the SLO, so the team is pushed to spend more time on reliability', 'Hold risky launches and spend the time on reliability until it recovers'], a: 3, no: ['Moving the target to fit the outage hides the problem users already felt; SLOs change only by agreement on what users need.', 'More failures before the window ends hurt users further, and with a rolling window the budget comes back slowly.', 'A tighter SLO means an even smaller budget, so the team is just further over it.', null], why: 'The error budget is the shared rule for balancing speed and reliability. When it is spent, risky releases pause and the team fixes what burned it.' },
  // postmortem: Blameless Postmortems
  { id: 'qb-postmortem1', c: 'postmortem', type: 'mc', q: 'A postmortem\'s action items read: "be more careful with deploys" and "improve monitoring". What is wrong with them?', opts: ['There are too few; a thorough postmortem lists ten or more items', 'They are vague, with no owner or date, so nothing will change', 'They should name the careless engineer, so the item targets them', 'They belong in the timeline section, not in the action items list'], a: 1, no: ['Count does not matter. Two concrete, owned items beat ten vague ones.', null, 'Naming people makes postmortems about blame, and people stop reporting honestly.', 'The timeline records what happened. Action items record what will change, so these are in the right place, just weak.'], why: 'Good action items are specific system changes, such as "add a canary step to deploys", each with an owner and a due date. "Be more careful" changes nothing about the system.' },
  { id: 'qb-postmortem2', c: 'postmortem', type: 'mc', q: 'Why does a postmortem include a minute-by-minute timeline of the incident?', opts: ['It shows how long detection, response and mitigation each took', 'It shows which engineer acted too slowly at each step of the response', 'It replaces the analysis of contributing factors for short incidents', 'It sets how much SLA credit each affected customer is owed'], a: 0, no: [null, 'Using the timeline to grade individuals turns the review into blame. Delays point at gaps in alerts, tools or runbooks.', 'A timeline says what happened, not why. Contributing factors still need their own analysis.', 'SLA credits come from measured downtime in the contract. The timeline is for learning, not billing.'], why: 'Gaps in the timeline show where the system failed the responders: 20 minutes before anyone noticed means an alerting gap, 40 minutes to roll back means a deploy tooling gap.' },
  { id: 'qb-postmortem3', c: 'postmortem', type: 'mc', q: 'In a postmortem review someone says, "she should have known that flag was dangerous". What is the better question to ask?', opts: ['Who reviewed and approved the change, so they share the root cause', 'Has she caused incidents before, so the team can judge if it is a pattern', 'What she saw at the time, and why the change looked safe to her', 'Will she sign a pledge to double-check every flag before she flips it'], a: 2, no: ['Spreading blame to the reviewer is still blame. Ask what made the change look safe to both of them.', 'Tracking individuals\' incident history is a blame culture, and it discourages honest reporting.', null, 'A personal pledge relies on memory and care. A system guard, like flag risk labels or staged rollout, prevents the repeat.'], why: '"Should have known" is hindsight bias. Asking what the engineer saw and why it looked safe finds what the system can change, such as missing warnings or no staged rollout.' },
  { id: 'qb-postmortem4', c: 'postmortem', type: 'mc', q: 'A bad config went to every region at once, the alert fired 25 minutes late, and the runbook was out of date. What should the postmortem name as the cause?', opts: ['The bad config, since without it none of the rest would have mattered', 'The late alert, since quick detection would have kept the outage small', 'The engineer who wrote the config, so that they can be retrained', 'Several contributing factors, each of them with its own owned action item'], a: 3, no: ['Bad configs will happen again. Without staged rollout, alerting and runbook fixes, the next one does the same damage.', 'Detection is one factor, but fixing only alerting leaves global config pushes and the stale runbook in place.', 'Naming a person ends the inquiry at "human error" and teaches people to hide mistakes.', null], why: 'Incidents usually have several contributing factors. Each one is a place the system can change: staged config rollout, a faster alert, and an up-to-date runbook, each with an owner.' },
  // failuredet: Failure Detection (Heartbeats and Indirect Probes)
  { id: 'qb-failuredet1', c: 'failuredet', type: 'mc', q: 'In a SWIM-style cluster, node A concludes that node C is dead. How does the rest of the cluster find out?', opts: ['A broadcasts it to every member at once, which then all ack', 'A writes it to a central registry that every member polls', 'The news rides on normal ping messages and spreads by gossip', 'Each member waits until its own direct ping to C has failed'], a: 2, no: ['Broadcasting each change to every member costs messages that grow with cluster size, and it is bursty.', 'A central registry like ZooKeeper works, but it is a different design with its own failure point; SWIM needs none.', null, 'Waiting for every member to test C slows the verdict and multiplies probe traffic.'], why: 'SWIM piggybacks membership updates on the pings it already sends, so news reaches the whole cluster in about log n rounds of gossip with no extra messages.' },
  { id: 'qb-failuredet2', c: 'failuredet', type: 'mc', q: 'Node C is marked suspect after a 2-second pause, but it is healthy again. What lets it avoid being declared dead?', opts: ['It restarts and rejoins under a new ID before the timeout ends', 'It gossips that it is alive, with a higher incarnation number', 'It raises its heartbeat rate so that the suspicion is cleared', 'The detector retries its direct ping every 10 ms until it answers'], a: 1, no: ['Restarting throws away a healthy process. A new ID is for a node that really was declared dead.', null, 'C does not drive the probes in SWIM; other members ping it. Faster heartbeats do not undo a suspect verdict.', 'Hammering one node with pings adds load and still leaves the suspicion unresolved for other members.'], why: 'In SWIM a suspected node that hears the rumour refutes it by gossiping alive with a higher incarnation number, which overrides the older suspect message. That keeps short pauses from causing failovers.' },
  { id: 'qb-failuredet3', c: 'failuredet', type: 'mc', q: 'Why not have each of 2,000 nodes send a heartbeat to every other node every second?', opts: ['Clock drift would make the heartbeats of different nodes clash', 'Heartbeats need a leader to collect them, which is a single point of failure', 'Each node can only keep about 1,024 TCP connections open at once', 'That is about 4 million messages a second, growing with n squared'], a: 3, no: ['Heartbeats measure gaps between arrivals on one node; they do not compare clocks across nodes.', 'All-to-all heartbeats need no leader. The trouble is their volume, not who collects them.', 'That is a default file descriptor limit that is easily raised. Message volume is the real problem.', null], why: 'All-to-all heartbeating grows with the square of the cluster. SWIM-style detectors ping one random member per period and spread results by gossip, so load per node stays flat.' },
  { id: 'qb-failuredet4', c: 'failuredet', type: 'mc', q: 'The detector declares a node dead after a long pause and moves its shards to others. The node then resumes, still believing it owns them. What is the risk, and the guard?', opts: ['None: it learns it was removed the moment it resumes, and stops', 'It may keep writing as owner; epoch numbers let storage reject it', 'Its writes fail anyway, since TCP connections dropped in the pause', 'The detector reverses its verdict, and the shards move back to it'], a: 1, no: ['A paused process resumes mid-task without knowing time passed, and it may write before it hears any news.', null, 'Connections often survive a pause, and a fresh one is easy to open. Relying on luck is not a guard.', 'Moving shards back and forth on each pause is flapping, which makes availability worse.'], why: 'A false positive leaves two nodes that each think they own a shard. Each new owner gets a higher epoch or fencing token, and storage rejects writes carrying an older one.' },
  // sretoil: Eliminating Toil
  { id: 'qb-sretoil1', c: 'sretoil', type: 'mc', q: 'Your SRE team tracks its time and finds 70% now goes to manual tickets and pushes, and the share rises every quarter. What does the SRE model say to do?', opts: ['Hire SREs in step with ticket volume, so each person stays near 50% toil', 'Accept it, since running production by hand is the core of an SRE job', 'Cap toil near half and spend the freed time automating its biggest sources', 'Move the tickets to a cheaper offshore team that runs them by hand'], a: 2, no: ['Toil grows with the service, so headcount would have to grow with it forever. The point of the cap is to engineer the work away instead.', 'SRE treats toil as a cost to shrink. The other half of the time goes to engineering that makes the toil disappear.', null, 'That moves the toil without removing it, and it still grows with the service. Outsourcing suits stable work with no automation payoff.'], why: 'Google SREs cap toil at about half their time. When it goes over, that is a signal to put engineering time into automating the largest sources of manual work, not to absorb it.' },
  { id: 'qb-sretoil2', c: 'sretoil', type: 'mc', q: 'Which of these is toil, in the SRE sense of the word?', opts: ['Restarting a stuck queue consumer by hand most nights', 'Designing a new sharding scheme for the orders database', 'The weekly planning meeting for next quarter\'s work', 'Writing the postmortem after last week\'s outage'], a: 0, no: [null, 'That is engineering: it is creative, done once, and leaves lasting value in the system.', 'Meetings are overhead, not toil. They are not tied to running the service and do not grow as it grows.', 'A postmortem is engineering work with lasting value: it finds causes and leads to fixes that prevent repeats.'], why: 'Toil is manual, repetitive, automatable work with no lasting value that grows with the service. A nightly hand restart fits every part of that; the fix is automation or, better, fixing why the consumer sticks.' },
  { id: 'qb-sretoil3', c: 'sretoil', type: 'mc', q: 'An engineer spends two days moving a legacy service to new hardware by hand. It is a one-off move that will never happen again. Is it toil?', opts: ['Yes: any task an engineer does by hand counts as toil', 'Yes, since it touches production and could cause an outage', 'No, since it took days, and toil is made of small tasks', 'No: it is manual, but it is not repetitive work'], a: 3, no: ['Manual is only one part of the definition. Toil must also repeat and grow with the service, so automating it pays off.', 'Risk does not make work toil. Risky one-off work calls for a careful plan and a rollback, not automation.', 'Size is not the test. A two-day task repeated every month would be toil; this one is not because it never recurs.', null], why: 'Toil is repetitive as well as manual. A true one-off may be cheaper to do by hand than to automate, so it does not count, though it is still worth writing down.' },
  { id: 'qb-sretoil4', c: 'sretoil', type: 'mc', q: 'Three manual tasks: A takes 2 hours once a quarter, B takes 10 minutes 30 times a week, C takes 1 hour once a month. Which should you automate first?', opts: ['A: it is the longest task, so each run saves the most', 'B: it costs about five hours a week, far more than the rest', 'C: monthly tasks are easy to forget, so they fail more', 'None yet: write runbooks for all three before automating'], a: 1, no: ['Per run it is the longest, but at four runs a year it costs about 40 minutes a month. Total time matters, not time per run.', null, 'C costs about 15 minutes a week. Forgotten monthly tasks are better solved with a scheduler than by automating them first.', 'Runbooks are a first step up the ladder, but B already burns five hours a week. A script for B saves more than documenting all three.'], why: 'Rank toil by total time: frequency times duration. B is 300 minutes a week; A and C together are well under an hour, so B gives the biggest return on automation.' },
  { id: 'qb-sretoil5', c: 'sretoil', type: 'mc', q: 'A script restarts a leaky service whenever its memory passes 90%. A year ago it fired weekly; now it fires every hour. What is the problem?', opts: ['Nothing: the restarts are automatic and cost nobody any time', 'The threshold is too high; restarting at 70% would stop it', 'It should page a human for each restart instead of acting', 'It is hiding a growing leak that someone needs to fix at the root'], a: 3, no: ['Hourly restarts drop in-flight work and the rate is climbing. Automation that hides a trend is not free.', 'A lower threshold only restarts it sooner and more often. Tuning the trigger does not touch the leak.', 'Paging for every restart turns it back into toil and noise. A ticket or an alert on the restart rate fits better.', null], why: 'Auto-remediation is good, but its rate is a signal. Restarts going from weekly to hourly mean the leak is getting worse, so track the rate and fix the cause rather than let the script mask it.' },
  // srealert: Monitoring and Alerting
  { id: 'qb-srealert1', c: 'srealert', type: 'mc', q: 'A database\'s latency and error rate look normal, but its connection pool is 98% used and climbs with traffic each day. Which golden signal is this, and why watch it?', opts: ['Saturation: it warns you before users feel anything', 'Traffic: more connections just means more requests', 'Errors: a full pool already counts as failed queries', 'Latency: pool use is part of latency, so p99 has it'], a: 0, no: [null, 'Traffic counts demand. A pool at 98% is about how full a resource is, and a full pool will soon queue or refuse requests.', 'No query has failed yet; the error rate is normal. Errors only show once the pool is exhausted and calls are refused.', 'p99 stays normal until the pool runs out, then jumps. Latency is a symptom, which is why it shows up too late here.'], why: 'Saturation is how full the most constrained resource is. It is the golden signal that predicts trouble: a pool nearing 100% will soon add latency and errors, so it is worth a ticket or a dashboard now.' },
  { id: 'qb-srealert2', c: 'srealert', type: 'mc', q: 'With a 99.9% monthly SLO, an alert pages whenever errors pass 0.1% for 5 minutes. It wakes people weekly for blips that barely dent the budget. Better rule?', opts: ['Raise it to 1% errors for 5 minutes, so short blips stop paging', 'Page when the month\'s budget burns fast, such as 2% in one hour', 'Page only when the alert has fired three times in a row', 'Move it to a dashboard and have someone check it each morning'], a: 1, no: ['A fixed higher threshold still pages on short spikes and misses a steady 0.5% that drains the budget in a week.', null, 'Requiring repeats delays real outages too, and still ignores how much budget is being spent.', 'A dashboard alone misses a real outage at 3 a.m. Fast burns should page; slow burns can be tickets.'], why: 'Burn-rate alerts page on how fast the error budget is being spent. A short blip barely moves it, while a fast burn, such as 2% of the month in an hour, is worth waking someone for.' },
  { id: 'qb-srealert3', c: 'srealert', type: 'mc', q: 'An alert pages about once a week. Each time, on call looks, finds it has already cleared on its own, and goes back to bed. What should the team do?', opts: ['Fix it or delete it, since it never needs any action', 'Add a runbook step saying to wait ten minutes first', 'Keep it: a regular page keeps on call in practice', 'Send it to a second on-call person so the first can sleep'], a: 0, no: [null, 'Waiting is still being woken. If the right action is to wait, the alert itself should wait or not page.', 'Pages that need nothing train people to ignore pages. Practice belongs in game days and drills.', 'That just moves the noise to someone else. The page is the problem, not who gets it.'], why: 'Every page must be urgent, actionable and need a human. One that clears itself fails that test, so tune it until it means something or remove it; enduring noisy alerts leads to missed real ones.' },
  { id: 'qb-srealert4', c: 'srealert', type: 'mc', q: 'A team wants to page on every cause they can think of: high CPU, low memory, disk use and queue depth, on every host. What is the main problem with this plan?', opts: ['The monitoring system can\'t store that many metrics per host', 'Cause alerts fire too late, after users already see errors', 'Many pages for causes users never feel, so real ones get ignored', 'They catch everything but cost more, since each alert is a query'], a: 2, no: ['Modern metrics systems handle these easily. The limit is human attention, not storage.', 'Causes often show up early, which is why a few, like a disk filling fast, are worth paging on. The trouble is their volume.', null, 'They do not catch everything: plenty of outages cross no host threshold. Query cost is minor next to alert fatigue.'], why: 'Most cause metrics spike without hurting users, so paging on all of them floods on call. Page on symptoms users feel, plus the rare cause that is about to become one, and send the rest to dashboards.' },
  { id: 'qb-srealert5', c: 'srealert', type: 'mc', q: 'A batch job that must publish yesterday\'s reports by noon failed at 1 a.m. It takes an hour to rerun. How should it alert?', opts: ['A ticket for the morning, with time left to rerun it', 'A page at 1 a.m., since a failed job is an error', 'No alert, since anyone can rerun the job by hand', 'A page only if it fails three nights in a row'], a: 0, no: [null, 'There are eleven hours of slack and the rerun takes one. Waking someone gains nothing users will see.', 'Without any alert nobody knows to rerun it, and the noon reports are late. It needs a ticket, not silence.', 'Three nights of missing reports is three late mornings for users. Each failure needs fixing before the deadline.'], why: 'Pages are for problems that need a human now. Here there is time to act during working hours, so a ticket fits; it would become a page only if the deadline were close.' },
  // srecascade: Overload and Cascading Failures
  { id: 'qb-srecascade1', c: 'srecascade', type: 'mc', q: 'A request crosses three layers, and each layer makes up to 4 attempts at the call below it. The bottom service starts failing. How many calls can it get per user request?', opts: ['12: three layers, each making four attempts', '64: each layer\'s four attempts multiply', '4: only the layer just above it retries', '9: each of the three layers adds three tries'], a: 1, no: ['That adds the attempts, but each attempt from the top layer starts its own four below it. Retries multiply across layers.', null, 'Every layer retries what it sees fail, and failures pass up through each one. The layers above repeat the whole chain.', 'That counts only the extra tries and adds them. Each layer multiplies the attempts below it by four.'], why: 'Retries multiply: 4 at the top, times 4 in the middle, times 4 at the bottom is 64 calls. The fix is to retry at one layer only, or to give each layer a retry budget.' },
  { id: 'qb-srecascade2', c: 'srecascade', type: 'mc', q: 'A frontend gives up after 2 s, but the backend keeps working for up to 10 s on each request it gave up on. Under load the backend falls over. What helps most?', opts: ['Raise the frontend\'s timeout to 10 s, so the work is used', 'Give the backend more threads, so abandoned work ends sooner', 'Pass the deadline down, so the backend drops expired work', 'Cache the backend\'s answers, so repeated calls cost less'], a: 2, no: ['Users wait 10 s instead of 2, and the backend is still overloaded. Longer timeouts hold resources longer.', 'More threads just run more useless work at once. The work should not run at all once nobody wants it.', null, 'Caching helps repeat queries, but the backend still spends most of its effort on answers nobody will read.'], why: 'Deadline propagation sends the time left with each request, so every layer can skip or stop work whose caller has already given up. That frees capacity for requests that can still succeed.' },
  { id: 'qb-srecascade3', c: 'srecascade', type: 'mc', q: 'At 150% of capacity, a server accepts every request and queues it. Latency climbs to 30 s and almost every request times out. What should it do?', opts: ['Make its queue bigger, so no request gets dropped', 'Turn on client retries, so timed-out requests try again', 'Raise client timeouts to 60 s, so queued requests can finish', 'Reject the extra early with a fast 503, so the rest succeed'], a: 3, no: ['A bigger queue only makes the wait longer. Queues smooth short bursts; they cannot fix sustained overload.', 'Retries add even more load to a server already at 150%. Retry only with backoff and a budget, and not into overload.', 'Users still wait a minute, and the server is still behind. Long timeouts hold threads and memory for longer.', null], why: 'Load shedding turns away what the server cannot handle while it still has time to serve the rest. Serving two thirds of requests well beats serving all of them too late to matter.' },
  { id: 'qb-srecascade4', c: 'srecascade', type: 'mc', q: 'Clients use exponential backoff with jitter, yet during an outage retries still make up 70% of a service\'s traffic. What caps them?', opts: ['More jitter, so the retries spread over a longer window', 'A shorter timeout, so each failed try gives up sooner', 'A retry budget, so retries stay near 10% of requests', 'A fixed 1 s pause between tries instead of backoff'], a: 2, no: ['Jitter spreads retries in time so they do not arrive together. It does not reduce how many there are.', 'Faster failure means faster retries, which can make the flood worse. Timeouts bound waiting, not volume.', null, 'A fixed pause retries more often than exponential backoff, not less. Backoff is the better of the two.'], why: 'A retry budget limits retries to a fraction of normal traffic per client, so during an outage they cannot multiply the load. Backoff and jitter shape when retries happen; the budget caps how many.' },
  { id: 'qb-srecascade5', c: 'srecascade', type: 'mc', q: 'After an outage, 2,000 clients each reconnect exactly 5 s after losing their connection. When the service comes back, it falls over again at once. What prevents this?', opts: ['A longer health check interval on the load balancer', 'Random jitter in each client\'s reconnect delay', 'Bigger connection pools in each of the clients', 'Bigger servers, sized for the normal daily peak'], a: 1, no: ['That slows how fast the load balancer notices health. It does nothing about clients all arriving in the same second.', null, 'More connections per client means even more arriving at once. Pool size is about steady load, not reconnect storms.', 'Normal peak is far below 2,000 clients reconnecting in the same second. Sizing for that spike wastes money all year.'], why: 'A fixed delay synchronises the clients, so they all return together: a thundering herd. Jitter, ideally on top of exponential backoff, spreads them out so the service can recover.' },
  // eventsrc: Event Sourcing and CQRS
  { id: 'qb-eventsrc1', c: 'eventsrc', type: 'mc', q: 'An event-sourced bank rebuilds each account by replaying its events. Busy accounts now hold 200,000 events, and loading one takes 4 s. What is the standard fix?', opts: ['Delete events older than a year, since the balance reflects them', 'Save a snapshot now and then, and replay only the events after it', 'Merge each account\'s old events into one, rewriting the log in place', 'Move the log to a faster database, so a full replay keeps up'], a: 1, no: ['Deleting events destroys the history and audit trail that are the reason to event-source a ledger.', null, 'Events are immutable; rewriting them loses history. A snapshot is stored beside the log, never in place of it.', 'A faster disk shaves a constant off, but replay still grows with every event. It only delays the problem.'], why: 'Snapshots store the state as of some event, so a load starts there and replays only what came after. The full log stays intact, and a snapshot can always be thrown away and rebuilt.' },
  // colstore: Column Storage & Analytics (OLTP vs OLAP)
  { id: 'qb-colstore1', c: 'colstore', type: 'mc', q: 'An analyst runs SELECT * on a 40-column warehouse table, then uses only 3 of the fields. The query is slow and costly to run. Why?', opts: ['Column stores keep rows whole, so the scan is slow regardless', 'SELECT * skips the column indexes and falls back to a full scan', 'The star schema joins every dimension table into a SELECT *', 'SELECT * makes the column store read all 40 columns from disk'], a: 3, no: ['Column stores keep each column separately, so naming 3 columns reads only those 3. That is the whole point of them.', 'Warehouses rarely use per-column indexes; they skip blocks by min and max values. The cost is reading every column.', 'SELECT * on one table joins nothing. Joins come only from the query naming other tables.', null], why: 'A column store reads only the columns a query names. SELECT * asks for all 40, so it reads more than 13 times the data needed, and many warehouses bill by bytes scanned.' },
  { id: 'qb-colstore2', c: 'colstore', type: 'mc', q: 'To speed up reports, a team moves its app\'s orders table, which takes thousands of single-row inserts a second, into a columnar warehouse. What goes wrong?', opts: ['Each small insert has to touch every column file, so writes crawl', 'Nothing: column stores take small writes as well as row stores do', 'Compression fails, since each new row holds many distinct values', 'Reports get slower, since column data can\'t be filtered by date'], a: 0, no: [null, 'Row stores write one row in one place. A column store spreads each row over many files, which suits large batches only.', 'Compression works on whole columns, not single rows, and still works on new data once it is batched together.', 'Column stores filter by date well, often by skipping blocks sorted by time. Reports were never the problem here.'], why: 'A column store suits big batch loads and big scans. Single-row writes have to touch every column, so keep the app on a row store and copy changes to the warehouse with ETL or a change stream.' },
  // auth: Authentication & Authorization
  { id: 'qb-auth1', c: 'auth', type: 'mc', q: 'A user with a valid, unexpired token calls DELETE on another team\'s project, which their role is not allowed to touch. What should the API return?', opts: ['403 Forbidden: the caller is known, and the answer is no', '401 Unauthorized, since the user lacks the rights to it', '400 Bad Request, since the request itself is not allowed', '409 Conflict, since the project belongs to another team'], a: 0, no: [null, '401 means the caller is not authenticated: no credential, or a bad one. The token here is valid, so identity is known.', '400 is for a malformed request, such as a missing field. This request is well formed; only the permission is missing.', '409 is for a clash with the resource\'s current state, such as an edit on a stale version. Ownership is a permission question.'], why: 'Authentication passed, so it is not 401. The caller is known but not allowed, which is authorization failing: 403 Forbidden.' },
  // resilience: Timeouts, Circuit Breakers & Bulkheads
  { id: 'qb-resilience1', c: 'resilience', type: 'mc', q: 'A dependency answers in 40 ms at p50, 120 ms at p99 and 180 ms at p99.9. Callers use a 30 s timeout. What should the timeout be?', opts: ['30 s is fine, since a long timeout means fewer failed calls', '40 ms, its median, so every slow call is cut off quickly', 'A little above its slow end, around 200 to 300 ms', '120 ms, its p99, so no call ever waits longer than usual'], a: 2, no: ['A hung dependency would hold each caller\'s thread for 30 s, which is how one slow service takes down its callers.', 'Half of all normal calls take longer than the median, so this would fail them for no reason.', null, 'About 1% of healthy calls take longer than p99, so they would fail all the time. Leave room above normal slow calls.'], why: 'A timeout should sit a little above the dependency\'s normal slow responses, so healthy calls finish but a hang is cut off quickly instead of holding threads for 30 s.' },
  // services: Monoliths, Microservices & the Strangler Fig
  { id: 'qb-services1', c: 'services', type: 'mc', q: 'The Orders and Billing services both read and write the same customers table. Orders wants to rename a column and finds it must wait on Billing. What does this show?', opts: ['A need for a saga, so the rename runs in both services at once', 'Nothing wrong: one shared table keeps both views consistent', 'A distributed monolith: neither can change its data alone', 'A need for a service mesh to send queries to the right table'], a: 2, no: ['A saga coordinates a business transaction across services. A schema change on a shared table is a coupling problem.', 'It does keep one copy, but at the cost of the independence the split was for. Each service should own its own data.', null, 'A mesh handles calls between services, such as mTLS and retries. It does not separate a shared database.'], why: 'When two services share a database, a change to one is a change to both, so they must deploy together: all the costs of microservices, none of the independence. Give each its own data and talk through APIs or events.' },
  // transport: TCP, UDP & HTTP Versions
  { id: 'qb-transport1', c: 'transport', type: 'mc', q: 'A page loads 60 small files from one host over HTTP/1.1. It is slow even though the network has bandwidth to spare. What is the main reason?', opts: ['About six connections, each one request at a time', 'Each file is sent over UDP, so routers drop more of them', 'Each file needs its own DNS lookup before it is fetched', 'Uncompressed headers use up all of the bandwidth'], a: 0, no: [null, 'HTTP/1.1 runs over TCP. Only HTTP/3 runs over UDP, through QUIC.', 'DNS answers are cached, so one lookup serves every file from the same host.', 'HTTP/1.1 headers are uncompressed, but bandwidth is spare here. HTTP/2 compresses headers with HPACK, a secondary win.'], why: 'HTTP/1.1 sends one request at a time per connection, and browsers open about six per host, so most files wait in line, a round trip each. HTTP/2 multiplexes them all over one connection.' },
  // keys: Random vs Time-Ordered Keys
  { id: 'qb-keys1', c: 'keys', type: 'mc', q: 'Twelve app servers in three regions write orders to regional shards, but each order\'s ID comes from one auto-increment counter in the main database. What is the main cost?', opts: ['Index pages split often, as counter values arrive out of order', 'Every insert has to reach the one database that hands out numbers', 'The 64-bit counter will run out of numbers within a few years', 'Two servers inserting at the same moment can get the same number'], a: 1, no: ['Counter values grow steadily, so inserts land on the last page, the best case for a B-tree.', null, 'At a million inserts a second, a signed 64-bit counter lasts about 290,000 years.', 'The database hands out each value once, even under heavy concurrency. Collisions are not the risk.'], why: 'A single counter means every writer depends on one place for the next number, which adds cross-region latency and a single point of failure. Snowflake IDs or UUIDv7 can be made anywhere.' },
  { id: 'qb-keys2', c: 'keys', type: 'mc', q: 'A team switches user IDs to UUIDv7 and shows them in public profile URLs. A privacy review flags the change. What does a UUIDv7 give away?', opts: ['Other users\' IDs, which can be guessed from any one of them', 'How many users exist in total, by comparing two of the IDs', 'Which of the app servers created each of the user accounts', 'When each account was created, to the millisecond'], a: 3, no: ['After the timestamp come about 74 random bits, so neighbouring IDs cannot be guessed.', 'That is the leak of auto-increment keys. UUIDv7 has no counter, so two IDs say nothing about the total.', 'UUIDv7 has no machine number. Snowflake IDs do carry one, which can reveal the server.', null], why: 'UUIDv7 starts with a 48-bit millisecond timestamp, so anyone can read when the row was made. If that matters, keep the time-ordered key inside and show a random public ID.' },
  { id: 'qb-keys3', c: 'keys', type: 'mc', q: 'Inserts into a table keyed by UUIDv4 were fast at 10 GB but are slow at 500 GB, on the same server with 64 GB of RAM. What changed?', opts: ['The tree got deeper, adding a level each time the data doubled', 'UUIDv4 collisions got likelier as the table filled up', 'The index outgrew memory, so random inserts read pages from disk', 'Each insert now rewrites the whole index file on disk'], a: 2, no: ['B-tree depth grows very slowly: a few levels hold billions of keys. Depth is not what changed.', 'With 122 random bits, collisions are practically impossible even at trillions of rows.', null, 'A B-tree insert changes one page, sometimes splitting it. Nothing rewrites the whole index.'], why: 'While the index fit in memory, random inserts were cheap. Now most target pages must be read from disk first. Time-ordered keys keep inserts on the last page, which stays in memory.' },
  // encoding: Encoding, Hashing & Encryption
  { id: 'qb-encoding1', c: 'encoding', type: 'mc', q: 'You publish a 2 GB installer and want users to be able to confirm their download was not corrupted on the way. What do you publish alongside it?', opts: ['A SHA-256 checksum of the file', 'A bcrypt hash of the whole file', 'A base64 copy of its first block', 'The file encrypted with AES, plus its key'], a: 0, no: [null, 'bcrypt adds a random salt and is built to be slow, for passwords. It is the wrong tool for checking a large file.', 'Base64 is encoding, and checking one block says nothing about the rest of the file.', 'Encryption hides data from people without the key. Publishing the key hides nothing, and it does not check integrity.'], why: 'A SHA-256 checksum is a fixed-size fingerprint: any change to the file gives a different hash. To also prove who published it, sign the file or its checksum.' },
  { id: 'qb-encoding2', c: 'encoding', type: 'mc', q: 'An app stores card numbers so it can charge customers every month. A developer suggests storing a bcrypt hash of each card number instead. Why won\'t that work?', opts: ['bcrypt is too slow to run on every monthly charge', 'Card number hashes can collide, so the wrong card is charged', 'bcrypt cuts input at 72 bytes, so card numbers get truncated', 'A hash can\'t be turned back, and a charge needs the number'], a: 3, no: ['bcrypt takes tens of milliseconds, which is fine for a monthly job. Speed is not the problem.', 'Collisions are vanishingly rare at this scale. The problem is that the number cannot be recovered at all.', 'The 72-byte limit is real, but a card number is 16 digits, far under it.', null], why: 'Hashing is one-way, so it suits passwords, which are only compared. Card numbers must be read back, so they need encryption, or better, a token from the payment provider.' },
  { id: 'qb-encoding3', c: 'encoding', type: 'mc', q: 'A search page builds its URL as ?q=rock & roll from what the user typed. The server only receives "rock " as the query. What is the fix?', opts: ['Hash the query with SHA-256, so its special characters go away', 'Percent-encode the value, so the & becomes %26 in the URL', 'Encrypt the query with AES, so the browser can\'t parse it', 'Put double quotes around the value, so the & is kept in it'], a: 1, no: ['A hash cannot be turned back, so the server could never read the search terms.', null, 'Encryption is for secrecy, and its output is bytes that still need encoding. The problem is only how the value is written.', 'Quotes have no special meaning in a query string, so the & still splits it into two parameters.'], why: 'In a query string, & separates parameters. Percent-encoding writes reserved characters so they travel as data; it is encoding, so it hides nothing, which is fine here.' },
  // replag: Replication Lag Guarantees
  { id: 'qb-replag1', c: 'replag', type: 'mc', q: 'After each write, the app notes the leader\'s log position for that user. When can an asynchronous replica safely serve that user\'s next read?', opts: ['When it has applied the log up to that position', 'When it is in the same region as the leader', 'When its average lag over the past hour is under 1 s', 'After a fixed 100 ms, since lag is usually milliseconds'], a: 0, no: [null, 'Being nearby lowers typical lag but promises nothing. A replica next door can still be minutes behind.', 'An average hides spikes. Right now it may be far behind, and that is when the user\'s edit would vanish.', 'Lag is usually milliseconds but can be minutes. A fixed wait fails exactly when something is struggling.'], why: 'Read-your-writes needs proof that the replica has the user\'s write. Comparing its applied log position with the one saved at write time gives that proof; otherwise read from the leader.' },
  { id: 'qb-replag2', c: 'replag', type: 'mc', q: 'A chat app partitions messages by message ID. Readers sometimes see a reply appear before the question it answers. What fixes it?', opts: ['Pin each reader to one replica by hashing the user ID', 'Read from the leader for a minute after each user posts', 'Add replicas, so each partition falls less far behind', 'Partition by conversation, so a thread stays together'], a: 3, no: ['That gives monotonic reads for one reader. The two messages are still on partitions that lag by different amounts.', 'That is read-your-writes, for the poster. Other readers still see the reply ahead of the question.', 'More replicas share reads but do not order writes across partitions. Lag can still differ between them.', null], why: 'Consistent prefix reads break when related writes land on different partitions with different lag. Keeping each conversation on one partition means its messages replicate in order.' },
  { id: 'qb-replag3', c: 'replag', type: 'mc', q: 'An app reads from asynchronous replicas. Which of these reads can safely be served by any replica, with no extra guarantee?', opts: ['A user\'s own settings, just after they save them', 'The like count shown under a popular post', 'A user\'s balance, just after their deposit', 'A thread the user just posted a reply to'], a: 1, no: ['The user just changed it, so a stale read looks like the save failed. That needs read-your-writes.', null, 'A balance missing the deposit looks like lost money. Read it from the leader or a caught-up replica.', 'Their reply must appear, or they will post it again. That is read-your-writes too.'], why: 'A like count a few seconds old surprises nobody, so plain eventual consistency is fine. The others are the user\'s own recent writes, which need read-your-writes.' },
  { id: 'qb-replag4', c: 'replag', type: 'mc', q: 'Users are pinned to replicas by a hash of their user ID. One replica dies, and its users move to another replica. What might they briefly see?', opts: ['Nothing odd, since every replica gets the very same writes', 'Their recent writes gone for good, as the dead replica held them', 'Older data than before, if their new replica lags further behind', 'Duplicate rows, since two replicas have now served the same user'], a: 2, no: ['They get the same writes, but not at the same time. Each replica has its own lag.', 'Writes go to the leader, not the replica. Nothing is lost; the new replica may just not have it yet.', null, 'Replicas hold copies of the same rows. Reading from a new one cannot create duplicates.'], why: 'Monotonic reads come from sticking to one replica. Moving to a replica that is further behind can show older data than the user just saw, so a careful system waits until the new replica has caught up to the old one\'s position.' },
  { id: 'qb-replag5', c: 'replag', type: 'mc', q: 'Replica lag is usually 20 ms but reaches 3 minutes during nightly backups. To give read-your-writes, the app waits 1 s after a write, then reads from a replica. Result?', opts: ['It always works, since 1 s is 50 times the normal lag', 'It fails on every request, since any lag at all breaks it', 'Writes are lost during backups, as the leader stalls', 'It works by day, but at night users\' edits seem to vanish'], a: 3, no: ['Normal lag is not the problem; the spike is. A fixed delay fails exactly when the system is under strain.', 'A replica that has caught up is fine to read from. Most of the day, 1 s is plenty.', 'Lag means the replica is behind, not that the leader lost anything. The writes are safe on the leader.', null], why: 'A fixed delay is a guess about lag. Lag spikes when something struggles, so a robust fix checks the replica\'s log position or reads the user\'s own data from the leader.' },
  { id: 'qb-replag6', c: 'replag', type: 'mc', q: 'For read-your-writes, an app sends all of a user\'s reads to the leader for one minute after any write. Most users write every few seconds. What is the risk?', opts: ['Users see older data than before, since the leader lags', 'Each write slows, since replicas must now confirm it', 'Different users see their reads in different orders', 'Almost every read lands on the leader again'], a: 3, no: ['The leader has every write first; it never lags behind a replica.', 'Routing reads changes nothing about how writes are confirmed. That would be synchronous replication.', 'Each user still sees a consistent view. Ordering across users is a consistent prefix question, not caused by this.', null], why: 'If users write constantly, nearly everyone is always inside their one-minute window, so the leader takes almost all reads and the replicas sit idle. Narrow it to the data the user changed, or check log positions.' },
  // isolation: Weak Isolation & Snapshots
  { id: 'qb-isolation1', c: 'isolation', type: 'mc', q: 'A 20-minute backup runs in one transaction under snapshot isolation on a busy Postgres database. What happens to writes from the app while it runs?', opts: ['They carry on; the backup reads the older row versions', 'They block until the backup ends, to keep it consistent', 'They queue up and are applied once the backup is done', 'They go through, and the backup picks up some of them'], a: 0, no: [null, 'That is how lock-based reads behave. With MVCC, readers never block writers.', 'Writes commit at once. MVCC keeps old versions for the backup rather than holding back new ones.', 'The snapshot is fixed at the start, so later writes are invisible to it. That is what keeps the backup one moment in time.'], why: 'MVCC keeps old row versions, so the backup sees the database as of its start while writers keep creating new versions. Readers never block writers, and writers never block readers.' },
  { id: 'qb-isolation2', c: 'isolation', type: 'mc', q: 'A reporting transaction keeps one snapshot open for six hours on a busy Postgres database. What builds up while it runs?', opts: ['Row locks on every row the report has read so far', 'Old row versions that cleanup can\'t remove yet', 'A line of blocked writers waiting for it to finish', 'Dirty pages that can\'t be flushed to disk yet'], a: 1, no: ['Plain reads under MVCC take no row locks. Only SELECT ... FOR UPDATE and writes do.', null, 'Writers do not wait for snapshot readers. They create new versions and carry on.', 'Pages are flushed on the normal schedule. The snapshot holds old versions, not unflushed pages.'], why: 'Vacuum cannot remove row versions that an open snapshot might still need, so tables and indexes bloat for as long as it stays open. Long reports belong on a replica or in a warehouse.' },
  { id: 'qb-isolation3', c: 'isolation', type: 'mc', q: 'At MySQL InnoDB\'s repeatable read, two transactions each read a counter as 10, add 1 in app code, and write 11 back. What happens?', opts: ['The second aborts with a serialization error', 'Both commit, and the counter ends up at 11', 'The second blocks, then reads 11 and writes 12', 'Both commit, and the counter ends up at 12'], a: 1, no: ['That is Postgres\'s repeatable read, which detects the lost update. MySQL\'s does not.', null, 'It blocks on the row lock, but it already computed 11 in code, so it writes 11. Only an atomic SET c = c + 1 gives 12.', 'Nothing adds the two increments together. Each writes the value it computed, 11.'], why: 'MySQL\'s repeatable read does not stop lost updates, so one increment disappears. Use an atomic update, SELECT ... FOR UPDATE, or compare-and-set.' },
  { id: 'qb-isolation4', c: 'isolation', type: 'mc', q: 'A wiki saves an edit only if the page\'s version number is still the one the editor loaded, and asks the user to merge otherwise. What problem does this solve?', opts: ['Read skew in reports that read many pages at once', 'Dirty reads of a page that is halfway through saving', 'Phantoms, when new pages appear during a search', 'Lost updates when two editors save the same page'], a: 3, no: ['Read skew is one reader seeing two moments. Snapshot isolation fixes it; version checks on save do not.', 'Read committed, the default, already prevents dirty reads.', 'Phantoms are new rows matching a search mid-transaction. Version checks on one page do not touch that.', null], why: 'This is compare-and-set: the write succeeds only if nothing changed since the read. A second editor\'s save fails instead of silently overwriting the first.' },
  { id: 'qb-isolation5', c: 'isolation', type: 'mc', q: 'At read committed, a ticket app reads a seat row, checks it is free in code, then marks it sold. Two buyers sometimes get the same seat. Which change fixes it?', opts: ['Read the seat with SELECT ... FOR UPDATE', 'Wrap the plain SELECT in BEGIN and COMMIT', 'Run the check in a READ ONLY transaction', 'Lower the isolation to read uncommitted'], a: 0, no: [null, 'A transaction at read committed still lets both buyers read the seat as free before either writes.', 'A read-only transaction cannot mark the seat sold, and it takes no lock to stop the other buyer.', 'Seeing uncommitted writes sooner does not stop two buyers acting on the same old read.'], why: 'SELECT ... FOR UPDATE locks the row, so the second buyer waits until the first commits and then sees the seat is sold. A conditional UPDATE ... WHERE status = \'free\' works too.' },
  { id: 'qb-isolation6', c: 'isolation', type: 'mc', q: 'On Postgres at read committed, one single SQL statement sums every account balance while transfers keep committing. Can the total come out wrong?', opts: ['Yes: it reads each row at the moment the scan reaches it', 'Yes, unless every transfer is run as SERIALIZABLE', 'No: each statement gets one snapshot of its own', 'No, as the sum locks the table until it is done'], a: 2, no: ['That is how locking read committed can behave in some databases, such as SQL Server without snapshots. Postgres uses MVCC.', 'The writers\' level does not matter here. The statement already sees one consistent moment.', null, 'Postgres reads take no table lock that blocks writers. Consistency comes from MVCC snapshots, not locks.'], why: 'At read committed, Postgres takes a fresh snapshot for each statement, so one query is consistent. Read skew appears when a transaction runs several statements that see different moments.' },
  // serializable: Write Skew & Serializability
  { id: 'qb-serializable1', c: 'serializable', type: 'mc', q: 'An on-call app runs at snapshot isolation. Each healer\'s transaction counts who is on call, then sets its own row off duty if the count is 2 or more. What is the cheapest targeted fix for write skew?', opts: ['Add a version column to each healer\'s row and check it on update', 'SELECT ... FOR UPDATE on the on-call rows the count reads', 'Run the count against the primary instead of a read replica', 'Put the count and the update inside a single transaction'], a: 1, no: ['Each healer updates a different row, so neither version check fails. Optimistic versions catch two writers on the same row.', null, 'Write skew happens on the primary with fully fresh snapshots. Reading from the primary fixes replica lag, a different problem.', 'They are already in one transaction each. Snapshot isolation lets two such transactions skew; the problem is between transactions.'], why: 'Write skew comes from two transactions reading the same rows and writing different ones. Locking the rows the check reads with SELECT ... FOR UPDATE makes the second healer wait, re-read, and see only one person left on call.' },
  { id: 'qb-serializable2', c: 'serializable', type: 'mc', q: 'You add SELECT ... FOR UPDATE to the room-booking check ("no booking overlaps 2 pm, then insert"). Double bookings still happen. Why?', opts: ['With no overlapping booking, there is no row to lock', 'FOR UPDATE locks are released as soon as the SELECT returns', 'Row locks are taken at commit time, after the insert has run', 'Two sessions can each hold a FOR UPDATE lock on the same row'], a: 0, no: [null, 'FOR UPDATE locks are held until the transaction commits or aborts, which is what lets them guard a check.', 'FOR UPDATE locks rows as the SELECT reads them, not at commit. That early lock is the whole point of it.', 'FOR UPDATE locks are exclusive, so a second session blocks. Shared locks (FOR SHARE) are the ones several readers can hold.'], why: 'This is a phantom: the check is about rows that do not exist yet, so FOR UPDATE finds nothing to lock. Fix it by materialising the conflict as lockable rows, or by running at serializable isolation.' },
  { id: 'qb-serializable3', c: 'serializable', type: 'mc', q: 'To stop rooms being double booked, a teammate suggests "materialising the conflict". What does that mean in practice?', opts: ['Raise the whole database to serializable for every transaction', 'Keep both bookings as siblings and let staff pick the winner', 'Build a materialised view of bookings and run the check on it', 'Pre-create a row per room and time slot, and lock it to book'], a: 3, no: ['That also stops the phantom, but it is the broad fix, not this one. Materialising is a targeted fix that leaves other transactions alone.', 'Siblings are how multi-leader stores keep concurrent versions. Here the goal is to stop the double booking, not repair it later.', 'A materialised view is a cached query result. It gives faster reads, not a row two bookers must both lock.', null], why: 'Materialising the conflict turns a check on missing rows into rows that exist: one per room and slot. Both bookers lock the same slot row with SELECT ... FOR UPDATE, so the second waits and sees the first booking.' },
  { id: 'qb-serializable4', c: 'serializable', type: 'mc', q: 'A team moves from snapshot isolation to two-phase locking to get serializability. What new cost should they expect?', opts: ['Reads may now see rows from transactions not yet committed', 'Many commits abort at the end, and the app has to retry them', 'Readers and writers block: deadlocks and a worse p99', 'Every transaction has to run on one thread, one at a time'], a: 2, no: ['That is a dirty read, allowed only at read uncommitted. Two-phase locking holds write locks to commit, so it prevents it.', 'Aborting at commit is serializable snapshot isolation, which is optimistic. Two-phase locking blocks instead, aborting only to break deadlocks.', null, 'That is actual serial execution (VoltDB, Redis). Two-phase locking runs transactions concurrently and uses locks to order them.'], why: 'Two-phase locking takes shared locks on reads and exclusive locks on writes, held to commit. Readers block writers and writers block readers, so deadlocks appear and tail latency grows under contention.' },
  { id: 'qb-serializable5', c: 'serializable', type: 'mc', q: 'You are weighing actual serial execution (one thread, like VoltDB) for an order service. Which fact about the workload makes it a poor fit?', opts: ['The whole working dataset fits comfortably in memory', 'Transactions wait on the user\'s input between statements', 'Each transaction touches only a single partition of data', 'Every transaction is a short stored procedure on the server'], a: 1, no: ['That is a requirement for serial execution, not a problem. One thread cannot afford to wait on disk.', null, 'Single-partition transactions suit it well, since each partition can have its own thread. Cross-partition transactions are what hurt.', 'That is exactly how serial execution is meant to be used: the whole transaction is submitted at once, so the thread never waits.'], why: 'Actual serial execution only works when each transaction is short and never waits. A transaction that pauses for user input stalls the single thread, and every other transaction queues behind it.' },
  { id: 'qb-serializable6', c: 'serializable', type: 'mc', q: 'After switching to Postgres SERIALIZABLE, logs fill with "could not serialize access" errors under load. What is the right response in the app?', opts: ['Rerun the whole transaction, with a short backoff', 'Drop those queries back to read committed so the errors stop', 'Retry only the failed statement inside the same transaction', 'Raise lock_timeout so transactions wait longer before giving up'], a: 0, no: [null, 'Read committed is weaker than snapshot isolation, so the write skew the errors were preventing comes straight back.', 'The transaction is already aborted. Its earlier reads may be the stale ones, so every statement has to run again.', 'The error is not a lock wait timing out: SSI spotted a dangerous read-write pattern and aborted. lock_timeout only caps how long a statement waits for a lock.'], why: 'Serializable snapshot isolation runs optimistically and aborts one of a conflicting pair at commit. The app must expect that and rerun the whole transaction, which then reads fresh data.' },
  // multileader: Multi-Leader Conflicts & CRDTs
  { id: 'qb-multileader1', c: 'multileader', type: 'mc', q: 'Two regions accept writes and resolve conflicts with last-write-wins. A user edits their bio in both regions within the same second. What is the main risk?', opts: ['The write blocks until the other region confirms it has it', 'The two regions diverge, each keeping its own version for good', 'Both writes are rejected and the user is asked to try again', 'One edit is quietly thrown away, and nobody is told about it'], a: 3, no: ['That is synchronous cross-region replication. Multi-leader setups accept writes locally precisely to avoid that wait.', 'Last-write-wins does converge: every replica keeps the same winner. Its flaw is how it gets there.', 'Multi-leader replication accepts both writes locally. Rejecting conflicting writes needs coordination, such as a single leader per record.', null], why: 'Last-write-wins converges by keeping the write with the highest timestamp and silently dropping the other. No error is raised, so a real user edit just disappears.' },
  { id: 'qb-multileader2', c: 'multileader', type: 'mc', q: 'Region B\'s clock runs 2 seconds fast. Conflicts are resolved with last-write-wins on timestamps. What happens to edits made in region A just after an edit in B?', opts: ['The store detects the skew and keeps both versions as siblings', 'A\'s edits win, because each replica orders writes by arrival', 'A\'s newer edits can lose to B\'s older one and vanish silently', 'Nothing much, since NTP keeps clocks within a few microseconds'], a: 2, no: ['Timestamps cannot reveal skew. Spotting concurrent writes needs version vectors, which track what each replica has seen.', 'Last-write-wins orders by the timestamp on the write, not arrival time. Arrival order differs per replica, so it would not converge.', null, 'NTP over the internet keeps clocks within milliseconds at best, and a bad source or VM pause can put one seconds off. Logical clocks avoid depending on it.'], why: 'With last-write-wins, B\'s timestamps look 2 seconds in the future, so B\'s earlier edit outranks A\'s later ones. Clock skew turns causally newer writes into losers with no error.' },
  { id: 'qb-multileader3', c: 'multileader', type: 'mc', q: 'Copy P of a record has version vector {P: 3, Q: 1}. Copy Q has {P: 2, Q: 2}. What should the database do when they meet?', opts: ['Take the element-wise max, {P: 3, Q: 2}, and keep P\'s data', 'A true conflict: merge them or keep both as siblings', 'Keep P\'s version, since its counters add up to more', 'Keep Q\'s version, since it holds the latest write from Q'], a: 1, no: ['The element-wise max is the right vector for the merged result, but the data must be merged too. Keeping P\'s data drops Q\'s write.', null, 'Sums say nothing about causality. P is ahead on P\'s counter but behind on Q\'s, so neither saw the other.', 'Q is behind on P\'s counter, so it missed one of P\'s writes. Keeping Q would lose that change.'], why: 'Each copy has a counter the other has not seen (P: 3 vs 2, Q: 2 vs 1), so the writes were concurrent. The store must resolve the true conflict in the app, keep siblings, or use a CRDT.' },
  { id: 'qb-multileader4', c: 'multileader', type: 'mc', q: 'A shopping cart is an add-wins set CRDT. Offline, the phone removes socks while the laptop adds socks again. What is in the cart after they sync?', opts: ['Socks, because a concurrent add beats a remove', 'No socks, because the remove came later by the clock', 'Two pairs of socks, one from each of the devices', 'Nothing yet: sync waits for the user to choose one'], a: 0, no: [null, 'An add-wins set ignores wall clocks; it only asks whether the remove had seen the add. A last-write-wins register would compare timestamps.', 'A set holds each element once. A counter CRDT is what you would use to track quantities.', 'CRDTs merge on their own, with no user input. Asking a person to choose is the siblings approach.'], why: 'In an add-wins (observed-remove) set, a remove only deletes the adds it has seen. The laptop\'s new add was unseen by the phone\'s remove, so socks survive the merge.' },
  { id: 'qb-multileader5', c: 'multileader', type: 'mc', q: 'An active-active ticketing app runs in two regions with no cross-region coordination on writes. Why can no CRDT stop the last seat being sold twice?', opts: ['CRDT merges are too slow to run on a checkout request path', 'CRDTs are built for text editing, not for inventory records', 'CRDT counters can only go up, so seats cannot be counted down', 'Each region can sell it before hearing of the other'], a: 3, no: ['Merges are local and cheap. The problem is not speed but that the rule needs agreement before the sale.', 'CRDTs cover counters, sets, maps and registers as well as text. Their limit is rules that span replicas, not data type.', 'A PN-counter keeps one grow-only counter for increments and one for decrements, so it counts down fine. The limit is coordination.', null], why: 'A uniqueness rule like "only one buyer gets the last seat" must be checked before accepting the write. Without coordinating (a single home region or consensus), both regions can say yes, and merging later cannot undo a sale.' },
  { id: 'qb-multileader6', c: 'multileader', type: 'mc', q: 'Two offline organisers move the same stage on a festival map stored as a CRDT: one to the north field, one to the south. After sync, what is guaranteed?', opts: ['Neither organiser\'s move is ever thrown away', 'The stage ends up in exactly one valid place', 'Both devices end up showing the same result', 'The move made later by the wall clock wins'], a: 2, no: ['A last-write-wins register drops one move by design. Whether a change survives depends on the CRDT chosen.', 'CRDTs promise convergence, not sense. A multi-value register can show the stage in both fields at once.', null, 'That holds only for a last-write-wins register, which is one CRDT among many. A multi-value register keeps both moves.'], why: 'A CRDT guarantees that every replica that has seen the same updates holds the same value. It does not promise the value obeys app rules, so the app still has to resolve a stage in two places.' },
  // lsm: SSTables & Compaction
  { id: 'qb-lsm1', c: 'lsm', type: 'mc', q: 'Why does an LSM engine like RocksDB usually take writes faster than a B-tree engine like Postgres?', opts: ['It skips the write-ahead log, which saves an fsync per write', 'Writes become sequential appends, not random page rewrites', 'It updates each value in place, so nothing is ever copied', 'It keeps all data in memory and writes it out at shutdown'], a: 1, no: ['LSM engines do write a WAL; it is what keeps the memtable safe across a crash. Both designs pay for durability.', null, 'That is the B-tree model. LSM engines never edit in place; they write new versions and compact later.', 'Only the memtable is in memory, and it is flushed to SSTables when full. A pure in-memory store would be Redis.'], why: 'An LSM engine appends to its WAL, buffers in a sorted memtable, and flushes whole sorted files. Large sequential writes beat a B-tree\'s random in-place page updates, at the price of compaction later.' },
  { id: 'qb-lsm2', c: 'lsm', type: 'mc', q: 'A RocksDB node crashes while its memtable holds writes not yet flushed to an SSTable. What happens to those writes on restart?', opts: ['The write-ahead log is replayed to rebuild the memtable', 'They are lost; only data already in SSTables survives a crash', 'The newest SSTable is rolled back to before the crash point', 'A replica has to stream the missing keys back to this node'], a: 0, no: [null, 'That would be true without a WAL. Every write is logged before it is acknowledged, so it survives.', 'SSTables are immutable once written, so there is nothing to roll back. Rollback belongs to transaction undo logs.', 'Replica repair (Cassandra\'s read repair or anti-entropy) fixes nodes that missed writes, not a node that still has its own log.'], why: 'Each write is appended to the write-ahead log before it goes into the memtable. On restart the engine replays the log to rebuild the memtable, then carries on flushing as normal.' },
  { id: 'qb-lsm3', c: 'lsm', type: 'mc', q: 'A Cassandra table uses size-tiered compaction and the disk is 60% full. Ops warn the next big compaction may fail. Why?', opts: ['Each key merged leaves a new tombstone behind on the disk', 'Compaction must copy every SSTable onto another node first', 'Compaction first rewrites the commit log, doubling its size', 'The new file is written before the old ones are deleted'], a: 3, no: ['Compaction removes tombstones and the versions they hide. It does not create new ones.', 'Compaction is local to each node. Streaming SSTables between nodes happens in repair and bootstrap.', 'The commit log is only for recovering the memtable and is truncated after flushes. Compaction works on SSTables.', null], why: 'Size-tiered compaction merges several large files into one, and the inputs stay until the output is complete. Merging the biggest tier can briefly need as much free space as the files being merged: that is space amplification.' },
  { id: 'qb-lsm4', c: 'lsm', type: 'mc', q: 'A write burst hits an LSM-backed store, compaction falls behind, and p99 read latency climbs. What is the most likely cause?', opts: ['The engine disables Bloom filters under write load', 'The B-tree index rebalances after every new insert', 'Each read now has to check more SSTables per key', 'Memtable flushes lock the table against all reads'], a: 2, no: ['Bloom filters are built per SSTable at write time and stay on. More files means more filters to check, though.', 'LSM engines have no B-tree to rebalance. Page splits and rebalancing are costs of B-tree engines like InnoDB.', null, 'SSTables are immutable and the memtable is swapped out on flush, so reads carry on. Flushes cost I/O, not read locks.'], why: 'When compaction lags, small SSTables pile up, and a read may check many of them before finding the key. That is read amplification, and it hits the tail first.' },
  { id: 'qb-lsm5', c: 'lsm', type: 'mc', q: 'A metrics service ingests 200,000 points a second and mostly reads recent data. Which storage engine fits, and why?', opts: ['B-tree: its in-place updates make each single write cheaper', 'LSM: appends absorb the write rate, and files compress well', 'B-tree: LSM engines cannot do range scans over time windows', 'LSM: its reads are always faster than a B-tree lookup is'], a: 1, no: ['In-place updates mean random page writes, and each one rewrites a whole page. That makes B-trees slower at heavy ingest.', null, 'SSTables are sorted by key, so range scans work well. Cassandra and RocksDB scan time-ordered keys all the time.', 'Right engine, wrong reason. LSM reads may touch several files; B-trees give one predictable lookup path.'], why: 'LSM engines turn heavy writes into sequential appends and compress immutable sorted files well, which suits time series. The cost is read and compaction amplification, which recent-data reads keep small.' },
  { id: 'qb-lsm6', c: 'lsm', type: 'mc', q: 'A Cassandra replica was down for three weeks, longer than gc_grace_seconds. After it rejoins, rows deleted meanwhile reappear. Why?', opts: ['Other replicas dropped tombstones it never received', 'Its commit log replayed writes from before it went down', 'Its Bloom filters were stale and hid the newer tombstones', 'Hinted handoff replayed the original inserts to the node'], a: 0, no: [null, 'Those writes are older than the deletes. With the tombstones present they would stay hidden; the real issue is that the tombstones are gone.', 'Bloom filters can only cause extra reads, never hide data that is present. Tombstones are still found when files are read.', 'Hints hold the writes a node missed, including deletes, and expire after a few hours by default.'], why: 'Tombstones are kept for gc_grace_seconds, then compaction drops them. A replica that missed the delete still holds the old row, and with no tombstone left anywhere to outrank it, repair spreads the row back.' },
  { id: 'qb-lsm7', c: 'lsm', type: 'mc', q: 'An LSM read checks the memtable, then SSTables from newest to oldest, and stops at the first version of the key it finds. Why that order?', opts: ['Older files are more heavily compressed, so they go last', 'Newer files are more likely in cache, so they are cheaper', 'Files are split by key range, so the newest covers the key', 'The newest version, or tombstone, is the current one'], a: 3, no: ['Compression level is not why. Even if every file were uncompressed, the order would have to stay the same.', 'They may be cached, but that is a side effect. Checking oldest first would return stale values however fast it was.', 'Leveled stores split each level by key range, but one key can still have versions in several levels. Recency decides.', null], why: 'Nothing is edited in place, so a key can live in several files. The newest version, or a tombstone, supersedes everything older, so the search stops as soon as it finds one.' },
  // bloom: Bloom Filters
  { id: 'qb-bloom1', c: 'bloom', type: 'mc', q: 'You want a Bloom filter over 100 million keys with roughly a 1% false positive rate. About how much memory does it need?', opts: ['About 12 MB', 'About 120 MB', 'About 1.2 GB', 'About 12 GB'], a: 1, no: ['That is about 1 bit per key, which gives a false positive rate well over 50%.', null, 'That is about 100 bits per key, far more than 1% needs. It would give a near-zero false positive rate.', 'That is about 1,000 bits per key, as much as storing each key in full in a hash set.'], why: 'About 10 bits per key gives roughly 1%: 100 million keys times 10 bits is a billion bits, about 125 MB. That is far less than storing the keys themselves.' },
  { id: 'qb-bloom2', c: 'bloom', type: 'mc', q: 'An engine sized its SSTable Bloom filters for 10 million keys per file, but files now hold 100 million. What happens to reads?', opts: ['Inserts start failing once every bit has been set', 'False positives soar, so reads open files for nothing', 'Writes slow down while the filter rebalances its bits', 'Some keys that are present get reported as absent'], a: 1, no: ['Setting a bit that is already 1 is fine, so inserts never fail. The filter just answers "maybe" more often.', null, 'Bloom filters have no rebalancing step. Rebalancing is something B-trees and consistent hashing rings do.', 'A Bloom filter never gives false negatives, however full it gets. Every added key\'s bits stay set.'], why: 'With ten times the keys per bit, most bits become 1 and almost every lookup says "maybe". The filter stops saving work, and reads open SSTables that do not hold the key.' },
  { id: 'qb-bloom3', c: 'bloom', type: 'mc', q: 'You need to delete keys, so you swap a plain Bloom filter for a counting Bloom filter. What is the main cost?', opts: ['Several times the memory: a small counter per slot', 'It must store each full key so it can undo an insert', 'The whole filter is rebuilt from scratch on each delete', 'Each lookup must now run twice as many hash functions'], a: 0, no: [null, 'Storing full keys would defeat the point of a filter. Decrementing the key\'s k counters is enough to undo it.', 'Deleting just decrements k counters. Rebuilding is what a plain filter would need, since it cannot delete at all.', 'A counting filter uses the same k hash functions. Only what each slot holds changes.'], why: 'A counting Bloom filter swaps each bit for a small counter, often 4 bits, so it uses several times the memory. Adds increment the k counters and deletes decrement them.' },
  { id: 'qb-bloom4', c: 'bloom', type: 'mc', q: 'A CDN wants to stop filling its cache with objects that are only ever requested once. How does a Bloom filter help?', opts: ['Check the filter before each cache lookup, to skip lookups that miss', 'Track recent requests and evict the least recently used ones', 'Store each object\'s bytes in the filter to save cache memory', 'Cache on the second request; the filter recalls the first'], a: 3, no: ['That saves a cheap local lookup but does nothing to keep one-hit objects out of the cache. Pre-checks pay off when the miss path is expensive, as in LSM reads.', 'LRU needs an ordering of accesses, which a Bloom filter cannot give. LRU eviction usually uses a hash map plus a linked list.', 'A Bloom filter stores only bits, not data. It can say whether something was seen, never return it.', null], why: 'On the first request the CDN only adds the URL to the filter; it caches the object when the filter says it was seen before. One-hit wonders never take cache space, and a false positive only caches one extra object.' },
  { id: 'qb-bloom5', c: 'bloom', type: 'mc', q: 'A web crawler tracks 10 billion seen URLs. Why use a Bloom filter instead of a hash set of the URLs?', opts: ['It can list every URL crawled so far for auditing', 'It lets you delete URLs once they are due a recrawl', 'It needs bits per URL rather than the URL itself', 'It never wrongly skips a URL it has not seen before'], a: 2, no: ['A Bloom filter cannot enumerate its keys, since it stores only shared bits. A hash set or a database can.', 'A plain Bloom filter cannot delete, because bits are shared. A counting Bloom filter can, at several times the memory.', null, 'It can: a false positive makes the crawler skip a new URL. The guarantee runs the other way, no false negatives.'], why: 'Ten billion URLs at 50 to 100 bytes each would need hundreds of gigabytes in a hash set. A Bloom filter needs about 10 bits per URL for 1% false positives, roughly 12.5 GB.' },
  { id: 'qb-bloom6', c: 'bloom', type: 'mc', q: 'A crawler skips any URL its Bloom filter says it has seen. The filter has a 1% false positive rate. What is the effect?', opts: ['About 1% of inserts are dropped by the filter', 'About 1% of new URLs are skipped and never crawled', 'About 1% of URLs are crawled twice by mistake', 'About 1% of lookups are slow but come back exact'], a: 1, no: ['Inserts always succeed: they just set bits. The rate describes lookups of keys never added.', null, 'Crawling twice would need the filter to forget a URL, a false negative, which Bloom filters never give.', 'Exact answers need a second check against the full store. Here the crawler trusts the filter, so nothing verifies.'], why: 'A false positive means the filter says "seen" for a URL it never saw. The crawler trusts it, so about 1% of new URLs are missed: an acceptable loss traded for a lot of memory.' },
  // schemaevo: Encoding & Schema Evolution
  { id: 'qb-schemaevo1', c: 'schemaevo', type: 'mc', q: 'A new producer adds field 7 (referrer) to a Protobuf event. Consumers still on the old schema read these events. What happens?', opts: ['They skip the unknown tag 7 and read the rest of the message', 'They must fetch the new schema from the registry to decode it', 'They read the referrer bytes into the next field they do know', 'They fail to parse the message and send it to a dead letter queue'], a: 0, no: [null, 'That is Avro, which needs the writer\'s schema to decode. Protobuf carries tags on the wire, so old code decodes alone.', 'Each field carries its tag and wire type, so the parser knows exactly how many bytes to skip and nothing spills over.', 'Protobuf parsers skip tags they do not know, so parsing succeeds. A dead letter queue is for messages that truly fail.'], why: 'This is forward compatibility: old code survives new data. Protobuf tags each field and tells the parser its length, so an old reader skips unknown tags and keeps working.' },
  { id: 'qb-schemaevo2', c: 'schemaevo', type: 'mc', q: 'A backend sends 64-bit post IDs as JSON numbers. The JavaScript front end shows some IDs off by a few, so links 404. Why?', opts: ['UTF-8 encoding mangles long strings of digits on the way over', 'The IDs are Snowflake IDs, which are not unique across machines', 'JSON has no integer type, so it rounds every number to 32 bits', 'JS numbers are doubles, exact only up to 2^53, so big IDs round'], a: 3, no: ['Digits are plain ASCII and pass through UTF-8 unchanged. The loss happens when the text is parsed as a number.', 'Snowflake IDs embed a machine ID, so they are unique. They are 64-bit, though, which is why they hit this.', 'JSON does not round to 32 bits; it leaves precision to the parser. In JavaScript the parser gives a double.', null], why: 'JavaScript parses every JSON number as a 64-bit double, which is exact only up to 2^53. Larger IDs round to a nearby value; send them as strings instead.' },
  { id: 'qb-schemaevo3', c: 'schemaevo', type: 'mc', q: 'A teammate adds a new proto2 field and marks it required. Old producers are still running. Why do reviewers push back?', opts: ['Required fields cost extra bytes on every single message', 'Protobuf ignores required, so the label adds no safety', 'Old producers never set it, so new readers reject them', 'A required field can never be renamed later on'], a: 2, no: ['Required has no wire cost; it is a check made when parsing. The cost is in compatibility.', 'proto2 does enforce required, rejecting messages without it. proto3 dropped required because of this exact pain.', null, 'Renaming is free in Protobuf because names never go on the wire. The tag number is what must stay fixed.'], why: 'New readers reject any message missing a required field, and old producers do not know it exists. That breaks backward compatibility, and removing the field later breaks old readers, so a required field is forever.' },
  { id: 'qb-schemaevo4', c: 'schemaevo', type: 'mc', q: 'Avro binary data carries no field tags or names. How does a newer reader decode a record written years ago?', opts: ['It matches fields by position in its own schema', 'It resolves the writer\'s schema against its own', 'It infers each field\'s type from the raw bytes', 'It reads the field names stored inside each record'], a: 1, no: ['Positions shift when fields are added or removed, so this would misread old data. Avro needs the writer\'s layout.', null, 'Avro bytes are not self-describing, so types cannot be guessed. Self-describing formats include JSON and MessagePack.', 'That is JSON, which repeats names in every record. Avro keeps records small by leaving names out.'], why: 'The reader gets the writer\'s schema (from the file header or a schema registry) and resolves it against its own by field name, filling defaults for new fields and skipping removed ones.' },
  { id: 'qb-schemaevo5', c: 'schemaevo', type: 'mc', q: 'Mid-migration, v2 reads the old column and dual-writes both. You ship v4, which reads and writes only the new column, as a rolling deploy. What breaks?', opts: ['v2 instances keep reading the old column, which goes stale', 'v4 instances miss rows that v2 instances write meanwhile', 'Rows stay locked until every instance has been restarted', 'The backfill job reruns and overwrites the newer values'], a: 0, no: [null, 'v2 dual-writes, so the new column gets every write. The gap is in the other direction.', 'A deploy does not take row locks. Long locks come from schema changes like a blocking ALTER TABLE.', 'Backfills run once as a separate job, not on each deploy. The trouble here is between live versions.'], why: 'Expand and contract moves reads to the new column (v3, still dual-writing) before anyone stops writing the old one. Skipping v3 leaves v2 instances serving stale data during the rollout.' },
  { id: 'qb-schemaevo6', c: 'schemaevo', type: 'mc', q: 'What does a schema registry in front of Kafka actually do for you?', opts: ['It encrypts payloads so only registered consumers can read them', 'It rewrites old messages on the topic into the newest schema', 'It routes each message only to consumers that know its version', 'It rejects incompatible schema changes before release'], a: 3, no: ['Encryption is TLS on the wire or encryption at rest. The registry stores schemas and their IDs.', 'Kafka messages are immutable, and the registry never touches them. Readers resolve old schemas when they decode.', 'Kafka delivers every message on a topic to every consumer group. Routing by type would need separate topics.', null], why: 'Producers register each schema and tag messages with its ID. The registry checks every new version against a compatibility rule, such as backward, and rejects breaking changes before they reach the topic.' },
  { id: 'qb-schemaevo7', c: 'schemaevo', type: 'mc', q: 'Years of Protobuf events sit in storage. Why is renaming a field safe, while changing its tag number is not?', opts: ['The registry tracks renames and remaps old names on read', 'Names are hashed into the tag number when protoc compiles', 'The wire carries tag numbers, so a new name changes no bytes', 'Renumbering is safe too, once every service upgrades together'], a: 2, no: ['Protobuf needs no registry to decode; names are only in the generated code. Avro is the format that resolves fields by name.', 'Tags are numbers you write in the .proto file, not hashes. That is why you can choose and reserve them.', null, 'Stored events keep the old tags forever, so upgrading the services does not fix the data. Old tags would read as wrong fields.'], why: 'Protobuf encodes each field as its tag number plus a value. A rename changes only generated code, but a new tag makes all old data unreadable for that field, so retire old tags with reserved.' },
  // raftlog: Log Replication & Total Order Broadcast
  { id: 'qb-raftlog1', c: 'raftlog', type: 'mc', q: 'A Raft follower has stored entry 9 on disk, but the leader\'s commit index is still 8. Can the follower apply entry 9 to its state machine?', opts: ['No: it waits until every follower has stored it too', 'No: it waits for the leader to mark 9 committed', 'Yes: storing it on disk makes the entry final', 'Yes, as soon as it has acknowledged it to the leader'], a: 1, no: ['Raft commits on a majority, not all nodes, so one slow follower cannot stall the cluster.', null, 'An entry stored on a minority can still be overwritten by a later leader. Durability on one node is not commitment.', 'Its acknowledgement is one vote toward a majority. Until the leader counts a majority, entry 9 may not survive.'], why: 'Only committed entries are applied. The leader commits once a majority stores the entry, then tells followers via its commit index in later messages; until then entry 9 might be overwritten.' },
  { id: 'qb-raftlog2', c: 'raftlog', type: 'mc', q: 'A follower gets an append for entry 10 that says the previous entry is index 9, term 3. The follower\'s entry 9 has term 2. What does it do?', opts: ['Reject it, so the leader retries from an earlier index', 'Accept it and keep its own entry 9 alongside it', 'Start an election, since the leader looks out of date', 'Accept it, since the higher term always wins the slot'], a: 0, no: [null, 'Keeping a mismatched entry 9 would break the log matching rule: logs that agree at an index must agree on everything before it.', 'A leader with a higher term is the current one, not stale. Followers start elections on missed heartbeats.', 'Accepting would place entry 10 after an entry the leader never had. The follower must reject so the leader can repair it.'], why: 'The consistency check on prevIndex and prevTerm fails, so the follower rejects. The leader walks back until the logs agree, then overwrites the follower\'s conflicting, uncommitted tail.' },
  { id: 'qb-raftlog3', c: 'raftlog', type: 'mc', q: 'In Raft, why does a node refuse its vote to a candidate whose log is behind its own?', opts: ['So two leaders cannot both be elected in the same term', 'So the node with the highest ID wins when votes are tied', 'So elections finish faster, with fewer candidates competing', 'So that any new leader already holds every committed entry'], a: 3, no: ['That comes from each node voting at most once per term, with a majority needed to win.', 'Raft does not break ties by node ID. A split vote just times out and a new election starts.', 'Randomised election timeouts are what make elections end quickly. The log check is about safety, not speed.', null], why: 'A committed entry is on a majority, and a candidate needs a majority of votes, so at least one voter has the entry. That voter refuses a candidate whose log is behind, so only up-to-date candidates can win.' },
  { id: 'qb-raftlog4', c: 'raftlog', type: 'mc', q: 'A teammate says "we do not need consensus, just total order broadcast so every replica sees the same sequence." What is the flaw?', opts: ['Total order broadcast needs tightly synchronised clocks to work', 'Total order broadcast only runs over UDP multicast networks', 'Total order broadcast is equivalent to consensus, not cheaper', 'Total order broadcast lets replicas see messages in differing orders'], a: 2, no: ['Clock-based ordering breaks under skew, so total order broadcast does not rely on clocks. It uses a consensus log.', 'It is defined over messages, not a transport. etcd and ZooKeeper implement it over TCP.', null, 'Same order on every node is the definition of total order broadcast. Differing orders describe gossip or causal broadcast.'], why: 'Total order broadcast and consensus can each be built from the other. A replicated log, as in Raft or Zab, is how you get total order broadcast, so skipping consensus is not an option.' },
  { id: 'qb-raftlog5', c: 'raftlog', type: 'mc', q: 'A term 4 leader appends entries 6 and 7, then crashes before sending them anywhere. The term 5 leader never had them. What happens when the old leader rejoins?', opts: ['Entries 6 and 7 replicate out, since they were written first', 'Its entries 6 and 7 are overwritten by the new leader\'s log', 'The cluster halts until an operator chooses one of the logs', 'The new leader merges 6 and 7 into its own log at the end'], a: 1, no: ['Writing first means nothing in Raft; the current leader\'s log is authoritative. Those entries were never committed.', null, 'Raft repairs logs automatically through the log matching rule. Operators step in for lost quorums, not this.', 'Raft never merges logs; data only flows from leader to follower. A client that saw no commit can resend.'], why: 'Entries 6 and 7 were only on the old leader, so they were never committed. The new leader\'s appends fail the consistency check, it walks back, and the follower\'s uncommitted tail is overwritten.' },
  { id: 'qb-raftlog6', c: 'raftlog', type: 'mc', q: 'You grow an etcd cluster from 3 voting members to 7 for safety. Write latency goes up. Why?', opts: ['Each commit now needs 4 of 7 members to store it, not 2 of 3', 'Every member must apply each entry before it commits', 'Reads now go to followers, which slows the leader down', 'Seven members split into two leaders far more often'], a: 0, no: [null, 'Commit needs a majority to store the entry, not to apply it. Applying happens after commit.', 'Cluster size does not move reads around. Serving reads from followers would take load off the leader, not slow writes.', 'Raft allows at most one leader per term, whatever the size. More members just means more votes to collect.'], why: 'A commit needs a majority, so more voters means more acks to wait for, and the slowest node in that majority sets the pace. That is why etcd recommends 3 or 5 voting members.' },
  // linearizable: Linearizability in Practice
  { id: 'qb-linearizable1', c: 'linearizable', type: 'mc', q: 'Two people sign up as "ada" at the same moment. Each signup checks "is ada taken?" on a different async follower, finds it free, and succeeds. What was missing?', opts: ['Each check could read stale data; uniqueness must see the latest claim', 'Each follower needs serializable isolation for its local signup transaction', 'The signup request needs an idempotency key so the retry is deduplicated', 'A cache of taken usernames in front of the followers would catch the second'], a: 0, no: [null, 'Serializable on one replica only orders transactions on that replica; it cannot see a write that has not replicated there yet.', 'These are two different people, not one retried request. Idempotency keys stop a retried payment or POST from running twice.', 'A cache is another possibly stale copy, so it is weaker still. Caches cut read load; they do not give recency.'], why: 'A uniqueness constraint needs every check to see the latest claim, as if there were one copy. Checking on a lagging follower is not linearizable, so both see "free"; the check must go through the leader or a consensus store.' },
  { id: 'qb-linearizable2', c: 'linearizable', type: 'mc', q: 'A linearizable store is split by a network partition. Two of its five nodes end up on the minority side. What must those two nodes do?', opts: ['Keep serving reads from local data and refuse only the writes', 'Refuse reads and writes until they can reach a majority again', 'Accept writes locally and merge them later with last write wins', 'Elect a leader of their own so both sides keep serving clients'], a: 1, no: ['Their data may already be stale, since the majority side can keep committing writes. A stale read breaks the recency guarantee.', null, 'Last write wins with later merging is how an available, eventually consistent (AP) store like Cassandra behaves, not a linearizable one.', 'Two leaders is split brain: both sides accept conflicting writes. Consensus (Raft, Paxos) requires a majority to elect a leader for exactly this reason.'], why: 'This is the CAP trade-off: to stay linearizable, the minority side cannot know what the majority has committed, so it must stop answering. Only the side with a quorum keeps serving.' },
  { id: 'qb-linearizable3', c: 'linearizable', type: 'mc', q: 'A Raft leader can serve linearizable reads with a read index or with a leader lease. What does the lease rely on that the read index does not?', opts: ['A round trip to a majority before answering each read', 'Synchronous replication of every write to all followers', 'Clocks on the nodes drifting apart by only a bounded amount', 'Fsyncing its log to local disk before it answers each read'], a: 2, no: ['That is the read index: the leader confirms with a majority that it still leads. The lease exists to skip that round trip.', 'Raft only needs a majority to commit. Waiting for every follower adds latency and does not help a deposed leader notice.', null, 'Durability of the log matters for writes. A read does not change the log, so fsync does not tell the leader it is still leader.'], why: 'A lease lets the leader assume no new leader can be elected until the lease runs out, so it answers locally. That is only safe if clock drift is bounded; the read index trades that assumption for a quorum round trip per read.' },
  { id: 'qb-linearizable4', c: 'linearizable', type: 'mc', q: 'A teammate says: "Our Dynamo-style store reads and writes with quorums, R + W > N, so reads are linearizable." What is the best reply?', opts: ['Yes: R + W > N means each read overlaps the latest write\'s replicas', 'Yes, as long as NTP keeps clocks close so last write wins picks right', 'Not by itself: a read racing a write can see new, then a later read old', 'No: linearizability needs a single node, so no replicated store can have it'], a: 2, no: ['The overlap guarantees a read meets one replica with the write once it completes. During an in-flight write, reads can still disagree.', 'Last write wins by timestamp can silently drop writes when clocks skew, which is itself a reason Dynamo-style stores are not linearizable.', null, 'Consensus systems such as etcd, ZooKeeper and Spanner are replicated and linearizable. It costs latency, not replication.'], why: 'While a write has reached only some replicas, one quorum read can return the new value and a later one the old, breaking recency. Synchronous read repair can fix that for plain reads and writes, but quorums alone, especially with last write wins, are not linearizable.' },
  { id: 'qb-linearizable5', c: 'linearizable', type: 'mc', q: 'Cluster nodes find the current leader by reading a "leader" key from any replica of a store, and some replicas lag. What failure does this invite?', opts: ['The key is lost whenever the leader node restarts', 'Every read waits on a quorum, so failover takes minutes', 'Every node polls the key, so its partition runs hot and throttles', 'Some nodes obey a deposed leader: two leaders act at once'], a: 3, no: ['Losing the key on restart is a durability problem, which replication already solves. The issue here is reading an old value.', 'Reading any replica is the fast, weak option: no quorum is involved. Quorum reads would actually fix this.', 'Polling a key is cheap and a hot key is solved by caching or backoff. It does not cause two leaders.', null], why: 'Leader election needs a linearizable view of who holds the lock. A stale replica can still name the old leader, so some nodes follow it while others follow the new one: split brain.' },
  { id: 'qb-linearizable6', c: 'linearizable', type: 'mc', q: 'A store is replicated across three regions. You make every read linearizable. What is the main cost you pay?', opts: ['Each read takes a row lock that blocks writers until it ends', 'Each read pays a round trip to a majority, often cross-region', 'Each replica must now hold a full copy of every single key', 'Each write must reach all three regions before it can commit'], a: 1, no: ['Blocking writers with read locks is two-phase locking, used for serializable transactions. Linearizable reads confirm recency; they do not lock.', null, 'Replication factor is a separate choice; partitioned data can be linearizable per key. The cost is coordination, not storage.', 'A majority (two of three) is enough to commit. Waiting for all replicas is fully synchronous replication and would hurt availability.'], why: 'To prove a value is current, a read must check with a majority (quorum read or read index), or trust a lease. Across regions that is tens of milliseconds per read, which is why most systems offer weaker reads on purpose.' },
  // windows: Windows & Watermarks
  { id: 'qb-windows1', c: 'windows', type: 'mc', q: 'A dashboard shows "orders in the last hour", and should refresh every 5 minutes. Which window fits?', opts: ['Tumbling one-hour windows, each emitted when its hour ends', 'Session windows per order, with a gap of 5 minutes', 'Hopping one-hour windows that advance every 5 minutes', 'One global window with a trigger firing every 5 minutes'], a: 2, no: ['Tumbling hours only update once an hour and show "since 2:00", not the last 60 minutes. Tumbling fits fixed reports like sales per hour.', 'Session windows group one key\'s activity until a quiet gap, like a user visit. An order is a single event, not a session.', null, 'A global window keeps everything since the job started, so the count grows forever instead of covering the last hour.'], why: 'Hopping windows overlap: each covers an hour, and a new one starts every 5 minutes, so each refresh shows a full trailing hour.' },
  { id: 'qb-windows2', c: 'windows', type: 'mc', q: 'A Flink job\'s watermark is at 10:05. An event with event time 09:58 arrives for a 09:00 to 10:00 window. Allowed lateness is zero. What happens?', opts: ['It is late: dropped, or sent to a side output if one is set', 'It is counted in the window that covers 10:05, the current time', 'The watermark moves back to 09:58 and the window reopens', 'The job pauses until the 09:00 window is recomputed in full'], a: 0, no: [null, 'That is processing-time windowing, which puts late events in the wrong window. Event-time windows place events by when they happened.', 'Watermarks only move forward. Allowed lateness is how you keep a window open for corrections after the watermark passes.', 'Streams do not pause to recompute. Recomputing complete results from the raw input is what a batch job is for.'], why: 'The watermark said no events older than 10:05 were expected, so the 09:00 window was already emitted. With no allowed lateness, the event is too late: dropped by default, or routed to a side output for separate handling.' },
  { id: 'qb-windows3', c: 'windows', type: 'mc', q: 'You tighten a job\'s watermark from 30 minutes behind the newest event to 1 minute behind. What do you gain and what do you lose?', opts: ['Gain more complete counts; lose speed, as results arrive later', 'Gain exactly-once output; lose some throughput to checkpoints', 'Gain lower memory; lose accuracy, as late events count twice', 'Gain fresher results and less state; lose more events as late'], a: 3, no: ['That is loosening the watermark: waiting longer for stragglers makes results complete but stale.', 'Exactly-once comes from checkpoints and transactional sinks, not from the watermark. The watermark only decides when windows close.', 'Less state is right, but late events are dropped or corrected, not double counted. Duplicates come from at-least-once delivery.', null], why: 'A strict watermark closes windows sooner, so results are fresh and fewer windows sit in memory. The price is that more events miss the watermark and are dropped, side-output, or applied as corrections.' },
  { id: 'qb-windows4', c: 'windows', type: 'mc', q: 'A click stream at 200k events a second must be tagged with each user\'s country from a users table in Postgres. A query per event is too slow. Usual streaming approach?', opts: ['Keep a local copy of users, kept current from its changelog', 'Join the clicks once a night against a Postgres export', 'Read a Postgres replica for each event, to spare the primary', 'Do a windowed join of clicks against a stream of signups'], a: 0, no: [null, 'A nightly join makes the tags a day late. That is batch enrichment, fine for reports but not a live stream.', 'A replica still costs a network round trip per event at 200k a second. Replicas spread read load for request paths.', 'Signups only include new users, and a window drops anyone who signed up before it. Stream-stream joins fit two event streams, like ad views and clicks.'], why: 'A stream-table join keeps the table in the processor\'s local state, fed by its change data capture stream, so each click is enriched from memory or local disk with no remote call.' },
  { id: 'qb-windows5', c: 'windows', type: 'mc', q: 'Session windows have a 30-minute gap. A user has clicks from 10:00 to 10:20 and from 11:00 to 11:15. A late click stamped 10:45 arrives. What happens?', opts: ['It starts a third session of its own, from 10:45', 'It joins whichever session is nearer, the 11:00 one', 'The two sessions merge into one visit, 10:00 to 11:15', 'It is dropped, since it lands in the gap between them'], a: 2, no: ['A new session only starts after a quiet gap, and 10:45 is within 30 minutes of clicks on both sides.', 'Session windows do not pick one neighbour. The click bridges both, so both are affected.', null, 'Lateness decides dropping, and that depends on the watermark, not on gaps. A click in a gap shortens it.'], why: 'The 10:45 click is within 30 minutes of 10:20 and of 11:00, so the gap that separated the sessions disappears and they merge. Session windows are the one window type that can merge as late data arrives.' },
  { id: 'qb-windows6', c: 'windows', type: 'mc', q: 'After a bug fix you replay last month\'s events through a job that windows by processing time. What goes wrong?', opts: ['Each event is counted twice: once from the old run and once now', 'A month of events lands in the few minutes the replay takes', 'The watermark stalls on old events, so no window is ever emitted', 'Events arrive out of order, so the job rejects most of them'], a: 1, no: ['Double counting depends on how results are written: idempotent writes or overwriting the output avoid it. It is not a windowing effect.', null, 'Processing-time windows do not use watermarks at all; they close on the wall clock. Event-time watermarks would advance through the old data.', 'Processing-time windows ignore event order, so nothing is rejected as late. Lateness only exists with event time.'], why: 'Processing time is when the event reached you, so a replay puts every event in the windows of the replay itself. Windowing by event time gives the same results on a replay as on the live run.' },
  // outbox: Dual Writes, Outbox & CDC
  { id: 'qb-outbox1', c: 'outbox', type: 'mc', q: 'To stop losing events, a developer flips the order: publish OrderPlaced to Kafka first, then commit the order to Postgres. What breaks now?', opts: ['If the commit fails, consumers act on an order that does not exist', 'Kafka rejects events whose order ID is not yet in the database', 'Kafka retries the publish until the commit lands, causing duplicates', 'The commit waits until every consumer has read the event'], a: 0, no: [null, 'Kafka knows nothing about your database; it stores whatever is sent. Checking references is the job of foreign keys inside one database.', 'Producer retries cover a failed send to Kafka, not your database commit. Kafka has no idea whether the commit happened.', 'Publishing is fire and forget for the producer; consumers read later at their own pace. Waiting for readers would be a synchronous call.'], why: 'Flipping the order only moves the gap: now the event can exist without the row. The fix is the transactional outbox, which writes the row and the event in one local transaction.' },
  { id: 'qb-outbox2', c: 'outbox', type: 'mc', q: 'The outbox relay publishes a batch of events, then crashes before marking the rows sent. On restart it publishes them again. What must consumers do?', opts: ['Nothing: Kafka drops any message it has already stored once', 'Dedupe by event ID, for example with a processed-events table', 'Use a two-phase commit between the relay and the Kafka broker', 'Enable offset auto-commit, so that repeated messages are skipped'], a: 1, no: ['The idempotent producer only dedupes retries within one producer session. A restarted relay sends the events as new messages.', null, 'Kafka does not join XA two-phase commits, and avoiding 2PC is why the outbox exists. 2PC fits databases that share a coordinator.', 'Offsets track how far a consumer has read, not what it has seen. Republished events get new offsets and are read again.'], why: 'An outbox relay delivers at least once: it can always crash between publishing and marking. Consumers make that safe by recording each event ID they have handled and skipping repeats.' },
  { id: 'qb-outbox3', c: 'outbox', type: 'mc', q: 'Two requests change one product\'s price at once; each writes Postgres, then Elasticsearch. Postgres ends at $12 but search shows $10. Why?', opts: ['The two writes reached the two stores in different orders', 'Read committed isolation in Postgres let one update be lost', 'Elasticsearch\'s refresh interval is hiding the newest version', 'The two versions were hashed to different Elasticsearch shards'], a: 0, no: [null, 'Postgres holds a row lock for each UPDATE, so both apply in turn and $12 is a valid final value. Lost updates come from read-modify-write in app code.', 'Refresh lag lasts about a second and then the latest indexed version shows. This mismatch is permanent.', 'Documents are routed by ID, so both versions go to the same shard and one overwrites the other.'], why: 'With dual writes, request A can win the race in Postgres and request B in Elasticsearch, so the two stores end with different last writers. CDC fixes this by feeding the index changes in the database\'s commit order.' },
  { id: 'qb-outbox4', c: 'outbox', type: 'mc', q: 'What does change data capture give you that a transactional outbox does not?', opts: ['Exactly-once delivery, so consumers no longer need to dedupe', 'Events shaped as a public contract, separate from the tables', 'Lower write latency, since it publishes before the commit lands', 'Every committed change, including ones that bypass your code'], a: 3, no: ['CDC connectors also deliver at least once, for example after a connector restart, so consumers still dedupe.', 'That is the outbox\'s strength: you choose the event shape. Raw CDC exposes table rows, so consumers couple to your schema.', 'CDC reads the log after the commit; it never publishes uncommitted changes. Write latency is unchanged.', null], why: 'CDC tails the database\'s own log, so any committed change shows up, whether from your service, a migration or an admin script. The outbox only captures events your code chose to write.' },
  { id: 'qb-outbox5', c: 'outbox', type: 'mc', q: 'Your outbox relay polls the outbox table every 100 ms, which adds load and delay. What is the usual upgrade that keeps the same guarantee?', opts: ['Have a CDC connector read outbox inserts from the WAL', 'Move the outbox table into Redis so polling is cheaper', 'Publish from the request after commit, then skip the outbox', 'Put a read-through cache in front of the outbox table'], a: 0, no: [null, 'The outbox works because it is in the same database transaction as the business row. A Redis outbox is a dual write again.', 'That is the original dual write: a crash after commit loses the event.', 'A cache would serve stale lists of unsent rows, so events are published late or twice. Caches suit hot reads, not work queues.'], why: 'Debezium\'s outbox pattern tails the WAL and turns each outbox insert into an event, in commit order, with no polling queries. The outbox row is still written in the same transaction as the business change.' },
  { id: 'qb-outbox6', c: 'outbox', type: 'mc', q: 'Products flow from Postgres through CDC into Kafka and on to the search index. The index gets corrupted. How do you rebuild it?', opts: ['Restore the search index from last night\'s Postgres backup', 'Snapshot the table, then replay the change stream into a new index', 'Ask each service to resend its recent writes to the indexer', 'Copy the documents back out of the Redis cache that holds products'], a: 1, no: ['A Postgres backup restores Postgres, not the index, and loses everything since the backup. Backups protect the source of truth itself.', null, 'Services do not remember their past writes, and admin changes would be missed. That puts dual writes back in.', 'A cache holds only hot items, possibly stale, so it is incomplete. Caches are derived data too, not a source to rebuild from.'], why: 'The index is derived data: rebuild it from the source of truth. A CDC connector takes a consistent snapshot of the table, then continues from the log position, so the new index catches up and you switch over.' },
  // batch: Batch Processing
  { id: 'qb-batch1', c: 'batch', type: 'mc', q: 'A nightly Spark job fails at 3 a.m. halfway through writing its output. Why can you usually just rerun the whole job?', opts: ['Spark checkpoints every record, so a rerun resumes mid-file', 'The input is untouched and the output is written fresh', 'The job ran inside a transaction that was rolled back', 'Each reducer appends only rows that are not already there'], a: 1, no: ['Spark retries failed tasks from their input, not from per-record checkpoints. Checkpointing every record is a streaming idea, and costly.', null, 'Batch jobs over files do not run in one database transaction. The safety comes from never modifying the input.', 'Appending with dedupe is fragile and slow on big outputs. Batch jobs overwrite their output directory instead.'], why: 'Batch jobs treat input as immutable and write a new output, so a failed run leaves only a partial output to throw away. Rerunning reads the same input and produces the same result.' },
  { id: 'qb-batch2', c: 'batch', type: 'mc', q: 'A MapReduce job joins orders with customers by customer ID. What is the shuffle step there for?', opts: ['So the mappers can sort their input files before reading them', 'So each reducer receives the same number of records', 'So the final output files come out sorted by customer ID', 'So all records for one customer reach the same reducer'], a: 3, no: ['Mappers read input in whatever order it is stored. Sorting happens during the shuffle, on the mapper outputs.', 'The shuffle splits by key, not by count, which is exactly why one hot key can overload one reducer.', 'Sorted output can be a side effect of the sort in the shuffle, but it is not the point. Grouping by key is.', null], why: 'Mappers emit (customer ID, record) pairs from both inputs; the shuffle sends every pair with the same key to the same reducer, which then sees a customer and all their orders together and joins them.' },
  { id: 'qb-batch3', c: 'batch', type: 'mc', q: 'A team runs a Flink job for live counts and a separate nightly Spark job, and keeps fixing bugs in one but not the other. Which change addresses that?', opts: ['Add a serving layer that merges the two jobs\' outputs', 'Add a reconciliation job that alerts when the outputs differ', 'Run both jobs on one shared cluster so they use the same config', 'Keep one stream job, and replay the log through it to recompute'], a: 3, no: ['That is the lambda architecture they already have. The merge layer does not remove the two codebases.', 'Reconciliation finds the drift but does not stop it. It is useful as a check, not as a fix for duplicated logic.', 'Sharing a cluster does not share logic. The bug lives in two copies of the code, wherever they run.', null], why: 'This is the kappa architecture: one stream job is the only code, and you recompute history by replaying the retained log through it, instead of keeping batch and stream versions in step.' },
  { id: 'qb-batch4', c: 'batch', type: 'mc', q: 'You salt a hot key in a batch count, splitting "tuna" into tuna#1 to tuna#4. What extra work does this require?', opts: ['A lock so the four reducers do not write tuna at once', 'Rehashing the other keys so they avoid the salted reducers', 'A small second step that adds the four partial counts', 'Sorting the input so tuna records arrive in salt order'], a: 2, no: ['Each salted key is its own group with its own output. Nothing writes the same row at once, so no lock is needed.', 'Other keys hash as before; the salted keys just spread over more reducers. Rehashing everything would only add work.', null, 'Salt is assigned per record, often at random, and order does not matter for a sum. Sorting would add cost for nothing.'], why: 'Salting turns one huge group into four smaller partial results, one per reducer. A cheap second aggregation by the original key adds them back into one tuna total.' },
  { id: 'qb-batch5', c: 'batch', type: 'mc', q: 'Finance needs monthly revenue that matches the ledger to the cent, including refunds posted days late. Which fits?', opts: ['A batch job over the full month of ledger data after it closes', 'A stream job with monthly tumbling windows and a tight watermark', 'A Redis counter incremented by every payment and refund event', 'Hopping 30-day windows updated every hour on the payment stream'], a: 0, no: [null, 'A tight watermark drops refunds that arrive days late, so the total is wrong. Streams fit fast answers that can tolerate small gaps.', 'An in-memory counter cannot be audited or rerun, and a lost or doubled event changes it for good. Redis fits rate limits and live tallies.', 'A sliding 30 days is not a calendar month, and late refunds still miss their window. Hopping windows fit trailing dashboards.'], why: 'Batch gives slow but complete answers: once the month closes, a job over all ledger rows sees every late refund, and can simply be rerun if something is fixed.' },
  { id: 'qb-batch6', c: 'batch', type: 'mc', q: 'A nightly job computes product recommendations. Why write a fresh output table and swap it in, instead of updating the live table row by row?', opts: ['Row updates break foreign keys while the job is running', 'A failed run leaves the old data intact, and a rerun is clean', 'Row-by-row updates cannot be retried, as they are not idempotent', 'Live tables cannot take writes while users are reading them'], a: 1, no: ['Recommendations rarely have foreign keys, and constraints are checked per statement anyway. The real risk is a half-finished job.', null, 'Setting a row to a computed value is idempotent; it can be retried. The problem is a crash leaving some rows new and some old.', 'Databases handle concurrent reads and writes routinely with MVCC. Millions of updates can slow live traffic, but they do not block reads.'], why: 'Writing fresh output and swapping it atomically keeps batch jobs rerunnable: a crash leaves yesterday\'s table serving and the partial output is discarded. Updating in place leaves a half-old, half-new table.' },
  // keydesign: Partition & Sort Keys
  { id: 'qb-keydesign1', c: 'keydesign', type: 'mc', q: 'You write-shard a hot day key into date#0 to date#9. What does reading all of one day\'s items now cost?', opts: ['One query: the store ignores the suffix when hashing the key', 'A scan of the whole table, since the date is no longer a key', 'Ten queries, one per suffix, merged by the client', 'One lookup in a global index that sharding now requires'], a: 2, no: ['The suffix is the point: each date#n hashes to a different partition. If it were ignored, the writes would not spread.', 'Each date#n is still a partition key you can query directly. A full scan is only needed if you do not know the keys.', null, 'No extra index is needed: the ten keys are known. A global secondary index serves queries on a different attribute.'], why: 'Write sharding trades cheap writes for scatter-gather reads: the reader queries all ten suffixes and merges them. That is why you only shard keys that are actually hot.' },
  { id: 'qb-keydesign2', c: 'keydesign', type: 'mc', q: 'A chat app\'s main query is "the last 50 messages in a chat". Which Cassandra keys fit?', opts: ['Partition key user ID, clustering column chat ID', 'Partition key message ID, so messages spread evenly', 'Partition key message time, clustering column chat ID', 'Partition key chat ID, clustered by time, newest first'], a: 3, no: ['A chat has many users, so its messages are spread over every member\'s partition. User ID fits "my chats" lists.', 'Even spread, but the 50 messages now live on 50 partitions. Unique IDs suit lookups of one item at a time.', 'Every new message goes to the current time\'s partition, a hot spot, and one chat is spread across all of time.', null], why: 'Key from the access pattern: putting a chat\'s messages in one partition, sorted by time descending, makes the query one short range read. Very busy chats can add a time bucket to the partition key.' },
  { id: 'qb-keydesign3', c: 'keydesign', type: 'mc', q: 'An orders table is keyed by customer ID with order time as sort key. You need "a customer\'s orders over $100". Which index fits?', opts: ['A local secondary index on amount inside each partition', 'A global secondary index partitioned by order amount', 'A scan of the whole table filtering on the amount', 'A second table keyed by amount, written alongside'], a: 0, no: [null, 'Partitioned by amount, it groups orders from all customers by price, so one customer\'s orders are scattered. Global indexes fit queries without the base key.', 'A full scan reads every order of every customer. Filters run after reading, so you pay for all of it.', 'The wrong key, and writing two tables from the app is a dual write that can drift. GSIs exist so the store does this for you.'], why: 'The query still has the partition key (customer), so a local index on amount sorts that customer\'s orders by price beside the data, read as one range. In DynamoDB an LSI must be defined when the table is created.' },
  { id: 'qb-keydesign4', c: 'keydesign', type: 'mc', q: 'A query on a local secondary index is fast with the partition key but slow at scale without it. Why?', opts: ['Local indexes are rebuilt from scratch on each query', 'Local indexes lag, so queries wait for them to catch up', 'It must ask every partition and then merge the answers', 'Local indexes live on one coordinator that is overloaded'], a: 2, no: ['Local indexes are updated with each write, beside the data, so nothing is rebuilt at read time.', 'Lag is the trade-off of a global index, which is updated asynchronously. A local one is updated with its partition.', null, 'Each partition keeps its own piece of the index, so there is no single index node. That is what makes them local.'], why: 'Each partition indexes only its own items. Without the partition key, the store cannot know which partitions hold matches, so it scatters the query to all of them and gathers the results.' },
  { id: 'qb-keydesign5', c: 'keydesign', type: 'mc', q: 'Orders are partitioned by customer. You need "this customer\'s pending orders, newest first" as one range read. Which sort key?', opts: ['timestamp#status, so the newest orders sort first', 'A random UUIDv4 per order, so items spread evenly', 'Order ID, with status filtered after the items are read', 'status#timestamp, for example PENDING#2026-10-18T09:00'], a: 3, no: ['With the time first you cannot select one status with a prefix; pending orders are mixed among all others.', 'A sort key orders items inside a partition; it does not spread load. Random values destroy any useful range.', 'Filtering after reading pays for every order the customer has. Filters trim results, they do not narrow the read.', null], why: 'A composite sort key puts the equality field first and the range field second, so "begins with PENDING#" read in reverse returns pending orders newest first in one short range.' },
  { id: 'qb-keydesign6', c: 'keydesign', type: 'mc', q: 'Orders are keyed by customer ID. A new query appears: "all orders for a product". What is the usual fix in DynamoDB?', opts: ['Scan the table each night into a product report', 'Change the partition key of the table to product ID', 'Add a global secondary index keyed by product ID', 'Add a local secondary index on product ID'], a: 2, no: ['A nightly scan is stale and reads the whole table. It fits analytics, ideally in a warehouse, not a live query.', 'That breaks the main query, "a customer\'s orders", which now spans every product partition.', null, 'A local index stays inside each customer\'s partition, so finding a product still asks every partition. It also must exist at table creation.'], why: 'A global secondary index is partitioned by its own key, so "orders for product X" reads one place. The store keeps it updated asynchronously, so it can lag the base table slightly.' },
  // rebalance: Rebalancing Partitions
  { id: 'qb-rebalance1', c: 'rebalance', type: 'mc', q: 'Keys are placed by hash(key) mod N on 4 nodes. You add a fifth node. Roughly what share of keys has to move?', opts: ['About 20%', 'About 25%', 'Roughly 50%', 'About 80%'], a: 3, no: ['That is the ideal: the new node takes a fifth of the data. Fixed partitions or consistent hashing get close to it.', 'A quarter is the share each old node held. Mod N reshuffles far more than one node\'s worth.', 'Half would already be bad, but mod N is worse: a key stays put only when its hash mod 4 equals its hash mod 5.', null], why: 'A key stays only when hash mod 4 equals hash mod 5, which is 4 of every 20 values, so about 80% move. That is why systems use many fixed partitions and move whole ones instead.' },
  { id: 'qb-rebalance2', c: 'rebalance', type: 'mc', q: 'You pick a fixed partition count up front. What goes wrong if you pick far too many, say 100,000 on 10 nodes?', opts: ['Keys move partitions more often as nodes join', 'Per-partition overhead adds up across the cluster', 'Hot keys get worse, since each partition is smaller', 'Hash mod N no longer spreads keys evenly over them'], a: 1, no: ['With fixed partitions no key ever changes partition; only whole partitions move between nodes.', null, 'A hot key is one key on one partition either way. Partition size does not change how hot a single key is.', 'With 100,000 partitions, keys spread more evenly, not less. Mod N is a problem when N is the number of nodes.'], why: 'Each partition costs files, metadata, open handles and leader elections, so a huge count wastes resources. Too few is the opposite trap: partitions grow huge and you cannot use more nodes than partitions.' },
  { id: 'qb-rebalance3', c: 'rebalance', type: 'mc', q: 'After a rebalance, a client with an old partition map sends a request to a node that no longer owns that partition. What usually happens?', opts: ['The old node answers from the stale copy it still keeps on disk', 'The request fails until the client is restarted', 'The client re-hashes the key with the new node count', 'The node forwards it, or redirects the client to the owner'], a: 3, no: ['Old copies are deleted once the move completes, and serving them would return stale data.', 'Clients refresh their map from the routing metadata, usually on that very error. No restart is needed.', 'With fixed partitions the key\'s partition never changes, so there is nothing to re-hash. Only the partition\'s owner moved.', null], why: 'Requests reach the right node via a smart client, a routing tier, or any node that forwards. On a miss the node forwards or replies "moved" (like Redis Cluster\'s MOVED), and the client updates its map.' },
  { id: 'qb-rebalance4', c: 'rebalance', type: 'mc', q: 'In systems like HBase, SolrCloud and older Kafka, where does the authoritative partition-to-node map usually live?', opts: ['In a coordination service such as ZooKeeper or etcd', 'In each client\'s config file, updated with each deploy', 'In a Redis cache that the routing tier reads from', 'On the node with the lowest ID, picked at startup'], a: 0, no: [null, 'Config files go stale the moment a partition moves. Static config fits settings that rarely change.', 'A cache can speed up lookups but is memory first and not the agreed record. The map must be durable and consistent.', 'A node picked by lowest ID with no consensus can split brain in a partition. Electing a controller is done through consensus.'], why: 'The map must be consistent across the cluster, so it lives in a consensus-backed store (ZooKeeper, etcd, or Kafka\'s KRaft controllers). Routers and clients watch it for changes; some systems spread it by gossip instead.' },
  { id: 'qb-rebalance5', c: 'rebalance', type: 'mc', q: 'You bulk-load 2 TB into a brand-new HBase table that starts as a single region. What goes wrong, and what is the usual fix?', opts: ['Regions split by key count, so 2 TB makes too many; raise it', 'Writes all hit one region until it splits; pre-split the table', 'HBase hashes keys unevenly; place rows by hash mod N instead', 'HBase moves rows one at a time; group those moves into batches'], a: 1, no: ['HBase splits by region size, and many regions is the goal here. Raising the threshold would keep the hot spot longer.', null, 'Hash mod N reshuffles almost every key when a node is added. HBase uses key ranges so scans stay efficient.', 'HBase moves whole regions, not rows. Moving rows one at a time is not how any of these systems rebalance.'], why: 'With dynamic splitting, a new table has one region on one server, so the load hammers it until splits catch up. Pre-splitting creates many regions up front so writes spread from the start.' },
  { id: 'qb-rebalance6', c: 'rebalance', type: 'mc', q: 'A rebalance that moves 5 TB to a new node doubles p99 latency for live traffic. Best mitigation?', opts: ['Throttle the transfer and move a few partitions at a time', 'Switch to hash mod N so that less data has to be moved', 'Pause all writes to the cluster until the move is done', 'Raise the partition count mid-move so each copy is smaller'], a: 0, no: [null, 'Mod N moves most of the data whenever N changes, so it makes this far worse.', 'Pausing writes is an outage. Write freezes fit short cutovers, not a move that takes hours.', 'Changing a fixed partition count remaps keys, which is a bigger move. Splitting suits systems built for it, like HBase regions.'], why: 'Moving partitions competes with live requests for disk and network. Rate limiting the copy and moving a few partitions at a time keeps p99 steady; it takes longer, which is why it is done gradually with a human watching.' },
  // toolpick: Picking the Right Tool
  { id: 'qb-toolpick1', c: 'toolpick', type: 'mc', q: 'An app stores user-uploaded videos up to 2 GB each, plus metadata that is queried by owner and date. Where should they go?', opts: ['Postgres bytea columns, so file and metadata share a transaction', 'Elasticsearch documents with each video stored base64-encoded', 'Redis with persistence on, keyed by video ID for fast reads', 'S3 for the files, and a row per video in Postgres'], a: 3, no: ['Gigabyte blobs bloat the database, its backups and replication. Postgres fits the metadata, not the bytes.', 'Base64 grows files by a third and search indexes are not built for blobs. Elasticsearch fits full-text and faceted search.', 'Gigabytes of video in memory is very expensive, and Redis is memory first. It fits caches, counters and short-lived state.', null], why: 'Blob stores like S3 hold large files cheaply and durably; the database keeps a small row with the object key and metadata, so queries stay fast. Clients can upload straight to S3 with presigned URLs.' },
  { id: 'qb-toolpick2', c: 'toolpick', type: 'mc', q: 'Product wants "average session length by country by day" over 3 years of events, about 20 billion rows. Postgres queries time out. Best move?', opts: ['Add a B-tree index on country and day in Postgres', 'Load the events into a column store like ClickHouse', 'Cache the query results in Redis for an hour at a time', 'Move the events into DynamoDB, keyed by country'], a: 1, no: ['An index helps find a few rows. An average over billions of rows still reads them all, row by row.', null, 'A cache only helps repeat queries, and the first one still times out. Caches fit hot reads that already work.', 'DynamoDB serves key lookups, not aggregations over billions of items. It fits huge scale with key-based access.'], why: 'Analytics scans a few columns over billions of rows. Column stores and warehouses (ClickHouse, BigQuery, Snowflake) read only those columns, compressed, in parallel, which is what OLAP needs; Postgres stays the OLTP source.' },
  { id: 'qb-toolpick3', c: 'toolpick', type: 'mc', q: 'You need a per-user API rate limit shared across 50 API servers handling 100,000 requests a second. What fits?', opts: ['A Postgres row per user, updated in each request\'s transaction', 'A Kafka topic of requests, counted by a consumer downstream', 'Redis counters, using INCR with an expiry per user window', 'An in-memory counter on each of the 50 API servers'], a: 2, no: ['A row lock per request on hot users makes them queue, and a disk-backed transaction per call is slow. Postgres fits durable records.', 'The consumer counts after the fact, too late to block a request. Kafka fits durable, replayable event streams.', null, 'Each server sees only its share, so a user gets 50 times the limit. Local counters fit per-instance protection.'], why: 'Rate limits need a fast shared counter with expiry, which is exactly what Redis gives: INCR and EXPIRE are atomic and in memory. Losing a few counts on a crash is acceptable for a limit.' },
  { id: 'qb-toolpick4', c: 'toolpick', type: 'mc', q: 'A team plans to keep shopping carts only in Redis, with default settings, as the system of record. What is the main risk?', opts: ['Redis cannot store nested data like a cart and its items', 'Single-key reads from Redis are slower than from Postgres', 'Carts leak between users without row-level security', 'It is memory first, so a crash can lose recent writes'], a: 3, no: ['Hashes, lists or JSON strings hold a cart fine. Data shape is not the problem.', 'Redis serves single keys from memory, usually faster than Postgres. Speed is why people reach for it.', 'Isolation between users comes from keying by user ID. Row-level security is a Postgres feature for multi-tenant tables.', null], why: 'By default Redis persists by periodic snapshots, so a crash loses writes since the last one. As a cache that is fine; as the only copy of carts or orders it is a risk, so keep a durable store as the source of truth.' },
  { id: 'qb-toolpick5', c: 'toolpick', type: 'mc', q: 'A startup with 5,000 orders a day needs orders, refunds and customers, with finance adding new join queries every week. What store fits?', opts: ['Postgres, with indexes for the common queries', 'DynamoDB, with a new global index for each filter', 'Cassandra, with one denormalised table per query', 'Elasticsearch as both the store and the query engine'], a: 0, no: [null, 'DynamoDB has no joins, and each new question needs a new index or table. It fits huge scale with known key-based access.', 'A table per query means a rewrite for each new question, and no joins. Cassandra fits heavy writes with fixed patterns.', 'Elasticsearch has no transactions or joins, and its documents are derived data. It fits full-text and faceted search.'], why: 'Postgres is the default: relational, transactional and good at ad-hoc queries, and 5,000 orders a day is tiny for it. Reach for specialised stores when an access pattern outgrows it.' },
  { id: 'qb-toolpick6', c: 'toolpick', type: 'mc', q: 'Sensors send 2 million readings a second. The only read is "one sensor\'s readings over a time range". What fits as the main store?', opts: ['Postgres, with one B-tree index on sensor and time', 'Elasticsearch, with a separate index for every sensor', 'Cassandra, partitioned by sensor and day, sorted by time', 'Redis sorted sets, one per sensor, as the only copy'], a: 2, no: ['A single Postgres primary struggles with millions of writes a second. Postgres fits moderate write rates with flexible queries.', 'Millions of tiny indexes overwhelm the cluster, and search indexes are a poor fit for heavy raw writes.', null, 'Months of readings in memory are costly, and memory first storage risks loss. Sorted sets fit leaderboards and recent windows.'], why: 'Cassandra spreads heavy writes over many nodes, and a partition of one sensor per day with readings clustered by time makes each read one sequential range. The day in the key keeps partitions from growing forever.' }
);
